"use strict";
function delp(obj, propName) { var a = obj[propName]; delete obj[propName]; return a; }
function htmlEncode(s, newLineToBr) {
    if (!s) return s; 
    s = s.replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/'/g, '&#39;')
        .replace(/"/g, '&#34;');
    if (newLineToBr === true) s = s.replace(/(\r\n)|[\n\r]/g, "<br>");
    return s;
}
function namespace(namespace, obj, opts) {
    /// <summary>Vytvori zanoreny namespace v globalnim scope a vrati odkaz na nej (napr."Gordic.Domain.Class")</summary>
    /// <param name="namespace" type="string">napr."Gordic.Domain.Class"</param>
    /// <param name="obj" type="any">objekt/hodnota, ktera se ma automaticky vlozit do vytvoreneho/existujiciho namespace</param>
    /// <param name="opts" type="object">Doplnujici parametry specifikujici chovani funkce namespace </param>
    /// <returns type=""></returns>
    opts = $.extend({ }, opts);
    var object = this || window;
    if (!namespace) return obj;

    var tokens = namespace.split(".")
    var token;
    while (token = tokens.shift()) { 
        if (tokens.length === 0 && typeof obj !== "undefined")
            return $.isPlainObject(object[token]) && $.isPlainObject(obj) ? $.extend(object[token], obj) : object[token] = obj;
        if (!$.isPlainObject(object[token])) object[token] = Object.create(null);
        object = object[token];
    }
    return object;
}
function translateParams(args, names, defaults) {
  /// <summary>funkce pro vytvoreni objektu z pole hodnot ([1,3,5]+["a","b","c"]=>{a:1,b:3,c:5}). 
  /// <para>Pokud je prvni hodnota PlainObject objekt, automaticky pouzije jako vysledny objekt a provede se extend jeji hodnoty kazdym dalsim objektem (funkce nikdy nemeni vstupni parametry)</para>
  /// <para>Urceno pro vytvareni override metod, ktere mohou mit na vstupu bud plny objekt(y), nebo seznam neobjektovych parametru.</para>
  /// </summary>
  /// <param name="args" type="Array">pole hodnot (hodnoty objektu)</param>
  /// <param name="names" type="Array">pole nazvu (klice objektu)</param>
  /// <param name="defaults" type="object">vychozi hodnoty. Undefined a null se ignoruji ($.extend chovani)</param>
  /// <returns type="object"></returns>
  defaults = $.extend({}, defaults); 
  if (!args || !args.length) return defaults;
  var i = 0;
  if ($.isPlainObject(args[i])) {
    do { $.extend(true, defaults, args[i]) } 
    while ($.isPlainObject(args[++i]))
    return defaults;
  }
  for (i = 0; i < Math.min(args.length, names.length) ; i++) defaults[names[i]] = args[i];
  return defaults;
}

/**
 * @callback arrayMergeComparator
 * @param {*} originalItem puvodni prvek
 * @param {*} newItem novy prvek
 * @returns {bool?} 
 *      true  ... prvky jsou stejne, novy prvek nahradi puvodni
 *      false ... prvky jsou rozdilne, novy prvek bude pridan na konec 
 *      null  ... novy prvek se ignoruje a do pole se neprida
 * 
 */

/**
 * Funkce pro merge poli na zaklade custom porovnavace
 * 
 * @param {arrayMergeComparator} comparator porovnava prvky originalniho (vysledneho) pole s nove vkladanymi prvky a ridi co se s nimi stane 
 * @param {...Array} array seznam poli ke slouceni
 */
function arrayMerge(comparator) {
    comparator = comparator || function (origIt, newIt) { return origIt === newIt; };
    var result = $.isArray(arguments[1]) ? Array.prototype.slice.call(arguments[1]) : [];
    for (var i = 2; i < arguments.length; i++) {
        var arg = arguments[i];
        if ($.isArray(arg))
            for (var j = 0; j < arg.length; j++) { 
                var q = false;
                for (var k = 0; k < result.length; k++) {
                    q = comparator(result[k], arg[j]);
                    if (q === true) { result[k] = arg[j]; break; }  // shoda -> replace
                    else if (q === null) break;                              // shoda -> nelze nahradit       
                    else if (q !== false) { result[k] = q; break; }          // shoda -> replace custom
                }
                if (q === false) result.push(arg[j]);               // vsechny comparatory vratily false (vcetne posledniho) => unikat => pridat
            }
    }
    return result; 
}
function arraySubstract(comparator) {
    comparator = comparator || function (origIt, newIt) { return origIt === newIt; };
    var args = Array.prototype.slice.call(arguments);
    if (!$.isArray(args[1])) return [];
    return args[1].filter(function (it) {
        for (var i = 2; i < args.length; i++) {
            var arg = args[i];
            if ($.isArray(arg))
                for (var j = 0; j < arg.length; j++) {
                    var q = comparator(it, arg[j]);
                    if (q === true) return false;           // shoda -> delete
                    else if (q === null) return true;       // shoda -> nelze smazat
                }
        }
        return true; 
    });
}
function groupsMatch(groupSet, groupFilter) {
    groupSet = $.isArray(groupSet) ? groupSet : typeof groupSet === "string" ? groupSet.split(/[\.,\s]+/g).filter(function (it) { return !!it; }) : [];
    groupFilter = $.isArray(groupFilter) ? groupFilter : typeof groupFilter === "string" ? groupFilter.split(/[\.,\s]+/g).filter(function (it) { return !!it; }) : [];

    if (groupSet.length === 0 && groupFilter.length > 0) return false; 
    return !!(groupFilter.length === 0 || groupFilter.filter(function (seeking) { return groupSet.indexOf(seeking) >= 0; }).length > 0);
}
function cleanObject(obj) {
    for (var n in obj)
        if ($.isPlainObject(obj[n])) {
            cleanObject(obj[n]);
            if ($.isEmptyObject(obj[n])) delete obj[n];
        } else if (obj[n] == null) delete obj[n];
    return obj; 
}

function queryStringToObj(qs) {
    /// <summary>Vstup (nebo URL querystring) ve tvaru "name1=val1&name2=val2&name3[name4]=val3" prevede na objekt { name1: val1, name2: val2, name3:{name4: val3} }</summary>
    /// <param name="qs" type="string">vstupni data (NULL pro pouziti URL querystringu)</param>
    /// <returns type="object"></returns>
    qs = (qs == null ? location.search.slice(1) : qs);
    qs = (qs || "").trim();

    var result = {}, coerce_types = { 'true': !0, 'false': !1, 'null': null }, protectionObj = {};
    if (qs) {

        // Iterate over all name=value pairs.
        $.each(qs.replace(/\+/g, ' ').split('&'), function (j, v) {
            var param = v.split('='),
                key = decodeURIComponent(param[0]),
                val,
                cur = result,
                i = 0,

                // If key is more complex than 'foo', like 'a[]' or 'a[b][c]', split it
                // into its component parts.
                keys = key.split(']['),
                keys_last = keys.length - 1;

            // If the first keys part contains [ and the last ends with ], then []
            // are correctly balanced.
            if (/\[/.test(keys[0]) && /\]$/.test(keys[keys_last])) {
                // Remove the trailing ] from the last keys part.
                keys[keys_last] = keys[keys_last].replace(/\]$/, '');

                // Split first keys part into two parts on the [ and add them back onto
                // the beginning of the keys array.
                keys = keys.shift().split('[').concat(keys);

                keys_last = keys.length - 1;
            } else {
                // Basic 'foo' style key.
                keys_last = 0;
            }

            // TS:241112 - T38178 - klice jako __proto__ se budou ignorovat
            if (keys.some(k => typeof protectionObj[k] !== "undefined")) return;

            // Are we dealing with a name=value pair, or just a name?
            if (param.length === 2) {
                val = decodeURIComponent(param[1]);

                val = /*val && !isNaN(val) ? +val              // number  //TS: 201023 - zakaz ciselnych typu; je potreba zachovavat formaty u leadingZeroes ucetnich slov, nks, apod. "00000012" a radeji nebudeme konvertovat pripadne decimaly na number
                     :*/ val === 'undefined' ? undefined         // undefined
                     : coerce_types[val] !== undefined ? coerce_types[val] // true, false, null
                     : val; 

                if (keys_last) {
                    // Complex key, build deep object structure based on a few rules:
                    // * The 'cur' pointer starts at the object top-level.
                    // * [] = array push (n is set to array length), [n] = array if n is 
                    //   numeric, otherwise object.
                    // * If at the last keys part, set the value.
                    // * For each keys part, if the current level is undefined create an
                    //   object or array based on the type of the next keys part.
                    // * Move the 'cur' pointer to the next level.
                    // * Rinse & repeat.
                    for (; i <= keys_last; i++) {
                        key = keys[i] === '' ? cur.length : keys[i];
                        cur = cur[key] = i < keys_last
                          ? cur[key] || (keys[i + 1] && isNaN(keys[i + 1]) ? {} : [])
                          : val;
                    }

                } else {
                    // Simple key, even simpler rules, since only scalars and shallow
                    // arrays are allowed.

                    if ($.isArray(result[key])) {
                        // val is already an array, so push on the next value.
                        result[key].push(val);

                    } else if (result[key] !== undefined) {
                        // val isn't an array, but since a second value has been specified,
                        // convert val into an array.
                        result[key] = [result[key], val];

                    } else {
                        // val is a scalar.
                        result[key] = val;
                    }
                }

            } else if (key) {
                // No value was defined, so set something meaningful.
                result[key] = '';
            }
        });
    }
        
    return JSON.parse(JSON.stringify(result));
};
function b64EncodeUnicode(str) {
    // first we use encodeURIComponent to get percent-encoded UTF-8,
    // then we convert the percent encodings into raw bytes which
    // can be fed into btoa.
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g,
        function toSolidBytes(match, p1) {
            return String.fromCharCode('0x' + p1);
        }));
}
function b64DecodeUnicode(str) {
    // Going backwards: from bytestream, to percent-encoding, to original string.
    return decodeURIComponent(atob(str).split('').map(function (c) {
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
}
Function.prototype.inheritsFrom = function (baseClass) {
    this.prototype = Object.create(baseClass.prototype);
    this.prototype.constructor = this;

    if (baseClass.constructor) this.prototype._base = function () {
        //NOTE (BM): Kompatibilita viz T37347 (Selectory psane ve fields.js)
        const o = new baseClass(...arguments);
        for (let k in o) {
            if (k === "constructor") continue;
            const descriptor = Object.getOwnPropertyDescriptor(o, k);
            if (descriptor) Object.defineProperty(this, k, descriptor);
        }
        return o;
    } 
    else this.prototype._base = baseClass;             // tohle nefunguje dobre pokud je dedicnost pres vic nez jednoho potomka, nikdy nebude v ES5
    this.prototype.base = baseClass.prototype;

    return this;
}
function CreateClass(inherits, proto) {
    /// <signature>
    /// <summary>Inline konstruktor trid.</summary>
    /// <param name="proto" type="Object">objekt s metodami a vlastnostmi prototypu nove tridy. Muze obsahovat metodu "_constructor"</param>
    /// <returns type="Function">knstruktor nove tridy</returns>
    /// </signature>
    /// <signature>
    /// <summary>Inline konstruktor trid.</summary>
    /// <param name="inherits" type="Function">predek (napr.: Gordic.Data.Readers.Base)</param>
    /// <param name="proto" type="Object">objekt s metodami a vlastnostmi prototypu nove tridy. Muze obsahovat metodu "_constructor"</param>
    /// <returns type="Function">knstruktor nove tridy</returns>
    /// </signature>
    if (typeof inherits !== "function") { proto = inherits; inherits = null; }
    var constructor = proto._constructor || function () { inherits && inherits.apply(this, this.arguments); };
    proto._constructor = undefined;
    if (inherits) constructor.inheritsFrom(inherits);
    $.extend(constructor.prototype, proto);
    return constructor; 
}

