function uriCombine(base, relative) {
    if (!relative) return base;  // zadna cesta
    if (!base || relative.startsWith("/") || relative.indexOf("://") > 0) return relative;  // absolutni cesta 
    var bqi = base.indexOf("?");
    if (bqi > 0) return base.replace("?", (base.charAt(bqi - 1) === "/" ? "" : "/") + relative + (relative.indexOf("?") >= 0 ? "&" : "?"));
    return base + (base.endsWith("/")?"":"/") + relative;
}

