/* ======================================================= */
/* GTaskProcessor - podpora pro asynchronni udalosti, ktere nastavaji casteji nez je zdrave je vyhodnocovat a navzajem se nahrazuji */
/* ======================================================= */


function GTaskProcessor(opts) {
    this._stream = []; // {tag: "save", task: func, working: null, deferred: $.Deferred() }
    this.working = null;
    this._preTimer = null
    this._postTimer = null;
    this.options = $.extend({
        waiting: 0,          // [ms] cas po ktery se ceka jestli neprijde dalsi pozadavek pred vykonanim libovolneho tasku
        waitingReset: true,  // priznak, ze dalsi pozadavek vyresetuje waitingTimer (false = ze fronta zpracuje pozadavky alespon kazdych waiting)
        delay: 5000,         // [ms] cas po ktery se ceka za naposledy vyrizenym taskem nez se muze pustit dalsi
        tags: {}  // save: { waitFor: "clear", override: "save load", run: function () { }, immediate: false}
    }, opts);
}

GTaskProcessor.prototype.process = function (tag, run, immediate) {
    var _this = this;

    if (typeof tag !== "string") { immediate = run; run = tag; tag = "unspecified"; }
    if (!$.isFunction(run)) { immediate = run; run = null; }
    if (typeof immediate !== "boolean") immediate = false; 

    var tagOpts = $.extend({ waitFor: "", override: tag }, this.options.tags[tag]);

    run = run || tagOpts.run;
    if (!run) return;

    // overrides - znicime predchozi pozadavky
    this._stream = this._stream.filter(function (task) {
        var rem = tagOpts.override.split(" ").indexOf(task.tag) >= 0;
        if (rem && task.working && task.working.abort) task.working.abort();
        return rem === false;
    });

    // pridame do fronty
    if (this.options.waiting && (!this._preTimer || this.options.waitingReset)) {
        window.clearTimeout(this._preTimer);
        this._preTimer = window.setTimeout(function () { _this._preTimer = null; _this.check(); }, this.options.waiting);
    }
    var newTask = { tag: tag, run: run, working: null, deferred: $.Deferred(), immediate: immediate };
    if (immediate) { this._stream.unshift(newTask); this.resetTimers(); }
    else this._stream.push(newTask);

    // waitFor - presuneme zavysle tasky na konec
    var moved = [];
    this._stream = this._stream.filter(function (task) {
        var opts = _this.options.tags[task.tag];
        if (opts && opts.waitFor && opts.waitFor.split(" ").indexOf(tag) >= 0) { moved.push(task); return false; }
        return true; 
    }).concat(moved);

    // spustime prvni task
    this.check(); 
}
GTaskProcessor.prototype.clear = function () {
    this._stream = this._stream.filter(function (task) {
        if (task.working && task.working.abort) task.working.abort();
        else task.deferred.reject("abort");

        return false;
    });
    this.resetTimers(); 
}
GTaskProcessor.prototype.resetTimers = function () {
    window.clearTimeout(this._preTimer); this._preTimer = null;
    window.clearTimeout(this._postTimer); this._postTimer = null;
}

GTaskProcessor.prototype.check = function () {
    var _this = this; 

    // spustime prvni task
    if (!this.working && this._stream.length && !this._preTimer && (!this._postTimer || this._stream[0].immediate)) {
        var task = this._stream.pop();
        task.working = task.run();
        if (!task.working) task.working = $.Deferred().resolve().promise();
        this.working = task.working.then(task.deferred.resolve, task.deferred.reject);
        this.working.always(function () {
            _this.working = null;
            _this._postTimer = window.setTimeout(function () { _this._postTimer = null; _this.check(); }, _this.options.delay);
        });
    }
}





