GEvents.prototype.dispatchEvent = function (eventName, args, options) {
///<summary>zaregistruje, nebo vyvola udalost (dle argumentu) (dispatch mezi on a trigger</summary>
  if (typeof (args) == "function")
    return this.on(eventName, args, options);
  else if (args.length == 1 && typeof (args[0]) == "function")
    return this.on(eventName, args[0], options);
  else
    return this.trigger(eventName, args, options);
}





