/* GACTIONLIST */
/* ======================================================= */

function GActionList(actions, persistentParams) {
  /// <summary>Vytvori pomocnou tridu pro seznam akci (pro jednodussi zadavani)</summary>
  /// <param name="actions" type="object">prvotni akce ve tvaru {actSchvalit:{caption:'', run:function(){}, ...}, actZaradit:{caption:'', run:function(){}, ...}} nebo castecny/uplne actionlist (napr. content.actions)</param>
  /// <param name="persistentParams" type="object">objekt persistentnich parametru, ktere budou pridany do kazde akce, ktera bude do tohoto listu pridana</param>
  this.persistentParams = persistentParams || {};
  this.addRange(actions);
}

GActionList.prototype.add = function (name, caption, params, run) {
    /// <signature>
    /// <summary>pridani akce do seznamu akci</summary>
    /// <param name="params" type="object">parametry akce (neuvedene povinne budou doplneny defaultem)</param>
    /// <returns type="GAction">vytvorenou akci</returns>
    /// </signature>
    /// <signature>
    /// <summary>pridani akce do seznamu akci</summary>
    /// <param name="action" type="GAction">existujici instance akce</param>
    /// <returns type="GAction">predanou akci</returns>
    /// </signature>
    /// <signature>
    /// <summary>pridani akce do seznamu akci</summary>
    /// <param name="caption" type="string">text/navetsi akce</param>
    /// <param name="run" type="function">funkce ke spusteni</param>
    /// <returns type="GAction">vytvorenou akci</returns>
    /// </signature>
    /// <signature>
    /// <summary>pridani akce do seznamu akci</summary>
    /// <param name="name" type="string">nazev akce</param>
    /// <param name="caption" type="string">text/navetsi akce</param>
    /// <param name="run" type="function">funkce ke spusteni</param>
    /// <returns type="GAction">vytvorenou akci</returns>
    /// </signature>
    /// <signature>
    /// <summary>pridani akce do seznamu akci</summary>
    /// <param name="caption" type="string">text/navetsi akce</param>
    /// <param name="params" type="object">dalsi parametry akce</param>
    /// <param name="run" type="function">funkce ke spusteni</param>
    /// <returns type="GAction">vytvorenou akci</returns>
    /// </signature>
    /// <signature>
    /// <summary>pridani akce do seznamu akci</summary>
    /// <param name="name" type="string">nazev akce</param>
    /// <param name="caption" type="string">text/navetsi akce</param>
    /// <param name="params" type="object">dalsi parametry akce</param>
    /// <param name="run" type="function">funkce ke spusteni</param>
    /// <returns type="GAction">vytvorenou akci</returns>
    /// </signature>
    var args = [].slice.call(arguments); // bugfix IE9 (setovani vstupnich promennych zaroven meni arguments[])
    var act;
    if (typeof args[1] === "function") {
        name = "actAnonymous" + (++window.guid).toString();
        caption = args[0];
        params = {};
        run = args[1];
    } else if (typeof args[2] === "function") {
        if ($.isPlainObject(args[1])) {
            name = "actAnonymous" + (++window.guid).toString();
            caption = args[0];
            params = args[1];
        } else
            params = {};
        run = args[2];
    } else if (args.length === 1 && args[0] instanceof GAction) {
        act = $.extend(args[0], this.persistentParams);
        name = act.name; 
    } else if ($.isPlainObject(args[0])) {
        name = args[0].name || "actAnonymous" + (++window.guid).toString();
        params = args[0];
        caption = args[0].caption || "";
        run = args[0].run || $.noop;
    }

    return this[name] = act || new GAction($.extend({}, this.persistentParams, params, { name: name, caption: caption, run: run }));
};

GActionList.prototype.addRange = function (actions) {
    /// <summary>Prida seznam akci (pro jednodussi zadavani)</summary>
    /// <param name="actions" type="object">prvotni akce ve tvaru {actSchvalit:{caption:'', run:function(){}, ...}, actZaradit: new GAction(), actRun: function() { }...}} nebo castecny/uplne actionlist (napr. content.actions)</param>
    /// <returns type="GActionList">list</returns>
    if (actions)
        if (actions instanceof GActionList) actions = actions.getActions(); 
        if ($.isArray(actions)) {
            for (var i = 0; i < actions.length; i++)
                this.add(actions[i]);
        } else {
            for (var k in actions)
                if (actions[k] instanceof GAction)
                    this[k] = $.extend(actions[k], this.persistentParams);
                else if ($.isPlainObject(actions[k]))
                    this[k] = new GAction($.extend(actions[k], this.persistentParams, { name: k }));
                else if ($.isFunction(actions[k]))
                    this[k] = this.add(k, k, actions[k]);

        }

    return this;
};

GActionList.prototype.getActions = function (filter) {
    /// <summary>Vrati Array akci uchovanych s listu</summary>
    /// <param name="filter">pripadna filtrovaci funkce (ve formatu Array.filter)</param>
    /// <returns type="Array">pole akci</returns>
    var arr = [];
    for (var k in this) if (this[k] instanceof GAction) arr.push(this[k]);
    return ($.isFunction(filter) ? arr.filter(filter) : arr);
};

GActionList.prototype.createBar = function (normalBar, oppositeBar, fav) {
    /// <signature>
    /// <summary>pomucka pro vytvoreni definice menu/commands z existujicich akci
    /// <para>Jako polozky pole lze pouzit:</para>
    /// <para>1. 'actAkce1' ... nazev akce</para>
    /// <para>2. 'Dokumenty' ... staticky text</para>
    /// <para>3. 'actAkce2*' ... akce / static oznaceny jako favorite</para>
    /// <para>3a.'actAkce2!' ... akce / static oznaceny jako primary</para>
    /// <para>3b.'<actAkce2' ... akce / static umisteny jako opposite (stejne jako "<actAkce2")</para>
    /// <para>3b.'>actAkce2' ... autofocus</para>
    /// <para>4. '-' ... separator</para>
    /// <para>5. content.actions.actSchvalit ... instance existujici akce</para>
    /// <para>6. new GAction() ... instance nove akce</para>
    /// <para>7. { type:'html', html:'<p></p>'} ... normalni menuparam</para>
    /// <para>8. ['Ulozit jako', 'actSaveAs', 'actSaveAsXml'] ... static se dvema children (lze pouzit vse vyse zminovane)</para>
    /// </summary>
    /// <param name="definition" type="Array">pole akci v menu</param>
    /// <param name="favorite" type="Boolean">(default=false) priznak, ze vsechny pridavane polozky jsou zaroven favorite</param>
    /// <returns type="menuparams">list</returns>
    /// </signature>
    var $actionlist = this;
    var addParamItem = function (list, c, ext) {
        var it = null, int = {};
        if ($.isPlainObject(c)) {
            if (typeof c.action === "string") {
                if (c.action.endsWith("!")) { c.primary = true; c.action = c.action.slice(0, -1); }  // favorite definovana v textu
                if (c.action.endsWith("*")) { c.favorite = true; c.action = c.action.slice(0, -1); }  // favorite definovana v textu
                if (c.action.startsWith(">")) { c.autofocus = true; c.action = c.action.slice(1); }  // opposite definovana v textu
                if (c.action.startsWith("<")) { c.align = "opposite"; c.action = c.action.slice(1); }  // opposite definovana v textu
                c.action = $actionlist[c.action];
            }
            else if (!c.action && !c.type && c.caption) c.type = "static";
            list.push(it = $.extend({}, c));
        } else if (c instanceof GAction)
            list.push(it = { action: c });
        else if (typeof c === "string") {
            if (c.endsWith("!")) { int.primary = true; c = c.slice(0, -1); }  // favorite definovana v textu
            if (c.endsWith("*")) { int.favorite = true; c = c.slice(0, -1); }  // favorite definovana v textu
            if (c.startsWith(">")) { int.autofocus = true; c = c.slice(1); }  // autofocus
            if (c.startsWith("<")) { int.align = "opposite"; c = c.slice(1); }  // opposite definovana v textu
            if (c === "-") list.push(it = { type: "separator" });
            else if ($actionlist[c]) list.push(it = { action: $actionlist[c] });
            else list.push(it = { type: 'static', caption: c });
        } else if ($.isArray(c)) {
            var it = addParamItem(list, c.shift(), ext);
            it.children = [];
            while (c.length) addParamItem(it.children, c.shift());
        }
        if (it) it = $.extend(it, ext, int);
        return it;
    };

    if (typeof (oppositeBar) == "boolean") { fav = oppositeBar; oppositeBar = null; }

    var params = [];

    if (oppositeBar) oppositeBar = oppositeBar.slice();
    if (normalBar) normalBar = normalBar.slice(); 

    while (oppositeBar && oppositeBar.length) addParamItem(params, oppositeBar.shift(), { align: "opposite", favorite: fav === true ? true : undefined });
    while (normalBar && normalBar.length) addParamItem(params, normalBar.shift(), { favorite: fav === true ? true : undefined });

    return params;
};





/* ======================================================= */
/* $.fn.gdomcontext() */
/* ======================================================= */

(function ($) {
  "use strict";
  $.fn.gdomcontext = function (options, obj) {

    //get
    if (typeof options == "undefined")
      return getContext(this[0]);

    //null 
    if (options === null)
      $(this).data("gdomContext", null);

    //set
    if ($.isPlainObject(options)) {
        this.each(function () {
            var curr = $(this).data("gdomContext");
            if (curr && curr.parent && options.parent && curr.parent !== options.parent)
                throw "gdomContext: jeden element nemuze mit vice ruznych parentu";
            $(this).data("gdomContext", $.extend({}, curr, options));
        });
    } else if (options === "remove") {
        var curr = $(this).data("gdomContext");
        if (curr) {
            curr[obj] = undefined;
            $(this).data("gdomContext", curr);
        }
    } else if (options === "isContainedIn") {
        var container = obj instanceof jQuery ? obj[0] : obj;
        var contained = this[0];

        //NOTE: Nativni HTMLElement.contains() volany interne v $.contains() je cca 10x rychlejsi nez getContext(), proto
        //      asi ma cenu vzdy to jednorazove testnout pred tim.
        if ($.contains(container, contained)) return true;

        var path = getContext(contained, container, false)._contextPath;
        //console.log("isContainedIn, contextPath", path);
        return path.indexOf(container, 1) > -1; //NOTE: Zde me zajimaji az parenti, tzn., current bych mel vynechat
    }

    return this;
  };

  function getContext(current, stopAt, mergeContextParams) {
      /// <summary>Vrati context od $current (vcetne!) az po stopAt nebo document. </summary>
      /// <param name="current" type="HTMLElement">Aktualni element</param>
      /// <param name="stopAt" type="HTMLElement">Parent element, na kterem se ma prohledavani DOM zastavit (default=undefined)</param>
      /// <param name="mergeContextParams" type="boolean">Kopirovat parametry GDOMContextu do resultu? (default=true)</param>
      /// <returns type="ObjectLiteral<any> & { _contextPath: [] }"></returns>
      var cp = [current];
      var result = { _contextPath: cp };
      
      mergeContextParams = typeof mergeContextParams === "undefined" ? true : mergeContextParams;

      while (current) {
          var data = $.data(current, "gdomContext");
          var c = data && data.parent ? data.parent : current.parentElement;

          if (c) cp.push(c);
          current = c;

          if (data && mergeContextParams) {
              var keys = Object.keys(data), i = 0, l = keys.length;
              for (; i < l; i++) {
                  var p = keys[i];
                  if (typeof result[p] === "undefined" && p !== "parent")
                      result[p] = data[p];
              }
          }

          if (stopAt && current === stopAt) break;
        }
      return result;
  }

  $.gcontains = function(container, contains) {
      /// <summary>Zjisti, zda arg. 'contains' je obsazen v containeru. Respektuje GDOMContext</summary>
      return $(contains).gdomcontext("isContainedIn", container);
  };

  //TODO: Presunout nekam jinam, ale kam???
  //Moznost zavolat nejaky kod na remove, pouziti:
  // $('.fooo').on('destroyed', function(){ ... });
  $.event.special.destroyed = {
    remove: function (o) {
      if (o.handler) {
        o.handler();
      }
    }
  };
})(jQuery);

$.fn.selectText = function () {
  /// <summary> funkce oznaci vsechen text v elementu (contenteditable div, apod.)
  /// </summary>
  this.each(function () {
    if (document.body && document.body.createTextRange) {
      var range = document.body.createTextRange();
      range.moveToElementText(this);
      range.select();
    } else if (window.getSelection) {
      var selection = window.getSelection();
      var range = document.createRange();
      range.selectNodeContents(this);
      selection.removeAllRanges();
      selection.addRange(range);
    }
  });

  return this; 
}

