$.fn.scrollTo = function (target) {
    /// <summary>funkce zascroluje this tak, aby target byl uprostřed</summary>
    if (target.length > 0) 
        target[0].scrollIntoView({
            block: "nearest"
        }); 

    return this;
};
$.fn.scrollWithin = function () {
    /// <summary>funkce zascroluje parent tak, aby this byl videt</summary>
    /// <param name="parent">element se scrollbarem, ve kterem se scroluje.
    /// Pokud neni uveden, scroluje se vsichni parenti prvniho this elementu
    /// </param>
    $().scrollTo(this);
    return this;
};
/**
 * Append visible drag handle (dots) - currently only "s" is working
 * @param {any} target
 */
$.fn.appendVisibleResizeHandle = function (target) {
    this.find(".ui-resizable-" + target).append($("<i class='g-drag-handle-" + target + " ui-icon ui-icon-grip-dotted-horizontal'>"));
    return this;
}
