(function ($) {
    "use strict";

    /* ======================================================= */
    /* GSTOR */
    /* ======================================================= */
    namespace("Gordic.Data.Storage", CreateClass({
        _constructor: function (initData, options) {
            /// <summary>Vytvoreni JSON uloziste</summary>
            /// <param name="initData" type="object">inicializacni objekt, ktery je GStor obsluhovan</param>
            /// <returns type="GStor">this</returns>

            this.__data = initData || {};
            this.__protectedFields = {}; 

            this.__settings = $.extend({
                autoSave: true,
                save: null,                          // ukladaci funkce
                traceChanges: false,                 // zapnuti sledovani zmen (set, merge, remove, ... zacnou plnit dirtyBranches + dirtySaved
                dirtyBranches: [],                   // seznam vetvi a hodnot GStor, ve kterych doslo ke zmenam
                saveWaiting: 5000,                   // [ms] vyckavaci cas od posledniho zavolani save po vyvolani ulozeni 
                saveDelay: 15000,                     // [ms] nejkratsi cas kdy je bude mozne odeslat opakovany request na ulozeni (zabranuje pretizeni serveru pri castych zmenach ulozenych hodnot)
            }, options);
            this.__settings.saveProcessor = this.__settings.saveProcessor || new GTaskProcessor({ delay: this.__settings.saveDelay, waiting: this.__settings.saveWaiting })
            this.rootStor = this;        
            this.rootSection = "";      
        },
        _getNameParts: function (name) {
            /// <summary>["foo.bar", "name"], "foo.bar.name" => ["foo", "bar", "name"]</summary>
            var parts = typeof name == "string" ? name.split(".") :
                $.isArray(name) ? name.reduce(function (p, n) { return p.concat(n?n.split("."):[]); }, []).filter(function (v) { return !!v; }) :
                    null;
            // TS:241112 - T38178 - klice jako __proto__ se budou ignorovat
            if (parts && parts.some(k => typeof this.__protectedFields[k] !== "undefined")) throw new GError('GStor: Nepovolena operace: pokus o pristup k chranene vlastnosti');

            return parts;
        },
        _getInnerObject: function (name, overrideValues) {
            /// <summary>["foo", "bar"] => foo: {bar: -->{}<-- }</summary>
            var curr = this.__data;
            var parts = this._getNameParts(name);

            if (!parts || parts.length == 0 || !parts[0]) return null;

            for (var i = 0; i < parts.length - 1; i++) {
                curr[parts[i]] = curr[parts[i]] || {};
                if (typeof curr[parts[i]] != "object" || ($.isArray(curr[parts[i]]) && i < parts.length - 1 && !$.isNumeric(parts[i + 1])))
                    if (overrideValues === true)
                        curr[parts[i]] = {};
                    else
                        throw new GError("GStor: Nepovolena operace: pokus o pristup k hodnote '" + parts.join(".") + "' prestoze '" + parts[i] + "' obsahuje hodnotovy typ (num/bool/string) a ne objekt.");
                curr = curr[parts[i]];
            }
            return { obj: curr, name: parts[parts.length - 1], fullname: parts.join("."), parts: parts };
        },
        setDirty: function () {
            /// <summary>pokud se na GStor (root) sleduji zmeny, ulozi, ze se [name] zmenil (rozhodujici pro getData(true) a Save() )</summary>
            /// <param name="name" type="string">napr:"foo.bar", nebo ["foo", "bar"]</param>
            if (this.__settings.traceChanges === true) {
                for (var j = 0; j < arguments.length; j++) {
                    var name = arguments[j];

                    var fullname = "";
                    if (name) {
                        var parts = this._getNameParts(name); // normalizace poli, subkomponent + kontrola
                        fullname = parts.join(".");
                        if (parts.filter(function (part) { return part == null || typeof part !== "string" || part.trim() === ""; }).length)
                            throw new GError("GStor: Neplatny klic: '" + fullname + "'");
                    }
                    if (!fullname)
                        this.__settings.dirtyBranches = [""];  // dirty root
                    else {
                        for (var i = this.__settings.dirtyBranches.length - 1; i >= 0; i--) {
                            if (!this.__settings.dirtyBranches[i] || fullname === this.__settings.dirtyBranches[i] || fullname.indexOf(this.__settings.dirtyBranches[i] + ".") == 0) return; // check jestli uz neni dirty nejaka nadrizena
                            if (this.__settings.dirtyBranches[i].indexOf(fullname + ".") == 0) // vymazani podrizenych dirty (stejne se resi jiz na predchozim radku)
                                this.__settings.dirtyBranches.splice(i, 1);
                        }
                        this.__settings.dirtyBranches.push(fullname);
                    }
                }
            }
            if (this.__settings.autoSave === true) this.save();
        },
        resetDirty: function (name) {
            if (name)
                this.__settings.dirtyBranches = this.__settings.dirtyBranches.filter(function (branch) {
                    return branch === name || branch.startsWith(name + ".");
                });
            else
                this.__settings.dirtyBranches = []; 
        },
        set: function (name, val) {
            /// <summary>nastaveni hodnoty, vcetne zanorenych vlastnosti (napr:"foo.bar" => { foo: { bar: null } })</summary>
            /// <param name="name" type="string">napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <param name="val" type="object">hodnota vlastnosti</param>
            /// <returns type="GStor">this</returns>
            if (val !== undefined) {
                var o = this._getInnerObject(name);

                if (o) {
                    //if (o.obj[o.name] !== val) {
                        o.obj[o.name] = val;
                        this.setDirty(o.fullname);
                    //}
                } else {
                    this.__data = val;
                    this.setDirty(""); 
                }
            }
            return this;
        },
        exists: function (name) {
            /// <summary>zjisteni existence v objektove strukture bez vytvareni vnorenych objektu. Skipuje Array</summary>
            var curr = this.__data;
            var parts = this._getNameParts(name);

            if (!parts || parts.length == 0 || !parts[0]) return false;
            for (var i = 0; i < parts.length - 1; i++) {
                curr = curr[parts[i]];
                if (typeof curr === "undefined") return false;
                if (i < parts.length - 1 && (typeof curr !== "object" || Array.isArray(curr))) return false;
            }
            return true;
        },
        get: function (name, copy) {
            /// <summary>ziskani hodnoty ze zanorenych vlastnosti (napr:"foo.bar")</summary>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <param name="copy" type="Boolean">(default=false) zda se ma udelat deepcopy vracenych dat (=true) nebo se muze vratit instance ze Stor (=false)</param> 
            /// <returns type="object">hodnota</returns>
            var o = this._getInnerObject(name);
            if (o) {
                var data = o.obj[o.name];
                if (copy === true) {
                    if ($.isPlainObject(data))
                        data = $.extend(true, {}, data);
                    else if ($.isArray(data))
                        data = data.slice();
                }
            } else { // root
                var data = this.__data;
                if (copy === true)
                    data = $.extend(true, {}, data);
            }
            return data;
        },
        getDef: function (name, defaultValue) {
            /// <summary>ziskani hodnoty ze zanorenych vlastnosti (napr:"foo.bar") s moznosti vraceni vychozi hodnoty, pokud hledana hodnota je undefined</summary>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <returns type="object">hodnota</returns>
            var val = this.get(name);
            return (typeof val === "undefined" ? defaultValue : val);
        },
        apply: function (obj, name, includeNewOnes) {
            /// <summary>obohati predany objekt o hodnoty ulozene v ulozisti, zadne nove nepridava</summary>
            /// <param name="obj" type="object">objekt, ktery se obohacuje</param>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <param name="includeNewOnes" type="Boolean">(default=false) zda se maji pridat i nove vlastnosti (true), ci pouze aktualizovat stavajici (false)</param>
            /// <returns type="object">obj rozsireny o hodnoty konfigurace</returns>

            return includeNewOnes === true ? $.deepExtendWoArray(obj, this.get(name)) : $.deepApply(obj, this.get(name));
        },
        remove: function (name) {
            /// <summary>smazani hodnoty zanorene vlastnosti (napr:"foo.bar")</summary>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <returns type="object">this</returns>
            var o; 
            if (this.exists(name) && (o = this._getInnerObject(name))) {
                delete o.obj[o.name];
                this.setDirty(o.fullname);
            }
            return this;
        },
        clear: function (name) {
            /// <summary>smazani vsech podrizenych vlastnosti specifickeho objektu (napr:"foo.bar") - NULL/undef pro vymazani sebe</summary>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <returns type="object">this</returns>
            var o = this._getInnerObject(name);
            var data = o ? o.obj[o.name] : this.__data;
            for (var v in data)
                this.remove(o ? [o.fullname, v] : v);

            return this;
        },
        merge: function (name, options) {
            /// <summary>Slouci predany objekt s konkretni pozici v ulozisti ($.extend, deepCopy)</summary>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <param name="options" type="object">seznam vlastností k rozšíření, muze byt vic argumentu napr. merge("foo.bar", {...}, {...})</param>
            /// <returns type="GStor">this</returns>
            if (!arguments.length) return this; 

            var dataobject = null;
            var args = null;

            if ($.isPlainObject(arguments[0]) || arguments[0] === null) {  // .merge(object, ...) - root
                args = Array.prototype.slice.call(arguments);
                dataobject = this.__data;
            } else {                                                      // .merge(name, ...)
                args = Array.prototype.slice.call(arguments, 1);
                var o = this._getInnerObject(name);
                if (o) {
                    if (args.length >= 1 && $.isPlainObject(args[args.length - 1]) === false)  // .merge(name, value)
                        o.obj[o.name] = args[args.length - 1];
                    else                                                      // .merge(name, object)
                        dataobject = o.obj[o.name] = o.obj[o.name] || {};
                } else                                                        // .merge("" | [], object)   .. .merge("" | [], value) budou ignorovany v nasledujici smycce
                    dataobject = this.__data
            }

            if (dataobject) {
                for (var i = 0; i < args.length; i++) {
                    if (args[i] instanceof Gordic.Data.Storage || args[i] instanceof Gordic.Data.StorageSection) args[i] = args[i].get("", true); // merge jineho GStor
                    if ($.isPlainObject(args[i]) === false) args[i] = {};         // merge akceptuje pouze objekty
                }
                args.unshift(dataobject);
                $.deepExtendWoArray.apply(this, args);
                for (var i = 1; i < args.length; i++)
                    for (var name in args[i])
                        this.setDirty(o ? [o.fullname, name] : name);
            }
            return this;
        },
        getDirtyStructure: function () {
            /// <summary>Vrati kopii dat z uloziste (pro trackChanges == true vrati rozdilovou strukturu (zmenene polozky doplnene o kolekci __new))</summary>
            /// <returns type="object">objekt dat</returns>
            if (this.__settings.traceChanges === true) {
                var gs = new GStor({});
                var newBranches = [];

                for (var i = 0; i < this.__settings.dirtyBranches.length; i++) {
                    var val = this.get(this.__settings.dirtyBranches[i], true);
                    if (typeof val === "undefined" || $.isPlainObject(val)) // deleted or replaced
                        newBranches.push(this.__settings.dirtyBranches[i]);
                    if (typeof val !== "undefined")
                        gs.set(this.__settings.dirtyBranches[i], val);
                }
                if (newBranches.length) gs.set("__new", newBranches);
                return gs.__data;
            } else
                return this.get("", true);
        },
        isDirty: function () {
            /// <summary>Vrati informaci, zda byla kolekce zmenena</summary>
            /// <returns type=""></returns>
            return (this.__settings.traceChanges === true && this.__settings.dirtyBranches && this.__settings.dirtyBranches.length > 0) || !this.__settings.traceChanges;
        },
        isLocked: function (name) { 
            /// <summary>Vrati priznak, zda dana sekce uloziste podleha zamku ze sdileneho obsahu (sdilene sekce lze editovat se specialnim opravnenim gin_usteditor=10)
            ///          Uzamknute sekce nelze prepsat uzivatelskou konfiguraci (lze lokalne, lze i ulozit, ale pri nacteni se ignoruji). Komponenty by mely reagovat jiz pri pokusu o ulozeni</summary>
            /// <param name="name" type="String">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <returns type="Boolean">zda je sekce uzamknuta, ci nikoliv</returns>
            var fullname = this._getNameParts(name).join(".");
            var ls = this.get("_lockedSections");
            return this.__settings.locked === true || ($.isArray(ls) && ls.filter(function (lock) { return fullname === lock || fullname.indexOf(lock + ".") === 0; }).length > 0);
        },
        isVirtual: function () {
            return this.__settings.virtual === true;
        },
        defaults: function (name, def) {
            /// <summary>vlozi do uloziste vychozi hodnoty objektu, ktere v ulozisti dosud nejsou (provadi deepcopy (this <- def <- currentValue))
            /// $#10;{ x: 10, y: 10 }.defaults({x: 0, y: 0, z: 0}) => {x: 10, y: 10, z: 0}
            /// </summary>
            /// <param name="name" type="string">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <param name="def">(default={}) vychozi hodnota. Pokud je objekt, provadi se deepcopy. Pokud hodnotovy typ, provede se "set" v pripade, ze zadna hodnota neexistuje. 
            ///   Pokud je rozpor mezi ulozenym a predanym typem, predany typ ma prednost (slouzi i pro narovnani typu v ulozisti):
            /// $#10;{ pozice: 300 }.defaults("pozice", {x:10, y:20}) => {pozice: {x:10, y:20}} )
            /// $#10;{ pozice: { x:10, y: 20} }.defaults("pozice", 400) => {pozice: 400} )
            /// $#10;{ form: 'mujForm' }.defaults("form.info", {title: ''}) => {form: {info: {title: ''}}}
            /// </param>
            /// <returns type="GStor">this</returns>
            if (typeof def == "undefined") def = {};
            this._getInnerObject(name, true); // "defaults" ma vyjimku a prepisuje i existujici hodnotove typy zanorenim. Vola se zde, proto .get by uz spadl

            var currentValue = this.get(name, true); // kopie je dulezita, provadi se merge/$.extend(this, def, currentValue). Pokud this == currentValue, prvni extend (this,def) modifikuje primo currentValue
            if ($.isPlainObject(def) && $.isPlainObject(currentValue)) // objekt
                this.merge(name, def, currentValue);
            else if (typeof currentValue == "undefined" || $.isPlainObject(def) || typeof currentValue != typeof def) // hodnotovy typ (pouzijeme jen pokud neni vyplnen)
                this.set(name, def);
            return this;
        },
        sub: function (name, defaults) {
            /// <summary>Vrati objekt GStor navazany na nejakou podrizenou vetev hlavni konfigurace</summary>
            /// <param name="name" type="string">klic v konfiguraci napr:"foo.bar", nebo ["foo", "bar"]</param>
            /// <param name="defaults" type="object">(default={}) vychozi hodnota objektu v pripade, ze [name] neexistuje nebo neni typu object</param>
            /// <returns type="GStor">GStor navazany na podrizenou vetev hlavni konfigurace (reference)</returns>
            if (typeof defaults != "undefined" && !$.isPlainObject(defaults))  // kontrola proti zapomenutym [] pri definici name 
                throw "GStor.sub: parametr 'defaults' musi byt typu object";

            var o = this._getInnerObject(name); 

            if (o) {
                if (!$.isPlainObject(o.obj[o.name]))   // vytvoreni zanoreni v ulozisti
                    o.obj[o.name] = defaults || {};
                return new Gordic.Data.StorageSection(this, o.fullname);
            }
            return this;
        },
        save: function (immediate) {
            if (!this.__settings.save) return;
            if (!this.isDirty()) return;

            var _this = this;
            this.__settings.saveProcessor.process("save", function () {
                var contestedDirties = _this.__settings.dirtyBranches;
                var p = _this.__settings.save.call(_this, _this.getDirtyStructure(), _this.__settings.traceChanges === true);
                _this.__settings.dirtyBranches = []; // povazujeme za ulozene a muzeme sbirat dalsi zmeny
                if (p && $.isFunction(p.promise)) p.fail(function () { _this.setDirty.apply(_this, contestedDirties); }); // ulozeni failnulo => vratime puvodni dirty (ve skutecnosti merge puvodnich k nove vzniklym)
            }, immediate === true);
            return this; 
        }
    }));

    window.GStor = Gordic.Data.Storage; // ke zruseni

    namespace("Gordic.Data.StorageSection", function (rootStor, section) {
        /// <summary>Obsluha lokalni casti Storage. StorageSection je namapovan na vybranou sekci Storage a metody volane na StorageSection se automaticky preposilaji na GStor s doplnenym prefixem sekce</summary>
        /// <param name="rootStor" type="Gordic.Data.Storage">hlavni GStor jehoz je tento StorageSection soucasti</param>
        /// <param name="section" type="string">cesta v GStor, ktera figuruje jako koren tohoto GStorSection</param>
        /// <returns type="Gordic.Data.Storage">this</returns>
        var _this = this;
        var _createWrapper = function (fceName, nameIndex) {
            _this[fceName] = function () {
                var args = Array.prototype.slice.call(arguments);
                if (typeof nameIndex == "number") {
                    if (typeof args[nameIndex] == "undefined")
                        args[nameIndex] = _this.rootSection;
                    else if (typeof args[nameIndex] == "string")
                        args[nameIndex] = _this.rootSection + (args[nameIndex] ? "." + args[nameIndex] : "");
                    else if ($.isArray(args[nameIndex]))
                        args[nameIndex].unshift(_this.rootSection);
                    else if (nameIndex === 0)
                        args.unshift(_this.rootSection)
                    else 
                        throw "Gordic.Data.StorageSection: Nelze preposlat volani '" + fceName + "'. Neplatna hodnota parametru 'name'."
                } // else if (typeof nameIndex === "function")   // TODO: kdyby automat nahore nestacil, asi by chtelo tam pridat delegata ()=>name

                if (typeof _this.rootStor[fceName] != "function")
                    throw "Gordic.Data.StorageSection: Funkci '" + fceName + "' nelze v GStor nalezt."

                var res = _this.rootStor[fceName].apply(_this.rootStor, args);
                return (res === _this.rootStor ? _this : res); // pokud premapovana root funkce vraci "this", chceme vratit nas this StorageSection
            }
        }

        this.rootStor = rootStor;        // vytvoreny substore (pomoci GStor.sub) zde ma odkaz na root GStor. Nektere veci se vzdy sleduji na rootu (dirtyBranches, lockedSections, aj)
        this.rootSection = section;      // fullname vlastnosti root GStor, ktera byla pouzita pro vytvoreni tohoto sub (root:{prvni: {druha: {treti: hodnota}}} -> sub("prvni.druha") -> GStor({treti: hodnota}, rootSection: "prvni.druha") )

        _createWrapper("setDirty", 0);
        _createWrapper("resetDirty", 0);
        _createWrapper("set", 0);
        _createWrapper("get", 0);
        _createWrapper("exists", 0);
        _createWrapper("getDef", 0);
        _createWrapper("apply", 1);
        _createWrapper("remove", 0);
        _createWrapper("clear", 0);
        _createWrapper("merge", 0);
        _createWrapper("isLocked", 0); 
        _createWrapper("isVirtual"); 
        _createWrapper("defaults", 0);
        _createWrapper("sub", 0);
        _createWrapper("save");
    });

    Gordic.Data.Storage.resolve = function (sub, context, opts) {
        opts = opts || {}; 
        var stor; 
        var isE = (isElement(context) || context instanceof jQuery); 
        if (sub !== false) { // explicitne vypnute nastaveni
            if (sub instanceof Gordic.Data.Storage || sub instanceof Gordic.Data.StorageSection) // zadani instanci uloziste
                stor = sub;
            else if (typeof sub === "string" || $.isArray(sub)) { // zadani absolutni cestou v gstor konfiguraci
                if (opts.container === true && isE)
                    $(context).gdomcontext("remove", "userSettings");  
                var us = opts.isolated ? window.gstor :
                    isE ? $(context).gdomcontext().userSettings || window.gstor :
                    (context instanceof Gordic.Data.Storage || context instanceof Gordic.Data.StorageSection) ? context : null; 

                if (us && sub)
                    stor = us.sub(opts.defaultSub).sub(sub);
            }
        }

        stor = stor || new GStor({}, { virtual: true });
        if (opts.container === true && isE)
            $(context).gdomcontext({ userSettings: stor });

        return stor;  
    }


    namespace("Gordic.Data.StorageService", CreateClass({
        _constructor: function (storage) {
            if (storage instanceof Gordic.Data.Storage || storage instanceof Gordic.Data.StorageSection) this.storage = storage;
            else throw new Error("CRITICAL ERROR: Gordic.Data.StorageService requires instance of Storage to operate")
        },
        getId: function (name) { return (obj.name || "unknown").replace(".", "#"); },
        getFilters: function (parametry) {
            var profiles = this.storage.get("", true);
            var profs = [];
            for (k in profiles) profs.push(profiles[k]);
            return $.when(profs);
        },
        saveFilter: function (obj) {
            this.storage.set(this.getId(obj.name), obj);

            return $.Deferred.resolve(obj).promise();
        },
        removeFilter: function (obj) {
            this.storage.remove(this.getId(obj.name)); 

            return $.Deferred.resolve().promise();
        }
    }));

})(jQuery);

