                var charKeysShortcuts = shortcutsToExecute.filter(function (it) { return it[1].key === charKeysKey; });
                var nonCharKeysShortcuts = shortcutsToExecute.filter(function (it) { return it[1].key !== charKeysKey; });
                //var charKeysShortcutIndex = -1;
                //if (shortcutsToExecute.length > 1 && shortcutsToExecute.find(function (it, index) { if (it[1].key === charKeysKey) { charKeysShortcutIndex = index; return true; } return false; }) && !shortcutsToExecute.every(function (it) { return it[1].key === charKeysKey; })) {
                //    // if there is more shortcuts and first one is charkeys shortcut and some other in chain isn't,
                //    // prefere the one, that is not charkeys.
