  function GShortcut(elem, options) {
    this.element = elem;

    $.extend(this, options);

    this.isCtrlRegistred = false;
    this.isAltRegistred = false;
    this.isShiftRegistred = false;
    this.comboKey = '';
    this.setKeyFlags();
    this.key = this.key.toLowerCase();

    if (this.key === charKeysKey || this.comboKey === charKeysKey) {
      this.compareKey = function (evKey, shortcutKey) {
        return reg.exec(evKey) !== null;
      };
    }
  }

  GShortcut.prototype.setKeyFlags = function () {
    var shortcuts = this.key.split('+');
    for (var i = 0, l = shortcuts.length; i < l; i++) {
      switch (shortcuts[i].toLowerCase()) {
        case 'ctrl':
          this.isCtrlRegistred = true;
          break;
        case 'alt':
          this.isAltRegistred = true;
          break;
        case 'shift':
          this.isShiftRegistred = true;
          break;
        case '':
          this.comboKey = '+';
          break;
        case 'space':
          this.comboKey = ' ';
          if (l === 1) {
            this.key = this.comboKey;
          }
          break;
        default:
          this.comboKey = shortcuts[i];
          break;
      }
    }
  };

  GShortcut.prototype.checkKeyDown = function (ev) {
      var realKey = ev.key == null ? clickEvToKey(ev) : ev.key.toLowerCase();
      if (this.comboKey.indexOf("c:") === 0 || this.key.indexOf("c:") === 0) realKey = ev.code == null ? realKey : ev.code.toLowerCase();

    if (ev.key === 'Control' || ev.key === 'Shift' ||
      ev.key === 'Alt' || ev.key === 'AltGraph') {
        return -1;
    } else if (!ev.ctrlKey && !ev.shiftKey && !ev.altKey &&
      this.key.indexOf('+') === -1) {
      return this.compareKey(realKey, this.key) ? 1 : 0;
    }

    var isCtrl = !(ev.ctrlKey ^ this.isCtrlRegistred);
    var isShift = !(ev.shiftKey ^ (this.isShiftRegistred || this.key === charKeysKey)); // enable shift for charkeys as they might start with big letter
    var isAlt = !(ev.altKey ^ this.isAltRegistred);

    return isCtrl && isShift && isAlt && this.compareKey(realKey, this.comboKey) ? 1 : 0;
  };

    GShortcut.prototype.compareKey = function (evKey, shortcutKey) {
        return evKey === (shortcutKey.indexOf("c:") === 0 ? shortcutKey.substr(2).toLowerCase() : shortcutKey);
  };

  $.fn.gshortcut = function (options) {
    // get
    if (typeof options == 'undefined') {
      return this.data('gshortcut');
    }

    // null
    if (options === null) {
      var curr = this.data('gshortcut') || [];
      for (var i = 0, l = curr.length; i < l; i++) {
          curr[i].unregister();
      }
      this.removeClass('gshortcut');
      this.data('gshortcut', null);
    }

    // get by key or get all
    if (typeof options === 'string') {
      switch (options) {
        case 'get': {
          var curr = $(this).data('gshortcut') || [];
          var arr = [];
          for (var i = 0, l = curr.length; i < l; i++) {
            if (curr[i].id === arguments[1] || curr[i].key === arguments[1]) {
              arr.push(curr[i]);
            }
          }
          return arr;
        }
        case 'all': {
          if (arguments[1] === 'down') {
              return getShortcutsDown.call(this);
          }

          return getShortcutsUp.call(this);
        }

        case 'remove': {
          var curr = $(this).data('gshortcut') || [];
          var arr = [];
          var toReturn = [];
          for (var i = 0, l = curr.length; i < l; i++) {
            if (curr[i].id === arguments[1] && curr[i].id != null || curr[i].key === arguments[1]) {
              toReturn.push(curr[i]);
            } else {
              arr.push(curr[i]);
            }
          }
          if (arr.length === 0) {
            this.removeClass('gshortcut');
            this.data('gshortcut', null);
          } else {
            this.data('gshortcut', arr);
          }

          return toReturn;
        }
        default: {
          console.error('Command ' + options +
            ' is not recognized - try "get" or "all".');
        }
      }
    }

    // set
    if ($.isPlainObject(options)) {
      var shortcuts = [];

      if (options.key && $.isArray(options.key)) {
        for (var i = 0, ii = options.key.length; i < ii; i++) {
          var key = options.key[i];
            shortcuts.push(
                new GShortcutManager(this, $.extend({}, options, { key: key, description: $.isArray(options.description) ? options.description[i] : options.description }))
          );
        }
      } else {
        shortcuts.push(new GShortcutManager(this, options));
      }

      for (var i = 0, ii = shortcuts.length; i < ii; i++) {
        var shortcut = shortcuts[i];
        this.each(function () {
          var curr = $(this).data('gshortcut') || [];
          var idx = curr.length === 0 ? -1 : curr.findIndex(function (it) {
            return it.key.toLowerCase() === shortcut.key.toLowerCase() &&
                  (shortcut.id == null || shortcut.id != null && it.id === shortcut.id);
          });

          if (idx < 0) {
            curr.push(shortcut);
          } else {
            curr[idx] = shortcut;
          }

          $(this).data('gshortcut', curr);
        });
      }
    }

    function getShortcutsDown() {
      var shortcuts = [];
      Array.prototype.push.apply(shortcuts, $(this).data('gshortcut'));
      var elements = $(this).find('.gshortcut');
      for (var i = 0, l = elements.length; i < l; i++) {
        var childShortcuts = $(elements[i]).data('gshortcut') || [];
        Array.prototype.push.apply(shortcuts, childShortcuts);
      }

      return shortcuts;
    }

    function getShortcutsUp() {
        var shortcuts = [];
        var elements = $(this).gdomcontext()._contextPath;

        for (var i = 0, l = elements.length; i < l; i++) {
            var childShortcuts = $(elements[i]).data('gshortcut') || [];
            Array.prototype.push.apply(shortcuts, childShortcuts);
        }

        return shortcuts;
    }

    return this;
  };

