                    //TODO (BM): Zde by melo v budoucnu byt pouze $(this).remove();

                    var $div = $(this).gcontentwrapper("destroy").gsidebarstub("destroy").gdialog("destroy");
                    if ($div.prop("doRemoveOnClose") === true) $div.detach();
                    $div.triggerHandler({ type: "contentclosed", returnValue: ev.returnValue, content: ev.content }, [retVal, content]); // TODO: kompatibilita; jedna se o obsolete metodu, mela by se zrusit do 488
                    if ($div.prop("doRemoveOnClose") === true) $div.remove();
