            if (typeof dialogOpts.menuBar !== "undefined") content.menuBar(dialogOpts.menuBar);
            if (typeof dialogOpts.statusBar !== "undefined") content.statusBar(dialogOpts.statusBar); 
            if (typeof dialogOpts.commandBar !== "undefined") content.commandBar(dialogOpts.commandBar);

            if (content.loaded && document.activeElement && !$.contains(div[0], document.activeElement)) div.gdialog("refocus");

