    $.fn.createDialogPromise = function (successCondition, returnValue) {
        /// <summary>Z existujiciho dialogu vytvori promise jeho zavreni s moznou filtraci navratovych hodnot</summary>
        /// <param name="successCondition" type="retVal | Array(retVal) | (func(retVal) => bool)">hodnota/y, ktere jsou akceptovane jako uspesne, nebo vyhodnocovaci funkce. Pokud okno vrati cokoliv jineho, promise bude rejected</param>
        /// <returns type="promise">vytvoreny promise, ktery se vyhodnoti pri zavreni okna</returns>
        return this.filter(".ui-dialog-content").createEventPromise("close", $.isFunction(successCondition) ? function (ev) { return successCondition(ev.data && ev.data[0]); } : successCondition)
            .then(function (ev) { return typeof returnValue === "undefined" ? ev.data && ev.data[0] : $.isFunction(returnValue) ? returnValue(ev.data && ev.data[0]) : returnValue; });  // returnValue je obsolete parametr, melo by se pouzit createDialogPromise().then()
    };

    $.fn.createEventPromise = function (eventName, successCondition, includePreventedEvents) {
        /// <summary>Vrati promise cekajici na specifickou udalost zavolanou na nekterem z elementu</summary>
        /// <param name="eventName" type="string">nazev jedne, nebo vice udalosti</param>
        /// <param name="successCondition" type="func(ev, ...args) => (bool | undefined)">vyhodnocovaci funkce uspechu udalosti. Pokud je nevyplnena za uspech se povazuje vznik udalosti</param>
        /// <param name="includePreventedEvents" type="boolean">(default=false) zda se maji zahrnout i udalosti s preventDefault</param>
        /// <returns type="promise">vytvoreny promise, ktery se vyhodnoti pri odchyceni eventy</returns>
        var _this = this; 

        var def = new $.Deferred();
        var eventDomain = ".createEventPromise" + (uuid++).toString();
        var eventNames = eventName.split(/\s+/g).map(function (s) { return s + eventDomain; }).join(" ");
        this.on(eventNames, function (ev, arg) {
            if (typeof ev.data === "undefined" && arguments.length > 1)
                ev.data = Array.prototype.slice.call(arguments, 1);
            if (includePreventedEvents === true || !ev.isDefaultPrevented()) {
                if ($.isFunction(successCondition)) {
                    var ret = successCondition.apply(this, arguments); // pri navratu undefined/null udalost ignorujeme a cekame na dalsi
                    if (ret === true) def.resolve(ev);
                    else if (ret === false) def.reject(ev); 
                }
                else if ($.isArray(successCondition) && successCondition.reduce(function (p, c) { return p || c === arg; }, false) === true) def.resolve(ev);
                else if (typeof successCondition === "undefined" || successCondition === arg) def.resolve(ev);
                else def.reject(ev);
            }            
        });
        return def.always(function () { _this.off(eventDomain); }).promise();
    };
