GContent.prototype.close = function (returnValue) {
    ///<signature>
    ///<summary>Návrat dat z obsahu (a zavření dialogového okna, pokud je obsah v Dialogu)</summary>
    ///<param name="returnValue" type="object">návratová hodnota</param>
    ///<returns type="GContent">this</returns>
    ///</signature>
    ///<signature>
    ///<summary>Registrace nové onReturn funkce</summary>
    ///<param name="returnFce(returnValue)" type="function">delegát návratové funkce</param>
    ///<returns type="GContent">this</returns>
    ///</signature>
    if (typeof returnValue === "function") { this.on("close", returnValue); return this; }
    if (this._closed === true || this._trueClosing === true) return;
    this._trueClosing = true;
    
    this.abortAjaxCalls();

    // rekurzivni zavreni vsech childu
    var childCnts = $.content(null, true);
    for (var i = childCnts.length - 1; i >= 0; i--)
        if (childCnts[i].parentContent === this)
            childCnts[i].close(); // close se narozdil od tryClose vola ciste rekurzivne
    
    //EVENTS
    var v = this.trigger("close", [returnValue]); // onClose, contentclose
    if (typeof v !== "undefined") returnValue = v; // null, false jsou validni hodnoty

    this._trueClosing = false;
    this._closed = true; 
    this.element.triggerHandler({ type: "close", returnValue: returnValue, content: this }, [returnValue, this]); // zkratka on "close" (vola se az za contentclose a dialogclose)
    this.element.prop("content", null).removeClass("gcontent").off("remove.gcontent"); // odvazani (nutne takhle, nebo upravit $.content aby nehledal closed contenty

    this.element.triggerHandler({ type: "closed", returnValue: returnValue, content: this }, [returnValue, this]); // informace o uzavrenem contentu, vola se az nakonec aby nebyl narusen seznam veci, ktere se provadi na close a jeste napriklad chteji cist dialog/udalosti DOM, apod.
    if (this.element.prop("doRemoveOnClose") === true) this.element.remove(); // contenty vytvorene v kontruktoru se tady vymazou. (Nesouvisi se stejnym priznakem z dialogu, ktery remove provede jiz v contentclosed)
    return this;
}
GContent.prototype.tryCloseAllChildContents = function () {
    console.log("OBSOLETE: content.tryCloseAllChildContents bude brzy zruseno! Castecne nahrazeno content.tryCloseAllSignificants. Pokud volate jako soucast breadcrumbu, zkopirovali jste obsolete kod - ODSTRANIT")
    return this.tryCloseAllSignificants(); 
}
/**
 * Rekurzivne prohleda seznam child contentu a vrati "nejblisi" significants (tj. samostatna okna - ty uz vnitrne neprohledava) a vsechny "vlastni" non-significants (taby, servisni cnt, sidebary...) az do nejblizsich significants
 * 
 * @author Tomáš Skála
 * @since 484.1.0.265
 */
GContent.prototype._analyzeChildContents = function (services, significants, contents) {
    var _this = this;
    contents = contents || $.content(null, true);

    for (var i = 0; i < contents.length; i++) {
        var cnt = contents[i];
        if (cnt.parentContent === this) {
            if (cnt.isSignificant()) significants.push(cnt);
            else {
                services.push(cnt);
                cnt._analyzeChildContents(services, significants, contents);
            }
        }
    }
}

GContent.prototype.tryCloseAllSignificants = function () {
    var _this = this;

    var def = $.Deferred();

    var closeOne = function () {
        var significants = []; 
        _this._analyzeChildContents([], significants);  // u significants je potreba hledat opakovane, aby se pozaviraly pripade contenty, ktere se mohly otevrit na onclose ve volajicich, prestoze volajici je jiz closing=true
        if (significants.length) significants[significants.length - 1].tryClose().done(closeOne).fail(def.reject);
        else def.resolve();
    };
    closeOne();
    return def.promise();
}

/**
 * vyvola closing udalost u predane skupiny contentu a vrati souhrnny promise vsech potvrzeni
 * 
 * @author Tomáš Skála
 * @since 484.1.0.271
 */
GContent.prototype._closingBunch = function (contents, returnValue) {
    var prom = $.when(), cnt;
    while (cnt = contents.pop()) 
        if ($.isFunction(cnt.closing))
            (function (cnt) { 
                prom = prom.then(function () { return cnt.closing(contents.length === 0 ? returnValue : undefined) });   // u "posledniho" (prvniho v poli; hlavni/significant content) se predava pripadny returnValue
            })(cnt);

    return prom.then(function (retValue) { return typeof retValue !== "undefined" ? retValue : returnValue; })
}

GContent.prototype.tryClose = function (returnValue) { 
    /// <summary>
    /// Zadost o uzavreni okna. Typicky se vola pri pokusu zavrit okno UZIVATELEM (krizkem na dialogu, odhlasenim z aplikace, prepnuti ulohy, apod.)
    /// Vyvolava delegata "closing()" pokud existuje, od ktereho ocekava navratovou hodnotu okna, nebo promise teto hodnoty. 
    /// </summary>
    /// <returns>promise hodnoty pro zavreni okna. Resolvnuty promise znamena, ze okno bylo uzavreno. Failnuty promise znamena, ze zustalo otevreno</returns>
    var _this = this;

    if (this._closingPromise) return this._closingPromise;
    if (this._closed === true || this._trueClosing === true) { // zabraneni zacykleni pokud nekdo v onclose vola tryclose (vcetne parentu)
        var d = $.Deferred();
        window.setTimeout(function () { d.resolve(); }, 1); // emulace asynchronicity (patri zrusit v jquery3) aby tryClose byl resolvnut az po dokoncenych close a ne pokud se toto vola jeste v nedokoncenem close
        return d.promise();
    }

    this._closing = true;

    this._closingPromise = this.tryCloseAllSignificants() // nejprve zavreme significants
        .then(function () {
            var cntsToClose = [_this];
            _this._analyzeChildContents(cntsToClose, []);
            return _this._closingBunch(cntsToClose, returnValue) // Significants jsou jiz zavrene. Pockame na tedy potvrzeni vsemi subcontenty vcetne sebe, pak je teprve vsechny zavreme. 
                .done(function (retVal) {
                    _this.close(retVal);
                });
        });
    return this._closingPromise.always(function () { _this._closingPromise = null; _this._closing = false; }); // nesmi byt na jednom radku s predchozim, jinak se v pripade okamzite vyhodnocenych closing promise _closingPromise=null zavola pred _closingPromise = ...
}

GContent.prototype.abortAjaxCalls = function () {
    ///<summary>Prerusi vsechny probihajici AJAX volani vyvolana pomoci load, call, post, postCall. Volani metodou fire preruseno nebude.</summary>
    this._xhrs.forEach(function (it) { it&&it.abort(); });
}
