GContent.prototype.working = function (working, statusObj) {
    ///<summary>Udalost pri beginOperation/endOperation</summary>
    ///<param name="working" type="bool">stav working operace (true = probiha, false = neprobiha)</param>
    ///<param name="statusObj" type="object">objekt aktivni operace ({text: "pleasewait", current: 0, total: 100, cancelAction: new GAction...})</param>
    ///<returns type="GContent">this</returns>
    return this.dispatchEvent("working", arguments);
}
GContent.prototype.notification = function (method, params) {
    ///<summary>Udalost pri potrebe pracovat s notifikaci</summary>
    ///<param name="method" type="string">argumenty se v podstate 1:1 posilaji do widget gnotificationlist, takze napr. "add", "remove", aj.</param>
    ///<returns type="GContent">this</returns>
    if (method === "add" && !(params instanceof GObservableObject)) arguments[1] = new GObservableObject(params);
    if (method === "add" && !params.id) arguments[1].id = "_contNot" + (++window.guid);
    return this.dispatchEvent("notification", arguments);
}

GContent.prototype.flashUpdate = function (data) {
    ///<summary>Udalost pri showFlash/hideFlash</summary>
    ///<param name="data" type="object">nove informace o flashinformaci</param>
    ///<returns type="GContent">this</returns>
    return this.dispatchEvent("flashUpdate", arguments);
}

GContent.prototype.showFlash = function (content, state, id) {
    ///<signature>
    ///<summary>Zobrazi Flash informaci (rychla informace, ktera typicky po case zmizi)</summary>
    ///<param name="content" type="string">zobrazovana informace</param>
    ///<param name="state" type="string">stav [info(default), success, warning, error, important]</param>
    ///<param name="id" type="string">identifikator pro moznost dohledani (napr. pro hideFlash(id) )</param>
    ///<returns type="GContent">this</returns>
    ///</signature>
    ///<signature>
    ///<summary>Zobrazi Flash informaci (rychla informace, ktera typicky po case zmizi)</summary>
    ///<param name="data" type="object">informace o flash (parametry komponenty gflashpanel)</param>
    ///<returns type="GContent">this</returns>
    ///</signature>
    var data = ($.isPlainObject(content) ? content : { content: content, state: typeof state === "string" && state.startsWith("g-state-") ? state.substr(8) : state, id: id || arguments[3] });  // arg[3] je kvuli kompatibilite se starym volanim, kde byl treti argument timer
    return this.flashUpdate(data);
}

GContent.prototype.hideFlash = function (id) {
    ///<summary>Skryje zobrazeny flash</summary>
    ///<param name="id" type="string">identifikator flashe</param>
    ///<returns type="GContent">this</returns>
    return this.flashUpdate({ id: typeof id === "undefined" ? null : id, content: null });
}

GContent.prototype.createIPopup = function () {
    ///<summary>Vytvori oldfashion popup menu, v jehoz udalostech bude fungovat $.content(this)</summary>
    var div = window.createIPopup.apply(window, arguments);
    div.content = this;
    return div;
}
GContent.prototype._processOps = function (ops) {
    ///<summary>Zpracuje nove Operations zaslane ze serveru</summary>
    if (ops.actions) {
        for (var i = 0; i < ops.actions.length; i++) {
            var newAPars = ops.actions[i];
            if (this.actions[newAPars.name])
                this.actions[newAPars.name].unregister();

            if (newAPars.run)
                (function () { eval("this.run=" + this.run); }).call(newAPars); // volani eval v kontextu newAPars. Pouziti libovolne promenne misto "this" zpusobovalo chybu v minifikovane verzi, ktera zmeni nazev promenne, ale ne uvnitr stringu; napr: newAPars.run&&eval("newAPars.run=" + newAPars.run) se minifikuje jako t.run&&eval("newAPars.run=" + t.run)

            var act = this.actions.add(newAPars);
            act.run(function (ev) { $(this.content.contentDiv).trigger({ type: this.name, action: this, content: this.content }, [this, this.content]); });
        }
    }

    this._processMenuDefinitions(ops);
    if (ops.customMenus) this.customMenus = $.extend(false, this.customMenus, ops.customMenus);
    if (ops.breadcrumbs) this.setBreadcrumbs(ops.breadcrumbs);
    if (ops.title != null) this.title = ops.title;
    if (ops.menuBar) this.menuBar(ops.menuBar);
    if (ops.commandBar) this.commandBar(ops.commandBar);
    if (ops.statusBar) this.statusBar(ops.statusBar);

    this.newOps(ops);
}

GContent.prototype._processMenuDefinitions = function (params, actions) {
    var _this = this;
    if (!params) return; 

    var stack = [params];
    while (stack.length) {
        var o = stack.pop();
        $.each(o, function (index, value) {
            if ($.isArray(value)) stack.push(value)
            else {
                if (typeof value.action == "string") {
                    var a = $.findAction(value.action, actions || _this.actions, _this);
                    if (!a) throw "Nelze nalezt instanci akce '" + value.action + "' pro naplneni menu params na contentu '" + _this.contentDiv.id + "'.";
                    value.action = a;
                }
                if (value.children && value.children.length) stack.push(value.children);
                else if (!value.action && !value.type && $.isPlainObject(value)) stack.push(value);
            }
        });
    }
}

GContent.prototype.navigate = function (contentInitializer, inputParams, options) {
    /// <signature>
    /// <summary>Otevre novy content jako podrizenou aktivitu (bude zobrazena na plose hlavni aplikace, prekryvajici content z nejz byla aktivita otevrena, s provazanim zavislosti)</summary>
    /// <param name="contentInitializer" type="string">
    /// Identifikátor obsahu GContent. 
    /// <para>1) Název serverové třídy IGAjaxContent (např.: "Gordic.Gui.WebControls.GAjaxContentASPX")</para>
    /// <para>2) Použití registrované zástupky (např.: "ascx://Test.ascx"). Výchozí registrované zástupky jsou: "aspx://", "ascx://", "iframe://"</para>
    /// <para>3) Použití contentInitializeru viz. new GContent(), nebo GContent.createInitializer() (např.: [className, params], {className:"", params: {}} ... className mohou byt z bodu 1) a 2) )</para>
    /// <para>4) NULL pro vytvoření prázdného Contentu (plněného z JS) </para>
    /// <para>5) $div pro vytvoření prázdného Contentu s přednastaveným obsahem </para>
    /// </param>
    /// <param name="inputParams" type="object">Vstupní parametry GContent (null, {}, undefined pro prázdný seznam).
    /// <para>Muze byt ID contentu/okna (zkratka za: {ID: "..."})</para>
    /// </param>
    /// <param name="dialogOptions" type="object">parametry okna (viz. JQueryUI.Dialog). Hodnoty rozmeru, pozice a vlastnosti okna (napr. resizable, title, noClose, ...) budou ignorovany.</param>
    /// <returns type="Promise<jQuery>" />
    /// </signature>
    if (this.parentContent && this.parentContent !== this) return this.parentContent.navigate(contentInitializer, inputParams, $.extend({ parentContent: this }, options));
    return this.dialogs.showModalWindow(contentInitializer, inputParams, options); // defaultne do otevreni plovouciho okna, pokud neexistuje spravce aktivit
} 

GContent.prototype.setUserSettings = function (us, isolated, container) {
    ///<summary>nastavi novy objekt uzivatelskeho nastaveni pro content</summary>
    ///<param name="us" type="object">nova specifikace objektu nastaveni:
    ///<para>1) Storage/StorageSection - instance uloziste (napr. " = window.gstor.sub('contents.detailDokumentu.spis');")</para>
    ///<para>2) "contents.detailDokumentu.spis" - klic v globalnim ulozisti zadany jmenem</para>
    ///<para>3) ["content.detailDokumentu", typDokumentu.toString()] - klic v globalnim ulozisti zadany polem</para>
    ///<para>4) false - explicitni vypnuti uloziste</para>
    ///<para>5) NULL/undefined - defaultne se pouzije umisteni ["contents", uid || id] </para>
    ///</param>
    ///<param name="isolated" type="bool">(default=false) 
    /// true znamena, ze content se pokusi defaultne ulozit jako root objekt. 
    /// false znamena, ze se objekt pokusi defaultne ulozit do nadrizeneho contentu. 
    /// 
    /// Typicky chceme, aby napr. contenty na zalozkach byly ukladany v ramci parent contentu detailu. Ale nektere contenty mohou byt izolovane, tzn. ze je chtene, 
    /// aby sdilely nastaveni napric ruznymi detaily a ruznymi umistenimi
    ///</param>
    /// <param name="container" type="bool">(default=true) zda tento content slouzi jako vychozi kontejner pro vnoreny obsah

    var uid = $(this.element).prop("uid") || $(this.element).prop("id");
    if (us == null && uid !== "_cont#" && !uid.startsWith("ui-id-")) us = ["contents", uid];

    this.userSettings = Gordic.Data.Storage.resolve(us, this.element, { isolated: typeof isolated === "boolean" ? isolated : this.isolatedUserSettings, container: container !== false });

    return this.userSettings;
};





