$.content = function (obj, multiple) {
    ///<signature>
    ///<summary>Najde příslušný GContent náležicí předanému HTMLElementu.</summary>
    ///<param name="element" type="HTMLElement">HTMLElement nebo jQuery DOM element, který leží na GContent.contentDiv. Pokud je NULL/undefined, vrátí všechny/první GContenty</param>
    ///<param name="multiple" type="bool">(default=false)zda nás zajímá jeden (první) GContent, nebo pole všech</param>
    ///<returns type="GContent">pro multiple==false vrací GContent nebo null; pro multiple==true vrací vždy jQuery GContent[] (je možné volat např.: .each)</returns>
    ///</signature>
    ///<signature>
    ///<summary>Najde příslušný GContent</summary>
    ///<param name="name" type="string">ID GContentu, resp. contentDivu</param>
    ///<param name="multiple" type="bool">(default=false)zda nás zajímá jeden (první) GContent, nebo pole všech</param>
    ///<returns type="GContent">pro multiple==false vrací GContent nebo null; pro multiple==true vrací vždy jQuery GContent[] (je možné volat např.: .each)</returns>
    ///</signature>
    multiple = multiple || false;
    if (obj instanceof GContent)
        return obj;
    else if (typeof (obj) == "string")   // nazev contentu 
        obj = $(".gcontent").filter(function () { return new RegExp("^" + obj.replace("#", "\\d+") + "$").test(this.id) || (this.uid == obj); });
    else if (obj instanceof GAction && obj.content)
        obj = $(obj.content.contentDiv);
    else if (isElement(obj) || obj instanceof jQuery) {
        var $obj = $([]);

        var cp = $(obj).gdomcontext()._contextPath;
        for (var i = 0; i < cp.length; i++) {
            var $e = $(cp[i]);
            if ($e.hasClass("gcontent") && !$e.hasClass("js-utility-content")) {
                $obj = $(cp[i]);
                break;
            }
        }
        if ($obj.length == 0) $(obj).closest(".gcontent");
        if ($obj.length == 0) { var c = $(obj).closest(".ContextMenu").parent(); if (c.length > 0) $obj = $(c[0].content.contentDiv); }  // jednoucelovka pro stare popupmenu
        obj = $obj;
    } else if (!obj)
        obj = $(".gcontent");

    if (obj instanceof jQuery) {
        if (multiple === true)
            return obj.get().map(function (cdiv) { return cdiv.content; });
        else if (obj.length > 0) return obj[0].content;
    }

    return (multiple === true ? [] : null);
}
$.findAction = function (name, actionList, context) {
    ///<summary>Najde instanci GAction podle nasledujicich pravidel (prvni vyhrava):
    ///<para>1) pokud je prvni parametr jiz instance GAction - vrati ji jako navratovou hodnotu </para>
    ///<para>2) pokusi se najit akci se shodnym nazvem v predanem seznamu actionList (pokud byl predan), muze byt objekt nebo pole</para>
    ///<para>3) pokud je v nazvu "." (napr.: "main.actOk"), pokusi se nalezt GContent se jmenem pred prvni "." a prohleda akce definovanem na nem</para>
    ///<para>4) pokud je v nazvu "*." (napr.: "*.actOk"), pokusi se nalezt akci v nadrazenych GContent s prioritou nejblizsiho(nejzanorenejsiho) obsahu (funguje jen pokud je zadan parametr "context")</para>
    ///</summary>
    ///<param name="name" type="string">Nazev referencovane akce ("actOk", "mainContent.actOk")</param>
    ///<param name="actionList" type="object">objekt akci, nebo pole akci, ktere se prohledava na vyskyt hledane akce</param>
    ///<param name="context" type="object">GContent/HTMLElement/jQuery kontextu, ktery se pouzije pro vyhledani v DOM</param>
    ///<returns type="GAction">vrati nalezenou akci nebo null</returns>
    if (name instanceof GAction) return name; // 1

    if (actionList) { // 2
        if (actionList[name]) return actionList[name]; // objekt akci
        for (var i = 0; i < actionList.length; i++) // pole akci
            if (actionList[i] && actionList[i].name == name) return actionList[i];
    }
    var m = /([^\.]+)\.([\w\.]+)/g.exec(name);
    if (m) {
        if (m[1] == "*" && context) { // 4
            var a = $.findAction(m[2], actionList);
            if (a) return a;
            var c = $.content(context).element.parent().closest(".gcontent").gcontent();
            if (c) a = $.findAction(name, c.actions, c);
            return a;
        } else {  // 3
            var c = $.content(m[1]);
            if (c && c.actions[m[2]]) return c.actions[m[2]];
        }
    }
    return null;
};
$.fn.gcontent = function () {
    ///<signature>
    ///<summary>Vytvoří GContent(y) ze současného pole (pouze div) prvků (ty ktere gcontent dosud nemaji)</summary>
    ///<param name="contentInitializer" type="object">inicializer GContent, který se má použit pro vytvoření GContent 
    /// <para>1) Název serverové třídy IGAjaxContent (např.: "Gordic.Gui.WebControls.GAjaxContentASPX")</para>
    /// <para>2) Použití registrované zástupky (např.: "ascx://Test.ascx"). Výchozí registrované zástupky jsou: "aspx://", "ascx://", "iframe://"</para>
    /// <para>3) Použití pole [className, params]</para>
    /// <para>4) Použití objektu {className:"", prop1: ..., prop2: ...}</para>
    /// </param>
    ///<returns type="jQuery">this</returns>
    ///</signature>
    ///<signature>
    ///<summary>nastavuje/cte parametry, metody a eventy GContentum. Napr. 
    ///.gcontent("params", {ixs:"DEMO00001234"})            // provede merge s content.params ("params" je vyjimka, ostatni vlastnosti by neprovedly merge, ale set)
    ///.gcontent("param", "ixs", "DEMO00001234"})           // zavola metodu content.param("ixs", "DEMO00001234")
    ///.gcontent("DetailIXS", "DEMO00001234")               // nastavi content.DetailIXS = "DEMO00001234"; 
    ///.gcontent({DetailIXS:"DEMO00001234", DetailIXS2:"DEMO00005678"}) 
    ///.gcontent("load", null, ["CallMethodName"])          // zavola metodu content.load(null, ["CallMethodName"]); 
    ///</summary>
    ///<param name="name">nazev vlastnosti, nebo metody GContent</param>
    ///<param name="value">nova hodnota vlastnosti GContent, parametry metody, null/undefined pro ziskani hodnoty</param>
    ///<returns type="jQuery">this, nebo navratovou hodnotu parametru/metody</returns>
    ///</signature>
    ///<signature>
    ///<summary>vrati GContent objekt(y) k seznamu elementu</summary>
    ///<param name="multiple" type="boolean">(default=false) zda chceme vratit pouze prvni (false), nebo pole vsech existujicich (true)</param>
    ///<returns type="GContent">nalezena/e instance GContent</returns>
    ///</signature>
    if (arguments.length == 0) // bez parametru vratime prvni GContent, ktery najdeme
        return $.content(this.filter(".gcontent"));
    if (arguments.length == 1 && typeof (arguments[0]) == "boolean")
        return $.content(this.filter(".gcontent"), arguments[0]);

    var args = Array.prototype.slice.call(arguments);

    var newC = this.filter("div:not(.gcontent)").each(function () {
        return GContent.createContent(args, this); //NOTE (BM 2025-04-23): Puvodni reseni nefungovalo u gcontentu bez dekoratoru (viz tento commit unittesty).
    });
    if (newC.length > 0) return this;   // protoze novy a existujici content pouzivaji pro stejne signatury ruzny vyznam, nebudeme nadale poustet obe varianty. 

    var retValue = undefined;
    this.filter(".gcontent").each(function () {
        var content = this.content; 
        if (!content) return;  // pokud se vola hromadny "close", tak se muze stat, ze item[0].close kaskadou pozavira i nektere dalsi a do each se dostanou jiz zavrene contenty (nemaji .content ani class)

        if (typeof (args[0]) == "object") {  // zjisteni seznamu prikazu
            var ops = args[0];
            for (var k in ops) {
                var member = content[k];
                if (typeof (member) == "function")
                    member.call(content, ops[k])
                else
                    content[k] = ops[k];
            }
        }
        else {
            var member = content[args[0]];
            if (typeof (member) == "function")
                retValue = member.apply(content, args.slice(1))  // retValue = ... ; pro navratove hodnoty z metod, ale zrusi se tim zretezeni
            else if (args.length == 1)
                retValue = member;
            else
                content[args[0]] = args[1];
        }
    });

    if (retValue === undefined || GContent.prototype.isPrototypeOf(retValue)) return this;  // GContent se vraci z hodne funkci pro potreby zretezeni. Proto pri volani z jQuery zretezime jQuery.  
    else return retValue;
};






