//#region gtasklist (seznam uloh)
//#region popis
//Inspirovano:      http://gohooey.com/demo/sidebar/bootstrapnavigation/hoedemo.html
//Vyuziva ikony:    http://fortawesome.github.io/Font-Awesome/icons/
//POPIS
//======================================================
//TODO:...
//
//Vytvoreni hlavicky s logem:
//---------------------------
//  - nutno vytvorit option header takto: 
//  {
//      applicationAbbr: "",     //Tri pismenna zkratka modulu (napr. UCR)
//      applicationRevision: ""  //Revize modulu
//  }
//
//Udalosti (widgetove):
//------------------------------------------------------
// - collapsed - tasklist byl smrsknut
// - expanded - tasklist byl rozevren
//#endregion

$.widget("gordic.gtasklist", $.gordic.gmenu, {
    options: {
        header: {
            applicationAbbr: "",
            applicationRevision: ""
        },
        collapsed: false,
        tooltipDelay: 1000,      //Zpozdeni tooltipu
        scrollbarSlideDelay: 200,//Doba rozevirani/zavirani podmenu
        userSettings: null,
        prepareDataOnInit: true,
        createActionUrl: null
    },
    _currentProfiledParams: null, //MenuParams[]
    _closeHandler: null,
    _activesBuff: null, //JQuery[]
    _create: function () {
        this.element.addClass("gtasklist");
        this.options.settings.rootOrientation = GMenu.menuRootOrientation.vertical;
        this.options.settings.createActionUrl = this.options.createActionUrl;
        this._gmenu = new GTaskList(this.element, this.options.settings);
        this._activesBuff = [];
        var $wg = this;
        this._on(this.element, {
            "click a": "_click",
            "click li.js-gmenu-html": "_click",
            "inlineopen": "_inlineopen",
            "inlineclose": "_inlineclose"
        });
        this.element.gshortcut({
            key: ["space", "enter"],
            visible: false,
            action: new GAction({
                name: "clickAct", run: function (ev) {
                    $(ev.target).click();                                           //Nutno kvuli rozbaleni/sbaleni
                    $(ev.target).trigger(GMenu.defaultSettings.runActionEventName); //Nutno kvuli spousteni akci
                }
            })
        });
        this.element.on("tasklistbeforeactionrun", function (ev) {
            $wg._activesBuff.push($(ev.target));
        });

        this._closeHandler = function (ev) { $wg._inlineCloseDelayed($wg); };

        this.refresh();
    },
    _destroy: function () {
        //Zakladni uklid
        this._partialCleanup();
        this.element.gshortcut(null); //likvidace vl. zkratek
        Gordic.ResizeManager.unobserve(this.element[0], "gtasklist");
        this.element
            .removeClass("gtasklist js-gmenu")
            .css("width", "");

        console.log("##T13938##, gtasklist:_destroy"); //##T13938##
    },
    _partialCleanup: function() {
        /// <summary>Castecne uklidi obsah widgetu</summary>
        this.element.empty();
        this.element.find(".js-taks-list-expand-collapse").off("click");
        this._gmenu.inlines.remove();
        this._gmenu.inlines = $([]);
    },
    refresh: function (options) {
        /// <summary>Vybuildi tasklist. Je-li option undefined, provede cistku puvodniho tasklistu.</summary>
        if (options !== undefined)
            this._partialCleanup();

        var $wg = this;
        if (this.options.header) {
            var $header =
                $("<div class='ui-front js-task-list-header g-tl-header'>" +
                    "<span class='js-tl-collapsible js-tl-head-abbr g-tl-header__abbr'>" + this.options.header.applicationAbbr + "</span>" +
                    (this.options.header.applicationRevision ? "<span class='js-tl-collapsible js-tl-head-rev g-tl-header__rev'>" + this.options.header.applicationRevision + "</span>" : "") +
                    "<a class='js-taks-list-expand-collapse g-tl-header__btn' tabindex='0' role='button' aria-label='jres:31150170'>" + //RC 31150170 : Smrsknout stromu úloh
                        "<i class='gi gi-sbalit_tasklist' aria-hidden='true'></i>" +
                    "</a>" +
                "</div>");

            this.element.append($header);

            $header.find(".js-taks-list-expand-collapse").on("click", function (e) {
                $wg._setOption("collapsed", !$wg.options.collapsed);
            });
        }

        this.options.settings = this._gmenu.settings;

        var oParams = this.params();
        if (this.options.prepareDataOnInit) {
            GMenu.completeParamsArray(oParams, this.options.actions || []);
            Gordic.Utils.Menu.makeIds(oParams);
            Gordic.Utils.Menu.resolveParams(oParams);
        }

        this._currentProfiledParams = this._applyProfile(this._loadProfile(), oParams);

        var paramsToRender = $.extend(true, [], this._currentProfiledParams);
        this._trigger("internalBeforeRefresh", null, [paramsToRender]);

        this._gmenu.build(
            paramsToRender,
            this.actions(),
            this.addClass());

        this.element.css("width", this.expandedWidth() + "rem");

        //Odstraneni marginu ikon 1. a 2. urovne (je to prasarna, pozdeji zrefaktorit)
        this.element.find(".g-tl-item-level-0>a>i")
            .add(this.element.find(".g-tl-item-level-1>a>i"))
            .css("margin-left", "");

        //Spodni cast tasklistu
        var topListHeight = this.element.children("ul." + GMenu.menuRootAlignOppositeClassName)
            .addClass("g-tl-item-root--bottom")
            .css("width", this.expandedWidth() + "rem")
            .wrap("<div class='js-tl-bottom-wrp' style='position: absolute; bottom: 0;'>");

        //Vytvoreni tooltipu v horni casti js-gmenu-itm
        $.each(this.element
                .find("ul." + GMenu.menuRootAlignNormalClassName)
                .find("li.js-gmenu-itm"), function () {
                    var $itm = $(this);
                    var p = $itm.prop(GMenu.buildParamPropertyName);
                    $itm.gtooltip({
                        caption: p.caption,
                        tooltip: p.tooltip,
                        show: { delay: $wg.options.tooltipDelay },
                        position: {
                            my: "left top",
                            at: "right top",
                            of: $itm,
                            shift: { left: 4, top: 0 }
                        },
                        showCaption: function () {
                            var isCollapsed = $wg.options.collapsed;
                            if (!isCollapsed || $itm.children(".g-tl-item--level-0").length === 0)
                                return false;

                            return !$itm.children(".js-tl-sublist-first-level").is(":visible");
                        }
                    });
            });

        //Vytvoreni tooltipu ve spodni casti
        $.each(this.element
            .find("ul." + GMenu.menuRootAlignOppositeClassName)
            .children("li"),
            function () {
                var $btn = $(this);
                var params = $btn.prop(GMenu.buildParamPropertyName);

                if (!params)
                    return;

                var caption = params.caption;
                var tooltip = params.tooltip;
                if ((caption === "" || caption === GAction.defaultParams.caption) && tooltip === undefined)
                    return;
                
                $btn.gtooltip({
                    caption: caption,
                    tooltip: tooltip,
                    delay: $wg.options.tooltipDelay,
                    //show: { delay: $wg.options.tooltipDelay },
                    showCaption: function () { return true; },
                    position: {
                        my: "left bottom",
                        at: "left top",
                        of: $btn,
                        shift: { left: 0, top: 5 }
                    }
                });

                $btn.children("a").attr("aria-label", params.ariaCaption || caption || tooltip);
            });

        //Horni cast tasklistu 
        this._updateTopHeight();
        this._createScrollbar(this.element.find(".js-gmenu-aling-normal"));

        if (this.options.userSettings)
            this.element.find(".g-tl-item-root").first().attr("data-admin-mode-nav-assist", "contents.main.tasklist");

        //Pokud je pozdovan collapsed stav provede se uprava stavu.
        if (this.options.collapsed)
            this.collapse();
    },
    _setOption: function (key, value) {
        var currVal = this.options[key];
        this._super(key, value);
        if (key === "collapsed" && currVal !== value)
            this._updateState(value);
        if (key === "expandedWidth") {
            this.options.settings.expandedWidth = value;
            this.options.settings.computeWidth();
            this.refresh();
        }
    },
    collapse: function () {
        if (this.element.hasClass("g-task-list-collapsed")) return;

        this.element.find(".js-tl-collapsible")
            .hide()
            .css("position", "absolute");
        this.element.find(".js-sublist").hide();
        this.element.css("width", this.collapsedWidth() + "rem");
        //this.element.width(this.collapsedWidth());
        this.element.find("." + GMenu.menuRootAlignOppositeClassName)
            .css("width", this.collapsedWidth() + "rem");

        this.element.find(".g-tl-item--level-0")
                    .children(".js-tl-expander")
                    .hide();

        //Pro typ HTML v rootu zobrazi ikonu    //TODO: Zrefaktorit HTML TYP
        this.element.find(".js-task-list-html-icon")
            .show()
            .parent() //sub
            .addClass("taskListCollapsed")      //padding: 10px
            .parent() //div
            .addClass("taskListCollapsed")      //padding: 10px 5px 10px 5px
            .removeClass("taskListHtmItem");    //padding: 5px

        this._destroyScrollbar(this.element.find(".js-gmenu-aling-normal"));

        //Skryje vsechny polozky zespod pod jednu ikonu
        this.element.find(".js-task-list-bottom-root-item")
            .show()
                .children(".js-task-list-bottom-menu")
                .append(this.element.find("ul." + GMenu.menuRootAlignOppositeClassName)
                    .children("li")
                    .not(".js-task-list-bottom-root-item")
                    .removeClass("gmenu"))
                .hide();

        //Zrusi zobrazeni aktivni rozbalene polozky
        this.element.find(".gmenu.g-tl-item--expanded")
            .removeClass("g-tl-item--expanded");

        this._resetExpand();

        //Prohozeni ikony pro expand/collapse button
        this.element.find(".js-taks-list-expand-collapse")
            .attr("aria-label", "jres:31150171") //RC 31150171 : Roztáhnout strom úloh
            .children("i")
            .first()
            .removeClass("gi-sbalit_tasklist")
            .addClass("gi-rozbalit_tasklist");

        this.element.find(".js-task-list-settings").addClass("hidden");

        this.element.find(".js-task-list-exp-coll-rect").css({
            "right": "",
            "left": "0"
        });

        this.element.find(".js-tl-sublist-first-level").addClass("ui-front");
        //this.element.find(".js-tl-bottom-wrp").addClass("ui-front"); //Skryto na poz. TSkaly, aby bylo mozny fullscreen mode pro grid. Nevyhodou je, ze pokud na to nekdo klikne a bude otevreny dialog, otevre se to az za nim...no ale co, tak si ho proste posune :-)

        this.element.addClass("g-task-list-collapsed");

        //Skryti badges na rootove urovni
        this.element.find(".js-gmenu-aling-normal>li>a>div.gbadge").hide();
        this._updateMarkedItem();

        this._trigger("collapse");
    },
    expand: function () {
        if (!this.element.hasClass("g-task-list-collapsed")) return;

        this.element.find(".js-sublist").hide();

        //Skryvatelne polozky v 1. urovni
        this.element.find(".js-tl-collapsible")
            .removeClass("g-tl-item__text--expanded")
            .show()
            .css({
                "left": "",
                "top": "",
                "min-height": "",
                "position": "",
                "width": "",
                "display": ""
            });

        this.element.removeClass("js-task-list-collapsed")
            .css("width", this.expandedWidth() + "rem");
        this.element.find("." + GMenu.menuRootAlignOppositeClassName)
            .css("width", this.expandedWidth() + "rem");

        this.element.find(".g-tl-item--level-0")
                    .children(".js-tl-expander")
                    .css("display", "");

        this.element.find(".js-tl-sublist-first-level")
            .css({
                "position": "relative",
                "left": "",
                "top": "",
                "width": "100%"
            });

        //Pro typ HTML v rootu skryje ikonu
        this.element.find(".js-task-list-html-icon")
            .hide()
            .parent() //sub
            .removeClass("taskListCollapsed")   //odstrani padding
            .parent() //div
            .removeClass("taskListCollapsed")   //padding: 10px 5px
            .addClass("taskListHtmItem");       //padding: 5px 

        //Zobrazi vsechny polozky zespod
        this.element.find(".js-task-list-bottom-root-item")
            .hide()
            .children("ul")
            .children("li")
            .appendTo(this.element.find(".js-task-list-bottom-root-item").parent())
            .addClass("gmenu");

        //Vytvoreni hlavniho scrollbaru v expanded rezimu
        this._createScrollbar(this.element.find(".js-gmenu-aling-normal"));

        //Zruseni scrollbaru na 1. urovni, ktere byly vytvoreny v collapsed modu
        this._destroyScrollbar($(".js-tl-sublist-first-level").css("max-height", ""));

        this._resetExpand();

        //Prohozeni ikony pro expand/collapse tasklistu
        this.element.find(".js-taks-list-expand-collapse")
            .attr("aria-label", "jres:31150170") //RC 31150170 : Smrsknout stromu úloh
            .children("i")
            .first()
            .removeClass("gi-rozbalit_tasklist")
            .addClass("gi-sbalit_tasklist");

        this.element.find(".js-task-list-settings").removeClass("hidden");

        this.element.find(".js-task-list-exp-coll-rect").css({
            "right": "0",
            "left": ""
        });
        this.element.find(".js-tl-sublist-first-level").removeClass("ui-front");
        //this.element.find(".js-tl-bottom-wrp").removeClass("ui-front"); //Skryto na poz. TSkaly, aby bylo mozny fullscreen mode pro grid. Nevyhodou je, ze 

        this.element.removeClass("g-task-list-collapsed");
        
        //Zobrazeni badges na rootove urovni
        this.element.find(".js-gmenu-aling-normal>li>a>div.gbadge").show();
        this._updateMarkedItem();
        this._trigger("expand");
    },
    collapsev: function (includeIds, excludeIds) {
        /// <summary>Provede vertikalni collapse (skova vsechny rozbalene)</summary>
        /// <param name='includeIds' type='string'>Id, ktere maji byt schovany. String obs. id. Je-li jich vice, jsou oddelene carkou</param>
        /// <param name='excludeIds' type='string'>Id, ktere nemaji byt schovany. String obs. id. Je-li jich vice, jsou oddelene carkou</param>

        var $expanded = this.element.find(".js-tl-expanded");

        if (includeIds) {
            var includes = includeIds.split(",");
            $expanded = $expanded.filter(function (index, elm) {
                var $elm = $(elm);
                for (var i = 0; i < includes.length; i++)
                    if ($elm.attr("data-param-id") === includes[i])
                        return true;
                return false;
            });
        }

        if (excludeIds) {
            var excludes = excludeIds.split(",");
            $expanded = $expanded.filter(function (index, elm) {
                var $elm = $(elm);
                for (var i = 0; i < excludes.length; i++)
                    if ($elm.attr("data-param-id") === excludes[i])
                        return false;
                return true;
            });
        }

        if ($expanded.length === 0) return $.Deferred().resolve().promise();
        var promise = this._toggleSubmenu($expanded);
        if (promise) return promise;
        return $.Deferred().resolve().promise();
    },
    _updateTopHeight: function () {
        /// <summary>Upravi vysku horniho divu s akcema</summary>
        var headerHeight = this.element.find(".js-task-list-header").outerHeight() || 0;
        //var bottomHeight = this.element.find("ul." + GMenu.menuRootAlignOppositeClassName).parent().outerHeight();
        var bottomHeight = this.element.find(".js-tl-bottom-wrp").outerHeight() || 0;
        this.element.find("ul." + GMenu.menuRootAlignNormalClassName).css("height", "calc(100% - " + Number(headerHeight + bottomHeight) + "px)");

    },
    _resetExpand: function () {
        this.element.find(".gi-rot180").removeClass("gi-rot180");
        this.element.find(".js-tl-expanded").removeClass("js-tl-expanded");
        this.element.find(".g-tl-item--expanded").removeClass("g-tl-item--expanded");
    },
    expandedWidth: function () {
        /// <summary>Vrati vypoctenou sirku tasklistu v expanded stavu v px (pouze getter)</summary>
        return this.options.settings.computedExpandedWidth;
    },
    collapsedWidth: function () {
        /// <summary>Vrati vypoctenou sirku tasklistu v collapsed stavu v px (pouze getter)</summary>
        return this.options.settings.collapsedWidth;
    },
    _updateState: function (collapsed) {
        /// <summary>Upravi stav (collapse/expand)</summary>
        /// <param name='collapsed' type='boolean'>True = poz. collapsed, false = poz. expanded.</param>
        if (collapsed)
            this.collapse();
        else
            this.expand();
    },
    _click: function(event) {
        //console.log("gtasklist._click", event, this);

        var $wg = this;
        var $target = $(event.target).closest(".js-tl-item"); //<a> nebo <li> (pro typ html)
        var $li = $target.closest("li.js-gmenu-itm");
        var $childUl = $li.children("ul.js-sublist");
        var $expanderIcon = $target.children(".js-tl-expander");
        var $collapsible = $target.children(".js-tl-collapsible");

        //console.log("gtasklist._click", $target, $collapsible, $li);

        if (this.options.collapsed && $collapsible.length !== 0) {

            //skryti vsech aktualne otevrenych podmenu           
            this.element.find(".js-tl-expanded").not(function (index, element) {
                            return $target[0] === element;
                        })
                        .removeClass("js-tl-expanded g-tl-item--expanded")
                        .children(".js-tl-collapsible")
                        .removeClass("g-tl-item__text--expanded")
                        .hide()
                        .parent()
                        .siblings("ul.js-sublist")
                        .hide();

            //Napozicovani menu 1. urovne pod span s caption
            if (!$collapsible.is(":visible") && !$li.hasClass("js-gmenu-action")) {
                //Zobrazeni aktualni
                $collapsible.addClass("g-tl-item__text--expanded")
                            .css({
                                "min-height": $li.height(),
                                "width": this.expandedWidth() + "rem"
                            });

                $target.addClass("js-tl-expanded g-tl-item--expanded");
                $collapsible.show()
                            .position({
                                of: $li,
                                my: "left top",
                                at: "right top"
                            });
                
                if ($childUl.hasClass("js-tl-sublist-first-level")) {
                    var at = $li.hasClass("js-task-list-bottom-root-item")
                                ? "left top" : "left bottom";
                    $childUl.show()
                            .css("position", "absolute")
                            .css("width", this.expandedWidth() + "rem")
                            .position({
                                of: $collapsible,
                                my: "left top",
                                at: at
                            });

                    var ulTop = $childUl.offset().top;
                    var ulMaxHeight = ulTop < 0
                        ? Math.floor($childUl.outerHeight() + ulTop)
                        : Math.floor(window.innerHeight - ulTop);

                    //Upravime vysku a pro sichr znovu i pozici (muze byt mimo obrazovku v pripadech, kdy top < 0)
                    $childUl.css("max-height", ulMaxHeight)
                        .position({
                            of: $collapsible,
                            my: "left top",
                            at: at
                        });

                    this._createScrollbar($childUl);
                    this._initDocumentEventHandling();
                }
            }
            else {
                this._hideAllExpanded();
                this._uninitDocumentEventHandling();
            }

            this._updateMarkedItem();

            return;
        }

        $wg._toggleSubmenu($li, $childUl, $target, $expanderIcon);
    },
    _hideAllExpanded: function () {
        if (!this.options.collapsed) return;
        var _this = this;
        var $expanded = this.element.find(".js-tl-expanded");
        $expanded.each(function () {
            var $this = $(this);
            var $collapsible = $this.children(".js-tl-collapsible");
            var $childUl = $this.next("ul.js-sublist");

            $collapsible.hide();
            $childUl.hide();
            $this.removeClass("g-tl-item--expanded");
            $childUl.css("max-height", "");
            _this._destroyScrollbar($childUl);
        });
    },
    _inlineopen: function (event) {
        var $li = $(event.target);
        this.element.find(".js-task-list-active").removeClass("js-task-list-active");
        this.element.find(".g-tl-item--active").removeClass("g-tl-item--active");
        $li.find(".js-tl-item").addClass("js-task-list-active");
        this._updateMarkedItem();
    },
    _inlineclose: function (event) {
        var $li = $(event.target);
        $li.find(".js-task-list-active").removeClass("js-task-list-active g-tl-item--expanded g-tl-item--active g-tl-item--marked");
        this._updateMarkedItem();
    },
    //#region Toto by v budoucim TL byt nemelo - vyresit to standardne pres inline
    _inlineCloseDelayed: function (_this) {
        setTimeout(function () {
            var shouldBeClosed = !$.contains(_this.element[0], document.activeElement);
            if (shouldBeClosed) {
                _this._hideAllExpanded();
                _this._uninitDocumentEventHandling();
            }
        }, 100);
    },
    _initDocumentEventHandling: function () {
        this._uninitDocumentEventHandling();
        document.addEventListener("mouseup", this._closeHandler, false);
        document.addEventListener("mousedown", this._closeHandler, true);
    },
    _uninitDocumentEventHandling: function () {
        document.removeEventListener("mouseup", this._closeHandler, false);
        document.removeEventListener("mousedown", this._closeHandler, true);
    },
    //#endregion
    _toggleSubmenu: function ($liParent, $ulChildren, $a, $expanderIcon) {
        //console.log("gtasklist._toggleSubmenu", $liParent, $ulChildren, $a, $expanderIcon);
        $ulChildren = $ulChildren || $liParent.children("ul.js-sublist");
        $a = $a || $liParent.children("a.js-tl-item");
        $expanderIcon = $expanderIcon || $a.children(".js-tl-expander");

        //NOTE: Html typ by se nemel oznacovat ani rozbalovat potomky
        if ($liParent.hasClass(GMenu.menuTypeHtmlClassName))
            return;

        var isOpen = $ulChildren.is(":visible");

        if (!isOpen && !$liParent.hasClass("js-gmenu-action")) {
            $liParent.addClass("js-tl-expanded");
            $expanderIcon.addClass("gi-rot180");
            $a.addClass("g-tl-item--expanded")
                .attr("aria-expanded", "true");
        }
        else {
            $liParent.removeClass("js-tl-expanded");
            $expanderIcon.removeClass("gi-rot180");
            $a.removeClass("g-tl-item--expanded")
                .attr("aria-expanded", "false");
        }

        var $wg = this;
        //Rozbaleni/sbaleni pod-menu
        if (!(this.options.collapsed && $liParent.parent().hasClass("g-tl-item-root"))) {
            if (isOpen) {
                return $ulChildren.slideUp(this.options.scrollbarSlideDelay, function () {
                    //$wg._destroyScrollbar(this);
                    $wg._updateMarkedItem();
                }).promise();
            }
            else {
                return $ulChildren.slideDown(this.options.scrollbarSlideDelay, function () {
                    $wg._updateMarkedItem();
                    if(!$wg._hasScrollbar(this))
                        $wg._createScrollbarCollapsed(this);
                }).promise();
            }
        }
        return null;
    },
    _updateMarkedItem: function ($elm) {
        /// <summary>Pokud neni aktivni polozka videt, pokusi se najit parenta, ktery je viditelny a toho oznaci jako 'marked'.</summary>
        var $active = $elm || this.element.find(".js-task-list-active");
        this.element.find(".g-tl-item--marked")
            .removeClass("g-tl-item--marked");

        if ($active.hasClass("g-tl-item--level-0"))
            $active.addClass("g-tl-item--marked");

        if ($active.is(":visible"))
            return;

        $active.parents(".js-gmenu-itm:visible")
               .eq(0)
               .children(".js-tl-item")
               .addClass("g-tl-item--marked");
    },
    _createScrollbar: function ($elm) {
        /// <summary>
        /// Vytvori scrollbar na param 'ctl'
        /// </summary>
        /// <param name='ctl' type='HTMLElement nebo jQuery'>Element(y) pro vytvoreni scrollbaru.<param>
        $($elm).addClass("g-tl-scrollable-items").css("overflow", "hidden auto");
    },
    _createScrollbarCollapsed: function ($elm) {
        /// <summary>
        /// Vytvori scrollbar na ul 1. urovne pokud je tasklist collapsed
        /// </summary>
        var $firstLevelUl = $($elm).closest(".js-tl-sublist-first-level");
        if (this._hasScrollbar($firstLevelUl) || !this.options.collapsed)
            return;

        var top = $firstLevelUl.offset().top - $(window).scrollTop();
        var ulHeight = $firstLevelUl.closest(".js-tl-sublist-first-level").outerHeight();
        var windowHeight = $(window).height();

        if (windowHeight < top + ulHeight) {
            $firstLevelUl.css("max-height", windowHeight - top + "px");
            this._createScrollbar($firstLevelUl);
        }
    },
    _destroyScrollbar: function (elm) {
        /// <summary>
        /// Zrusi vsechny obsazene scrollbary
        /// </summary>
        /// <param name='ctl' type='HTMLElement nebo jQuery'>Element(y) ke zruseni scrollbaru.</param>
        $(elm).removeClass("g-tl-scrollable-items").css("overflow", "");
    },
    _hasScrollbar: function (elm) {
        return $(elm).hasClass("g-tl-scrollable-items");
    },
    _loadProfile: function () {
        if (!this.options.userSettings) return null;
        var profile = this.options.userSettings.get("menuProfile") || null;
        if (profile) Gordic.Utils.Menu.GMenuProfileBuilder.verifyStructure(profile)
        return profile;
    },
    _saveProfile: function (profile /* ?: Gordic.Utils.Menu.IGMenuProfile | null */) {
        var settings = this.options.userSettings;
        if (!settings || typeof profile === "undefined") return;

        if (profile) settings.set("menuProfile", profile);
        else settings.remove("menuProfile");

        settings.save();
    },
    _isMenuCustomizationEnabled: function () {
        var settings = this.options.userSettings;
        return settings && !settings.isVirtual() && !settings.isLocked("menuProfile");
    },
    _applyProfile: function (profile, params) {
        if (!profile) return params;
        return Gordic.Utils.Menu.applyProfile(profile, params);
    },
    _resetActive: function ($active) {
        ($active || this.element.find(".js-task-list-active")).removeClass("js-task-list-active");
        this.element.find(".g-tl-item--active").removeClass("g-tl-item--active");
        this.element.find(".g-tl-item--marked").removeClass("g-tl-item--marked");
    },
    _expandActiveParents: function ($active) {
        //po-rozbalovani parentu
        var $parents = $active.parent().parents(".js-gmenu-itm").not(".js-tl-expanded");
        var chain = $.when();
        for (var i = $parents.length - 1; i >= 0; i--) {
            var promise = this._toggleSubmenu($parents.eq(i));
            if (promise)
                chain = chain.then(promise);
        }
    },
    _clearActivesBuff: function () { this._activesBuff = []; },
    setActive: function (id, autorun) {
        /// <signature>
        ///<summary>Nastavi aktivni polozku podle ID</summary>
        ///<param name='id' type='String'>ID z params<param>
        /// </signature>
        /// <signature>
        ///<summary>Nastavi aktivni polozku list item</summary>
        ///<param name='id' type='HTMLElement nebo jQuery'>Element<param>
        /// </signature>
        
        var $active = $([]), $buffered = this._activesBuff.length > 0 ? this._activesBuff[this._activesBuff.length - 1] : undefined;
        var resetActive = true;

        if (typeof id === "undefined" || (typeof id === "string" && id === "")) {
            if ($buffered) $active = $buffered;
            resetActive = $active.length > 0;
        }
        else if (id === null)               { resetActive = true; } //Jen kvuli linteru
        else if (id instanceof jQuery)      { $active = id; }
        else if (id instanceof HTMLElement) { $active = $(id); }
        else if (typeof id === "string") {
            var $currActive = this.element.find(".js-task-list-active");

            if ($currActive.parent().attr(gparam.idAttrName) === id && this._activesBuff.length === 0) { resetActive = false; $active = $currActive; }
            else {
                if ($buffered && ($buffered.attr(gparam.idAttrName) === id || $buffered.hasClass(id))) $active = $buffered;
                else $active = $("[" + gparam.idAttrName + "=" + id + "]", this.element);

                if ($active.length === 0) $active = $("." + id, this.element).first();
                if ($active.length === 0) $active = this._gmenu.inlines.find("[" + gparam.idAttrName + "=" + id + "]").first();
            }
        }
        else throw new GError("gtasklist.setActive(): id is not supported");

        this._clearActivesBuff();

        if (resetActive) this._resetActive();

        $active.children("a.g-tl-item").addClass("js-task-list-active g-tl-item--active");

        this._updateMarkedItem($active);

        //Parenti mohou byt skryti, takze overit (spustit rozbalovani)
        if (!this.options.collapsed && $active.length) this._expandActiveParents($active);

        if (typeof autorun === "boolean" && autorun) { $active.click(); }
    },
    getActive: function () {
        ///<summary>V poli vrati aktivni polozku a vsechny jeji parenty (serazeno od polozky az k nejvyssimu parentovi)</summary>
        var $active = this.element.find(".js-task-list-active");
        var params = [];

        if ($active.length === 0)
            return params;

        params.push($active.parent().prop(GMenu.buildParamPropertyName));

        $.each($active.parents(".js-gmenu-itm"), function () {
            params.push($(this).prop(GMenu.buildParamPropertyName));
        });

        return params;
    },
    loadProfile: function () { return this._loadProfile(); },
    saveProfile: function (profile /* ?: Gordic.Utils.Menu.IGMenuProfile | null */) { this._saveProfile(profile); },
    isCustomizationEnabled: function () { return this._isMenuCustomizationEnabled(); },
    getParams: function () {
        return this._currentProfiledParams;
    }
});

//#endregion

//#region jquery ui menu overrides
//#region popis
/*
 * Udalosti:
 *      - rootCollapse - pokud byla zmacknuta klavesa ESCAPE nebo SIPKA VLEVO a uz neni submenu, ktere by bylo mozne zavrit.
 * 
 */
//#endregion


$.widget("gordic.uimenu", $.ui.menu, {
    options: {
        runActionEventName: GMenu.defaultSettings.runActionEventName
    },
    delay: 50,
    _create: function () {
        this.options.icons.submenu = "gi gi-arrow-down";

        this.element.addClass("uimenu");
        this.activeMenu = this.element;

        // Flag used to prevent firing of the click handler
        // as the event bubbles up through nested menus
        this.mouseHandled = false;
        this.element
            .uniqueId()
            .addClass("ui-menu ui-widget ui-widget-content")
            .toggleClass("ui-menu-icons", !!this.element.find(".ui-icon").length)
            .attr({
                role: this.options.role,
                tabIndex: 0
            });

        if (this.options.disabled) {
            this.element
                .addClass("ui-state-disabled")
                .attr("aria-disabled", "true");
        }

        this._on({
            // Prevent focus from sticking to links inside menu after clicking
            // them (focus should always stay on UL during navigation).
            "mousedown .ui-menu-item": function (event) {

                //B: Zruseni kvuli pouziti parametru typu HTML
                if (!this._isClickMenuCatchable(event.target))
                    return;

                event.preventDefault();
            },
            "click .ui-menu-item": function (event) {
                var target = $(event.target);
                event.preventDefault();

                //B: Zruseni kvuli pouziti parametru typu HTML
                if (!this._isClickMenuCatchable(event.target))
                    return;
                
                if (!this.mouseHandled && target.not(".ui-state-disabled").length) {
                    this.select(event);

                    // Only set the mouseHandled flag if the event will bubble, see #9469.
                    if (!event.isPropagationStopped()) {
                        this.mouseHandled = true;
                    }

                    // Open submenu on click
                    if (target.has(".ui-menu").length) {
                        this.expand(event);
                    } else if (!this.element.is(":focus") && $(this.document[0].activeElement).closest(".ui-menu").length) {

                        // Redirect focus to the menu
                        this.element.trigger("focus", [true]);

                        // If the active item is on the top level, let it stay active.
                        // Otherwise, blur the active item since it is no longer visible.
                        if (this.active && this.active.parents(".ui-menu").length === 1) {
                            clearTimeout(this.timer);
                        }
                    }
                }
            },
            "mouseenter .ui-menu-item": function (event) {
                // Ignore mouse events while typeahead is active, see #10458.
                // Prevents focusing the wrong item when typeahead causes a scroll while the mouse
                // is over an item in the menu
                if (this.previousFilter) {
                    return;
                }
                var target = $(event.currentTarget);
                // Remove ui-state-active class from siblings of the newly focused menu item
                // to avoid a jump caused by adjacent elements both having a class with a border
                target.siblings(".ui-state-active").removeClass("ui-state-active");
                this.focus(event, target);
            },
            mouseleave: "collapseAll",
            "mouseleave .ui-menu": "collapseAll",
            focus: function (event, keepActiveItem) {
                // If there's already an active item, keep it active
                // If not, activate the first item
                var item = this.active || this.element.find(this.options.items).eq(0);

                if (!keepActiveItem) {
                    this.focus(event, item);
                }
            },
            blur: function (event) {
                this._delay(function () {
                    if (!$.contains(this.element[0], this.document[0].activeElement)) {
                        this.collapseAll(event);
                    }
                });
            },
            keydown: "_keydown"
        });

        this.refresh();

        // Clicks outside of a menu collapse any open menus
        this._on(this.document, {
            click: function (event) {
                if (this._closeOnDocumentClick(event)) {
                    this.collapseAll(event);
                }

                // Reset the mouseHandled flag
                this.mouseHandled = false;
            }
        });
    },
    _destroy: function () {
        this._super();
        this.element.removeClass("uimenu");
    },
    _keydown: function (event) {

        if (event.isDefaultPrevented())
            return;

        var match, prev, character, skip,
            preventDefault = true;

        switch (event.keyCode) {
            case $.ui.keyCode.PAGE_UP:
                this.previousPage(event);
                break;
            case $.ui.keyCode.PAGE_DOWN:
                this.nextPage(event);
                break;
            case $.ui.keyCode.HOME:
                this._move("first", "first", event);
                break;
            case $.ui.keyCode.END:
                this._move("last", "last", event);
                break;
            case $.ui.keyCode.UP:
                this.previous(event);
                break;
            case $.ui.keyCode.DOWN:
                this.next(event);
                break;
            case $.ui.keyCode.LEFT:
                this.collapse(event);
                break;
            case $.ui.keyCode.RIGHT:
                if (this.active && !this.active.is(".ui-state-disabled")) {
                    this.expand(event);
                }
                break;
            case $.ui.keyCode.ENTER:
            case $.ui.keyCode.SPACE:
                this._activate(event);
                break;
            case $.ui.keyCode.ESCAPE:
                this.collapse(event);
                break;
            default:
                //console.log(event.key);
                //console.log(event.keyCode);
                preventDefault = false;

                //prev = this.previousFilter || "";
                //character = String.fromCharCode(event.keyCode);
                //skip = false;

                //clearTimeout(this.filterTimer);

                //if (character === prev) {
                //    skip = true;
                //} else {
                //    character = prev + character;
                //}

                //this.previousFilter = character;
                //this._trigger("search", event, { searchTerm: this.previousFilter });
                //console.log(this.previousFilter);
                
                //TODO: Vyhodit udalost, chytnout v GMenu, vyhledavni dle _filterMenuItems

                //this.filterTimer = this._delay(function () { delete this.previousFilter; }, 1000);

                //match = this._filterMenuItems(character);
                //match = skip && match.index(this.active.next()) !== -1 ?
                //    this.active.nextAll(".ui-menu-item") :
                //    match;

                //// If no matches on the current filter, reset to the last character pressed
                //// to move down the menu to the first item that starts with that character
                //if (!match.length) {
                //    character = String.fromCharCode(event.keyCode);
                //    match = this._filterMenuItems(character);
                //}

                //if (match.length) {
                //    this.focus(event, match);
                //    this.previousFilter = character;
                //    this.filterTimer = this._delay(function () {
                //        delete this.previousFilter;
                //    }, 1000);
                //} else {
                //    delete this.previousFilter;
                //}
        }

        if (preventDefault) {
            event.preventDefault();
        }
    },
    _isClickMenuCatchable: function (evTarget) {
        /// <summary>
        /// Mel by byt click v menu odchycen?
        /// </summary>
        return $(evTarget).closest("." + GMenu.menuItemClickCloseIgnoredClassName).length === 0;
    },
    _isDivider: function () {
        /// <summary>Zruseni defaultnich oddelovacu (jquery ui menu umoznuje udelat oddelovac timto zpusobem: <li>-</li>, ale u me v menu to dela paseku)</summary>
        return false;
    },
    clearFilter: function () {
        /// <summary>Vymaze vyhledavaci filtr</summary>
        delete this.previousFilter;
    },
    _move: function (direction, filter, event, ignoreSearchDiv) {
        //console.log("uimenu._move, direction: ", direction, "filter:", filter, this.active);
        var next;
        if (this.active) {
            if (direction === "first" || direction === "last") {
                next = this.active
                    [direction === "first" ? "prevAll" : "nextAll"](".ui-menu-item:visible")
                    .not(".ui-state-disabled")
                    .eq(-1);
            } else {
                next = this.active
                    [direction + "All"](".ui-menu-item:visible")
                    .not(".ui-state-disabled")
                    .eq(0);
            }
        }

        if (!next || !next.length || !this.active) {
            ignoreSearchDiv = (ignoreSearchDiv === undefined ? false : ignoreSearchDiv);
            
            var searchDiv = this.element.parent().prev(".js-gctmenu-search");
            if (searchDiv.length === 0) {
                searchDiv = this.element.parent().parent().prev().prev(); //vyhledani ze search
            }
                
            //console.log(searchDiv);
            if (searchDiv.length !== 0 && !ignoreSearchDiv){
                searchDiv.children(".js-gctmenu-srch-inp").focus();
                return;
            }
                
            else
                next = this.activeMenu.find(this.options.items)
                    .filter(":visible")
                    .not(".ui-state-disabled")[filter]();
        }
        //console.log("uimenu.next", next);
        this.focus(event, next);
    },
    collapse: function (event) {
        /// <summary>Pretezuje jqui menu - pokud je volano collapse na rootovem menu, vyhodi udalost 'rootCollapse'</summary>
        var newItem = this.active &&
            this.active.parent().closest(".ui-menu-item", this.element);
        
        if (newItem && newItem.length) {
            this._close();
            this.focus(event, newItem);
        }
        else
            this._trigger("rootCollapse", event);
    },
    _activate: function (event) {
        /// <summary>Pokud ma list item akci, spusti akci (pretezuje jq-ui menu _activate)</summary>
        if (GMenu.hasAction(this.active)) {
            this.active.trigger(this.options.runActionEventName);
            this.collapse(event);
        }
    },
    _open: function (submenu) {
        submenu.children().removeClass("gmenu-item-hidden");
        submenu.children("." + GMenu.menuItemShiftClassName).css("display", "none");
        this._super(submenu);
        
        var position = $.extend({ of: this.active }, this.options.position);
        var currHeight = submenu.height();
        var offset = submenu.offset();
        var submenuBottom = submenu.offset().top + currHeight;
        var docHeight = $(window).height();
        var ofTop = position.of.offset().top;
        var ofBottom = ofTop + position.of.height();
        var hideItemCount = 0;
        var maxHeight = 0;

        if (offset.top < ofTop) {
            //zobrazuje se nahore
            if (currHeight > ofBottom) {
                hideItemCount = Math.ceil((currHeight - ofBottom) / 20);// + 1;
            }
        }
        else {
            //zobrazuje se dole
            if (offset.top + currHeight > docHeight) {
                hideItemCount = Math.ceil((offset.top + currHeight - docHeight) / 20);// + 1;
            }
        }
        
        if (hideItemCount) {
            var $items = submenu.children().not("." + GMenu.menuItemShiftClassName);
            for (var i = $items.length - 1; i >= $items.length - hideItemCount; i--) {
                $items.eq(i).addClass("gmenu-item-hidden");
            }
            submenu.children("." + GMenu.menuItemShiftClassName).css("display", "");
            submenu.position(position);
        }
        this.submenuPos = position;
    },
    updatePosition: function (submenu) {
        if (submenu[0] === this.element[0])
            return;

        submenu.position(this.submenuPos);
    }
    //,
    //_filterMenuItems: function (character) {
    //    var escapedCharacter = character.replace(/[\-\[\]{}()*+?.,\\\^$|#\s]/g, "\\$&"),
    //		regex = new RegExp("^" + escapedCharacter, "i");

    //    console.log(regex);

    //    return this.activeMenu
    //		.find(this.options.items)

    //		// Only match on items, not dividers or other content (#10571)
    //		.filter(".ui-menu-item")
    //		.filter(function () {
    //		    return regex.test($.trim($(this).text()));
    //		});
    //}
});

//#endregion

