//#region q:\ginis\Development\NET\Gordic.Gui.WebControls\Scripts\gactions.gbutton.js 

/*
//  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        gactions.gbutton.js											</Name>
//    <Description> Widget pro tlacitko											</Description>
//    <Author>      bmartinek                                                   </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2015                            </Copyright>
//    <Created>     2015-11-16                                                  </Created>
//  </FileHeader>
*/

//#region popis
/*
    Widget gbutton
    --------------
    Vytvori ovl. prvek jquery ui button. Pokud je ve vstupnim parametru def. param. 'children', vytvori jej jako splitbutton s kontextovym menu.
    Podporuje pouze typ 'action' a 'static'.
    Pozn. Pokud nema nastavenou ikonu, nastavi se captionVisibility na always.

    Udalosti:
    ---------
    - visibilityChanged - nastane v pripade, ze se tlacitko skryje nebo zobrazi pomoci show(), hide() a _actionUpdated()

    Zakladni pouziti:
    -----------------
    $("#gbtn1").gbutton({
            params: {
                caption: "Dlouhy text",
                icon: "fa-bars",
                action: new GAction({
                    name: "gbtn1FooAction", run: function () {
                        alert("Likviduji sam sebe...");
                        $("#gbtn1").gbutton("destroy");
                    }
                }),
                children: [
                    { type: "static", caption: "foo1", icon: "wfl/dokument_novy" },
                    { type: "static", caption: "foo2", icon: "fa-bars" },
                    { type: "static", caption: "foo3"}
                ]
            },
            within: $(...),                                         //pokud ma v params nejake children, bude z nich buildit menu. Vyplnenim zacne menu brat tento element jako hranicni.
            cssModifiers: { button: "", wrapper: "", text: "" }     //CSS modifikatory (tridy): button - pro g-button, wrapper - pro wrapper (pouze pokud elementem widgetu neni button), text - pro zobr. text
        });

*/
//#endregion

(function ($) {
    "use strict";

    var defaultPosition = {
        of: "this-button",                                        //tahle konstanta se pak zabehu nahradi buttonem, ktery jej otevira
        my: "left top",
        at: "left bottom",
        within: window
    };

    var iconBuilder;

    $.widget("gordic.gbutton", {
        options: {
            params: null,
            actions: [],
            badge: null,
            cssModifiers: {                                       //NOTE: Nepatri na xwiki
                button: "", wrapper: "", text: "", icon: "",      //modifikatory samostatneho tlacitka
                tooltip: { tooltip: "", header: "", tip: "" }     //modifikatory tooltipu
            },
            insertId: true,                                       //Je-li true prida tlacitku id z parametru (NOTE: Neni toto uz obsolete - od doby, co se id dava do attr. data-param-id???)
            menuActivationIcon: true,                             //Ma byt zobrazena ikona pro rozevreni menu? (funkcnost otevreni menu zustava zachovana)
            menuPosition: $.extend({}, defaultPosition),          //Moznost zmenit pozici otevirani menu 
            menuCreateOnOpen: false,                              //Vytvori menu znovu na otevreni
            tabindex: 0,                                          //Moznost nastavit tabindex vsem souvisejicim tlacitkum
            tooltipMode: "default",                               //default|delegatedAttr|delegatedProp, default - vytvori widget tooltipu|delegated - tooltip je na nejakem nadrazenem ovl. prvku a pouze se cte z atributu
            tooltipAttr: "title",                                 //v rezimu tooltipMode = delegated odtud cte tooltip    
            detachInnerWidgetsOnDestroy: false,                   //true = pred zlikvidovanim widgetu odpoji children widgety
            disabled: false,                                      //ridi enable/disable tlacitka samotneho nehlede na stav akce
            iconBuilder: null,                                    //moznost pouzit vlastni iconBuilder
            menuOptions: null,                                    //gctmenu options k rozsireni
            customClass: ""                                       //customClass vlozena primo na button
        },
        _iconBuilder: iconBuilder,
        _isCollapsed: false,
        _$mainButton: null,
        _$menuActivatorButton: null,
        _$caption: $([]),
        _$ctMenu: null,         //jQuery
        _panelTypes: [],
        _create: function () {
            var rootParam = GMenu.completeParams(this.options.params, this.options.actions, true);
            //var rootParam = GMenu._completeParams(this.options, this.options.actions, true);

            this._iconBuilder = iconBuilder || (iconBuilder = new Gordic.Utils.ButtonIconBuilder({ imageIconSize: 22 }));

            if (this.options.iconBuilder)
                this._iconBuilder = this.options.iconBuilder;

            this._panelTypes = GMenu.getRemovePanelType(rootParam);

            var $btn;

            if (this.element.prop("tagName") === "BUTTON") {
                $btn = this.element.addClass("gbutton");
            }
            else {
                $btn = $("<button>").appendTo(this.element);
                this.element.addClass("gbutton")
                            .addClass(this.options.cssModifiers.wrapper);
            }
            
            $btn.attr("type", "button")	//zruseni submitu (dat do options moznost volby?)
                .addClass("js-gbutton g-button")
                .addClass(this.options.cssModifiers.button)
                .addClass((rootParam.primary ? "g-button--primary" : ""));

            this._createPrimaryIcon($btn, rootParam.action ? rootParam.action.checked() : null);
            this._createCaption($btn);

            

            if (rootParam.customClass !== undefined)
              $btn.addClass(rootParam.customClass);

            if (this.options.customClass !== undefined)
                $btn.addClass(this.options.customClass);

            if (rootParam.autofocus === true)
                $btn.attr("autofocus", "autofocus");

            this._$mainButton = $btn;

            if (this.options.insertId && this.options.params.id !== undefined)
                $btn.attr(gparam.idAttrName, this.options.params.id);

            this.element.prop(GMenu.buildParamPropertyName, rootParam);
            var isVisible = true;
            var $wg = this;

            //NOTE: Nastaveni focusu na tlacitko resi: 
            //      - Zavirani inline v pripade, ze neco preventne udalost. Napr. v menubaru je widget ui-sortable, ktery dela preven default na mousedown. 
            //        Potom se tlacitku nenastavi focus a inline zustavaji otevrene, coz pak muze zpusobovat problem s jejich collected. 
            //      - problem se vyskytoval i u nastaveni gridu v inlinedialogu, kdy dochazelo k samostatnemu zavirani gridu.
            $btn.on("click", function (ev) { if (!ev.isDefaultPrevented() && ev.which) $btn.focus(); }); //https://api.jquery.com/event.which/ - doporucuji pouzivat pro detekci kliku (1 = lmb)

            switch (rootParam.type) {
                case 'action':
                    rootParam.action.register($btn, "click", false, function (event, updatedParams, action) {
                            $wg._paramsUpdated(updatedParams);
                        },
                        true, //false zpusobuje bug pri otevreni na gtabu - pokud je akce disabled/visible, atd. tlacitko se zobrazi jako by bylo enabled
                        rootParam.actionContext); //Na poz. TSkaly z 2019-09-11: Nepropisoval se mu pozadovany context
                    isVisible = rootParam.action.visible();
                    if (rootParam.action.checked() !== null) $btn.addClass("g-button--checkable");
                    break;
                case 'static':
                    if (rootParam instanceof GObservableObject)
                        rootParam.registerUpdate(function (p) { $wg._paramsUpdated(p); });
                    break;
                default:
                    throw "gbutton._create(): Parameter 'type' with '" + rootParam.type + "' is not supported";
            }

            this._createTooltip();

            if (this._getCaptionVisible(rootParam) === GAction.captionVisibility.never)
                this.collapse();

            this._createBadge(this.options.badge || rootParam.badge, false);

            //Pridruzene tlacitko + kontextove menu (ma-li root nejake children)
            if (GMenu.hasItemChildren(rootParam)) {
                Gordic.Utils.Menu.resolveParams([this.options.params]);
                var $menuActivatorBtn = null;

                if (rootParam.action !== undefined) {
                    $menuActivatorBtn = $(
                        "<button type='button' class='js-gbutton-activator g-button g-button--activator' tabindex='-1' aria-label='jres:31150050'>" + //RC 31150050 : Nabídka akcí
                            this._iconBuilder.createIcon({ icon: "gi-arrow-down", customClass: "g-button__icon g-button__icon--activator " + this.options.cssModifiers.icon }) +
                        "</button>"
                    );

                    $menuActivatorBtn
                        .addClass(this.options.cssModifiers.button)
                        .addClass((rootParam.primary ? "g-button--primary" : ""))
                        .addClass(rootParam.customClass || "");

                    $btn.after($menuActivatorBtn);
                    $btn.on({
                        "focusin": function () {
                            $menuActivatorBtn.addClass("gbuttonSplActive");
                        },
                        "focusout": function () {
                            $menuActivatorBtn.removeClass("gbuttonSplActive");
                        }
                    });

                    $menuActivatorBtn.on({
                        "focusin": function () {
                            $btn.addClass("g-button--mb-activated");
                        },
                        "mouseenter": function () {
                            $btn.addClass("g-button--mb-activated");
                        },
                        "focusout": function () {
                            if (!$menuActivatorBtn.hasClass("g-button--activated"))
                                $btn.removeClass("g-button--mb-activated");
                        },
                        "mouseout": function () {
                            if (!$menuActivatorBtn.hasClass("g-button--activated"))
                                $btn.removeClass("g-button--mb-activated");
                        }
                    });

                    //Vytvoreni efektu splitbuttonu, pokud nebylo vystaveno na html elementu button
                    if (this.element[0] !== this._$mainButton[0])
                        this.element.addClass("g-button--splitbutton");
                }
                else {
                    if (typeof rootParam.menuActivationIcon !== "undefined" ? rootParam.menuActivationIcon : this.options.menuActivationIcon)  // TODO: TSKALA 26.12.2016 - primo do options to nebylo jak zadat, kdyz to je tlacitko na gbuttonpanelu :( Takze bud takto, nebo si to do options napln z params nejak sam :) 
                        $btn.append(this._iconBuilder.createIcon({ icon: "gi-arrow-down", customClass: "g-button__icon g-button__icon--activator " + this.options.cssModifiers.icon }));
                    $btn.addClass("js-gbutton-activator");
                    $menuActivatorBtn = $btn;
                }

                this._$menuActivatorButton = $menuActivatorBtn;

                this._$ctMenu = $("<div class='js-gbutton-ctmenu'></div>").uniqueId();
                $(document.body).append(this._$ctMenu);

                $menuActivatorBtn
                    .attr("aria-owns", this._$ctMenu.attr("id"))
                    .attr("aria-haspopup", "menu")
                    .attr("aria-expanded", "false");

                $menuActivatorBtn.on({
                    click: function (e) { $wg._openMenu(e); }
                });

                $menuActivatorBtn.add($btn).on({
                    keydown: function(e) {
                        if(e.keyCode === $.ui.keyCode.DOWN)
                            $wg._openMenu(e);
                    }
                });

                if (!isVisible) {
                    this._$menuActivatorButton.css("display", "none");
                }
            }

            if (this.options.tabindex !== 0)
                this._setTabindex(this.options.tabindex);

            this._updateAriaCaption();
        },
        _destroy: function () {
            this._destroyMenu(true);

            if (this._$mainButton.gtooltip("instance") !== undefined)
                this._$mainButton.gtooltip("destroy");

            if (this._$menuActivatorButton !== null && this._$menuActivatorButton[0] !== this.element[0])
                this._$menuActivatorButton.remove();

            this.element.prop(GMenu.buildParamPropertyName, null);
            if (this.element.prop(GAction.actionPropertyName) !== undefined) {
                this.element.prop(GAction.actionPropertyName).unregister(this.element);

                //NOTE: Nasledujici presunuto do GAction.unregister()
                //this.element.off(GAction.updateTriggerName);
                //this.element.off(GAction.controlUpdatedTriggerName);
            }

            if (this.element.is("[" + gparam.idAttrName + "]"))
                this.element.removeAttr(gparam.idAttrName);

            this.element.find(".js-gbutton-primary-icon").remove();
            this.element.find(".js-gtbn-collapsible").remove();
            var b = this.element.find(".js-gbutton");
            if ($.contains(this.element[0], b)) b.remove();  //NOTE: JQuery 3.6 odebira elementy nejak jinak :-/

            this.element.removeClass("js-gbutton g-button gbutton g-button--splitbutton g-button--checkable js-gbutton-activator")
                        .removeClass(this.options.cssModifiers.button)
                        .removeClass(this.options.cssModifiers.wrapper)
                        .attr("tabindex", null);
        },
        _setOption: function(key, value){
            this._super(key, value);
            if (key === "disabled") {
                //NOTE: Zatim neni rozhodnute
                //var act = this._$mainButton.prop(GAction.actionPropertyName);
                //if (act)
                //    act.enabled(!value);
                //else
                this.enabled(!value);
                this._$mainButton.prop("disabled", value);
                if (this._$menuActivatorButton)
                    this._$menuActivatorButton.prop("disabled", value);
            }

            if (key === "badge")
                this._createBadge(value, true);

            if (key === "tabindex")
                this._setTabindex(value);

            if (key === "ariaCaption") this._updateAriaCaption(value);
        },
        //_setOptions: function(options){
        //    this._super(options);
        //    if (this.options.params) {
        //        for (var key in this.options.params) {
        //            if (key === "params")
        //                continue;
        //            if (this.options[key] === undefined || this.options[key] === "")
        //                this.options[key] = this.options.params[key];
        //        }
        //    }
        //},
        updateParams: function (params) {
            /// <summary>Updatne vybrane parametry buttonu</summary>
            /// <param name="params" type="object"></param>
            this._paramsUpdated(params);
        },
        _createTooltip: function () {
            switch (this.options.tooltipMode) {
                case "default":
                    this._createTooltipDefault();
                    break;
                case "delegatedAttr":
                    this._createTooltipDelegatedAttr();
                    break;
                case "delegatedProp":
                    this._createTooltipDelegatedProp();
                    break;
                default:
                    console.warn("gbutton: Option 'tooltipMode' with value '" + this.options.tooltipMode + "' is not supported");
            }
        },
        _createTooltipDefault: function() {
            var that = this;
            var pars = this.options.params;
            var caption = pars.caption;
            var tooltip = pars.tooltip;
            if (this._$mainButton.gtooltip("instance") === undefined) {
                this._$mainButton.gtooltip({
                    caption: caption,
                    tooltip: tooltip,
                    position: {
                        my: "left bottom",
                        at: "left top",
                        of: this._$mainButton,
                        shift: { left: 0, top: 4 }
                    },
                    showCaption: function () {
                        return that.isCollapsed();
                    }
                });

                return;
            }

            this._$mainButton.gtooltip({
                caption: caption,
                tooltip: tooltip,
            });
        },
        _createTooltipDelegatedAttr: function () {
            this._$mainButton.attr(this.options.tooltipAttr, this.options.params.tooltip);
        },
        _createTooltipDelegatedProp: function () {
            this._$mainButton.attr(this.options.tooltipAttr, "gtooltipDelegatedProp");

            var prop = this._$mainButton.prop("gtooltip");
            if (!prop) {
                prop = {};
                this._$mainButton.prop("gtooltip", prop);
            }

            prop.caption = this.options.params.caption;
            prop.isCaptionVisible = this._isCollapsed;
            prop.tooltip = this.options.params.tooltip;
        },
        _getCaptionVisible: function (params) {
            var caption = params.caption;
            var captionVisible = params.captionVisible;
            var icon = params.icon;

            if (icon === GAction.emptyIcon || icon === "")
                return GAction.captionVisibility.always;
            else if (caption === GAction.defaultParams.caption || caption === "")
                return GAction.captionVisibility.never;
            else
                return captionVisible;
        },
        _paramsUpdated: function (params) {
            /// <summary>Upravi parametry buttonu</summary>
            /// <param name="params" type="menuParam"></param>
            var action = this.options.params.action;
            var optParams = this.options.params;
            var updateAriaCaption = false;

            if (params.type !== undefined && params.type !== this.options.params.type)
                throw new Error("gbutton._paramsUpdated(): change 'type' is not allowed.");

            if (params.action !== undefined)
                throw new Error("gbutton.updateParams(): change 'action' is not allowed.");

            if (action && params.children !== undefined && optParams.children === undefined)
                throw new Error("gbutton.updateParams(): append 'children' is not allowed.");

            //icon
            if (params.icon !== undefined) {
                optParams.icon = params.icon;
                this._createPrimaryIcon(this._$mainButton, action ? action.checked() : null);
            }

            //caption
            if (params.caption !== undefined) {
                optParams.caption = params.caption;
                this._createCaption(this._$mainButton);
                updateAriaCaption = true;
            }

            //captionVisible
            if (params.captionVisible !== undefined) {
                optParams.captionVisible = params.captionVisible;

                if (this._getCaptionVisible(optParams) === GAction.captionVisibility.never)
                    this.collapse();
                else
                    this.expand();
            }

            //ariaCaption
            if (params.ariaCaption !== undefined) {
                optParams.ariaCaption = params.ariaCaption;
                updateAriaCaption = true;
            }

            //tooltip
            if (params.tooltip !== undefined) {
                optParams.tooltip = params.tooltip;
            }

            //visible
            if (params.visible !== undefined) {
                optParams.visible = params.visible;
                if (optParams.visible)
                    this.show(true);
                else
                    this.hide();
            }

            //enabled
            if (params.enabled !== undefined) {
                optParams.enabled = params.enabled;
                this.enabled(optParams.enabled, "main");
            }

            //checked
            if (params.checked !== undefined)
                this._$mainButton
                    .toggleClass("g-button--checked", !!params.checked);
            
            //primary
            if (params.primary !== undefined) {
                optParams.primary = params.primary;
                this._$mainButton.toggleClass("g-button--primary", !!params.primary);
            }

            if (params.children !== undefined) { 
                optParams.children = params.children;
                this._destroyMenu(); //NOTE: Staci odstranit, menu se vytvari pri otevreni
            }

            this._createTooltip();
            this._visibilityChanged(params);
            if (updateAriaCaption) this._updateAriaCaption();
            this.element.trigger(GMenu.eventControlUpdated, [params]);

            //NOTE: Toto musi byt az po vyhozeni udalosti GMenu.eventControlUpdated. GButtonPanel totiz na ni reaguje
            //      a v momente, kdy se animace spusti dochazi k prepoctu sirek. Nastartovana animace schova caption i 
            //      ikonu a GButtonPanel pak prepocte sirku pouze na ikonu v animaci.
            if (params.pendingState !== undefined)
                this._updatePendingState(params.pendingState);
        },
        _updatePendingState: function (state) {
            //console.log("gbutton._updatePendingState()", state);
            if (state === null) {
                //Reset
                this._resetPendingAnimation();
                return;
            }

            if (state === 100) {
                //Success
                this._startPendingCompleteAnimation("fa-check", "g-state-success");
                return;
            }

            if (state < 0) {
                //Error
                this._startPendingCompleteAnimation("fa-times", "g-state-error");
                return;
            }

            //Pending
            this._pendingState = state;
            this._startPendingAnimation();
        },
        _resetPendingAnimation: function() {
            this._$mainButton
                .css({ position: "", overflow: "" })
                .find(".js-prgsbar")
                        .stop()
                .remove();
            this._pendingState = null;
        },
        _startPendingAnimation: function () {
            //console.log("gbutton._startPendingAnimation() state", this._pendingState);
            var state = this._pendingState;
            var $progress = this._$mainButton.css({ position: "relative", overflow: "hidden" })
                                    .find(".js-prgsbar");

            var that = this;
            if($progress.length === 0)
                $progress = $("<div class='js-prgsbar g-button-progress' style='z-index: -1'>")
                                .prependTo(this._$mainButton);

            $progress.animate({ width: (state === 0 ? "100%" : state + "%")}, { duration: 500 });

            if(state === 0)
                $progress.animate({ left: "+=100%" }, {
                    duration: 500,
                    complete: function () {
                        $(this).css({ width: "0", left: "0px" });
                        if(state === 0)
                            that._startPendingAnimation();
                    }
                });
            
        },
        _startPendingCompleteAnimation: function (icon, bgClass) {
            /// <summary>Zahaji ukoncujici animaci, at uz uspesnou ci neuspesnou</summary>
            /// <param name="icon" type="string">Nazev tridy fa-ikony</param>
            /// <param name="bgClass" type="string">Nazev tridy pozadi, reagujici na g-state-background</param>

            //Pokud existuje nejaka dobihajici animace nezahajuji dalsi
            if (this._$mainButton.hasClass("js-pending")) return;

            this._resetPendingAnimation();

            if (this._$mainButton.hasClass("gtooltip")) this._$mainButton.gtooltip("destroy");

            var prevDisabled = !!this._$mainButton.attr("disabled");
            var action = this.options.params.action;
            var $state = $.newDiv("js-state ui-front g-state-background " + bgClass)
                .append("<i class='js-complete fa " + icon + "'>")
                .css({
                    "width": this._$mainButton.outerWidth(),
                    "height": this._$mainButton.outerHeight(),
                    //"z-index": 99999,
                    "position": "absolute",
                    "top": 0,
                    "left": 0,
                    "display": "flex",
                    "justify-content": "center",
                    "align-items": "center"
                })
                .prependTo(this._$mainButton);

            this._$mainButton
                .attr("disabled", true)
                .addClass("js-pending");

            var that = this;
            this._finishPendingAnimation = function () {
                that._$mainButton.removeClass("js-pending")
                $state.remove();
                that._$mainButton.attr("disabled", action ? !action.enabled() : prevDisabled);
                that._createTooltip();
                that._finishPendingAnimation = null;
            };
            
            setTimeout(this._finishPendingAnimation, 1000);
        },
        _createPrimaryIcon: function ($btn, checkedValue) {
            if (this._finishPendingAnimation) this._finishPendingAnimation();

            var $primaryIcon = $btn.children(".js-gbutton-primary-icon");
            var pars = this.options.params;
            var $newIcon = this._iconBuilder.createIcon({
                icon: pars.icon,
                iconSize: pars.iconSize,
                wrapWithSub: true,
                customClass: "js-gbutton-primary-icon g-button__icon " + this.options.cssModifiers.icon,
                checkedValue: checkedValue
            });

            if ($primaryIcon.length === 0)
                $btn.prepend($newIcon);
            else
                $primaryIcon.replaceWith($newIcon);
        },
        _createCaption: function ($btn) {
            if (this._finishPendingAnimation) this._finishPendingAnimation();

            //var $cpt = this._$caption;
            if (this._$caption.length === 0)
                this._$caption = $btn.children(".js-gbtn-caption"); //NOTE: Tohle by nikdy nemelo nastat

            var caption = this.options.params.caption;
            caption = caption || "";
            if (this._$caption.length === 0) {
                this._$caption = $("<span>", {
                    "class": "js-gbtn-caption js-gtbn-collapsible g-button__text" + (this.options.cssModifiers.text === "" ? "" : " " + this.options.cssModifiers.text)
                }).appendTo($btn);
            }
            
            this._$caption.html(caption);
            //    "<span class='js-gtbn-collapsible g-button__text" + (this.options.cssModifiers.text === "" ? "" : " " + this.options.cssModifiers.text) + "'>" + rootParam.caption + "</span>"
        },
        _createBadge: function (badge, cleanPrev) {
            /// <summary>Vytvori badge (pozn. na u badge na buttonu nebude fungovat tooltip - html button nepropousti udalosti na svuj obsah)</summary>
            /// <param name="badge" type="Object">Definice badge</param>
            /// <param name="cleanPrev">Ma se pokusit odstranit predchozi?</param>
            if (this._finishPendingAnimation) this._finishPendingAnimation();

            if(cleanPrev)
                this._$mainButton.find(".js-gbtn-badge")
                    .gbadge("destroy")
                    .remove();

            if (!badge)
                return;

            $("<div>", { "class": "js-gbtn-badge js-gtbn-collapsible" })
                .appendTo(this._$mainButton)
                .gbadge({ params: badge, tooltipDisabled: true });
        },
        _setTabindex: function (tabindex) {
            this._$mainButton.attr("tabindex", tabindex);
        },
        _updateAriaCaption: function (caption) {
            var p = this.options.params;

            if (typeof caption === "undefined") {
                if (!p) return;
                caption = p.ariaCaption || p.caption;
            }
            else if (p) p.ariaCaption = caption;

            if (!caption) this._$mainButton.removeAttr("aria-label");
            else this._$mainButton.attr("aria-label", caption);  //Musi byt setnuty, protoze caption muze byt skryte
        },
        collapse: function () {
            /// <summary>Skryje popisek (caption)</summary>
            if (this._isCollapsed)
                return;

            var captionVisible = this._getCaptionVisible(this.options.params);

            if (captionVisible === "exclusive")
                this.element.find(".js-gbutton-primary-icon").css("display", "");

            this.element.find(".js-gtbn-collapsible").css("display", "none");

            this._isCollapsed = true;

            if (this.options.tooltipMode === "delegatedProp")
                this._createTooltipDelegatedProp();
        },
        expand: function () {
            /// <summary>Zobrazi popisek (caption)</summary>
            if (!this._isCollapsed)
                return;

            var captionVisible = this._getCaptionVisible(this.options.params);

            if (captionVisible === "exclusive")
                this.element.find(".js-gbutton-primary-icon").css("display", "none");

            this.element.find(".js-gtbn-collapsible").css("display", "");
            this._isCollapsed = false;

            if (this.options.tooltipMode === "delegatedProp")
                this._createTooltipDelegatedProp();
        },
        buildParams: function () {
            /// <summary>(Obsolete)Vrati instanci parametru, ze kterych bylo tlacitko vytvoreno. Misto teto metody pouzijte getParams()</summary>
            return this.getParams();
        },
        getCaptionVisibility: function () {
            return this._getCaptionVisible(this.options.params);
        },
        getCaptionWidth: function () {
            return this._$caption.outerWidth(true) || 0;
        },
        getParams: function () {
            /// <summary>Vrati parametry, ze kterych bylo tlacitko vytvorene</summary>
            return this.element.prop(GMenu.buildParamPropertyName);
        },
        openMenu: function () {
            /// <summary>Otevre menu, pokud ho button ma.</summary>
            if (this._$menuActivatorButton === null || this._$menuActivatorButton.hasClass("g-button--disabled"))
                return;

            this._$menuActivatorButton.trigger($.Event("click"));
        },
        focus: function () {
            /// <summary>Nastavi focus na tlacitko</summary>
            this._$mainButton.focus();
        },
        enabled: function (isEnabled, type) {
            /// <summary>Povoli nebo zakaze tlacitko. Zavolanim bez parametru vrati aktualni stav.</summary>
            /// <param name='isEnabled' type='boolean'>True = povoli tlacitko, false jej zakaze</param>
            /// <param name='type' type='string'>
            ///     Param. ma smysl pouze u split buttonu. Lze jim rozlisit, ktere tlacitko ma byt povoleno/zakazano. 
            ///     Pro hlavni tlacitko musi byt uvedena hodnota 'main', pro tlac. k otevreni ctmenu 'menu'.
            /// </param>

            //Nebyl-li specifikovan arg. vraci automaticky ena/dis hlavniho tlacitka
            if (arguments.length === 0)
                return !this._$mainButton.hasClass("g-button--disabled");
                //return !this._$mainButton.prop("disabled");

            if (typeof (isEnabled) === "string") {
                type = isEnabled;
                isEnabled = null;
            }

            isEnabled = (typeof (isEnabled) === "boolean" ? isEnabled : null);

            //Bude se cist stav
            if (isEnabled === null) {
                switch (type) {
                    case "menu":
                        if (this._$menuActivatorButton === null) {
                            var errMsg = "gbutton.enabled() has no menu.";
                            console.warn(errMsg, this);
                            throw errMsg;
                        }
                        return !this._$menuActivatorButton.hasClass("g-button--disabled");
                        //return !this._$menuActivatorButton.prop("disabled");
                    case "main":
                    default:
                        return !this._$mainButton.hasClass("g-button--disabled");
                        //return !this._$mainButton.prop("disabled");
                }
            }

            type = (type === undefined ? "all" : type);
            var $q;

            switch (type) {
                case "main":
                    $q = this._$mainButton;
                    break;
                case "menu":
                    $q = this._$menuActivatorButton;
                    break;
                case "all":
                    $q = this._$mainButton.add(this._$menuActivatorButton);
                    break;
                default:
                    var errTypeMsg = "gbutton.enabled() value of 'type' is not supported";
                    console.warn(errTypeMsg, type, this);
                    throw errTypeMsg;
            }

            if (isEnabled) {
                $q.removeClass("g-button--disabled")
                    .attr("tabIndex", this.options.tabindex)
                    .prop("disabled", false); //NOTE: Resi bug https://phabricator.gordic.cz/T948
                                              //      Pokud se akce nastavi disabled behem animace, zustava na tlacitku atribut 'disabled'
                $q.removeAttr("aria-disabled");
                this.element.removeClass("js-gbutton-disabled");
            }
            else {
                $q.addClass("g-button--disabled")
                    .attr("tabIndex", "-1")
                    .attr("aria-disabled", "true");

                    //.prop("disabled", true); //NOTE: Bug na IE a na Chrome - pokud je na gtabu zakazane tlacitko, kliknutim na nej se zavre tab
                this.element.addClass("js-gbutton-disabled");
            }

            return this;
        },
        isCollapsed: function () {
            /// <summary>Vraci, zda je tlacitko v collapsed modu (popisek - caption je skryty)</summary>
            /// <returns type='boolean'>True, je-li skryty popisek (caption)</returns>
            return this._isCollapsed;
        },
        hide: function (skipEvent) {
            /// <summary>Skryje ovl. prvek</summary>
            /// <param name='skipEvent' type='Boolean'>Je-li true neni vyhozena udalost 'visibilityChanged'.</param>
            this._$mainButton.css("display", "none"); // hide()/show(); // TSKALA: 11.8.2016 optimalizace (show docela zere, vytvoreni par buttonu na demo strance zere 400ms/5000ms a v jinych vetvich je to taky) 
            if (this._$menuActivatorButton)
                this._$menuActivatorButton.css("display", "none");

            if (!skipEvent)
                this._visibilityChanged({ visible: false });
        },
        show: function (skipEvent) {
            /// <summary>Zobrazi ovl. prvek</summary>
            /// <param name='skipEvent' type='Boolean'>Je-li true neni vyhozena udalost 'visibilityChanged'.</param>
            this._$mainButton.css("display", "");
            if (this._$menuActivatorButton)
                this._$menuActivatorButton.css("display", "");

            if(!skipEvent)
                this._visibilityChanged({ visible: true });
        },
        click: function () {
            /// <summary>Provede click na hlavni tlacitko + nastavi mu focus</summary>
            if (!this._$mainButton.is(":visible"))
                return;
            this._$mainButton.focus().click();
        },
        _visibilityChanged: function (params) {
            this._trigger("visibilityChanged", null, params);
        },
        visible: function (isVisible) {
            /// <signature>
            /// <summary>Vraci hodnotu, zda je tlacitko viditelne</summary>
            /// <returns type='boolean'>True, je-li viditelne</returns>
            /// </signature>
            /// <signature>
            /// <summary>
            /// Nastavi viditelnost tlacitka. Pokud ma tlacitko akci, provede to pres ni (tzn. provede se to na vsech navazanych ovl. prvcich)
            /// </summary>
            /// <param name='isVisible' type='boolean'>True - ma-li byt tlacitko viditelne</param>
            /// </signature>
            if (isVisible === undefined)
                return this._$mainButton.is(":visible");

            if (this.options.params.action) {
                this.options.params.action.visible(isVisible); //NOTE: Akce sama vola show() a hide() pres actionRefresh
                return;
            }

            if (isVisible)
                this.show();
            else
                this.hide();
        },
        _hasPanel: function () {
            return (this._panelTypes.length !== 0);
        },
        _createPanel: function () {
            if (!this._hasPanel() || this._$ctMenu.hasClass("js-gbtn-ctmenu-pnl"))
                return;

            //NOTE: Aktualne se z parametru vyberou parametry typu 'panel' (tzn. odstrani se z params.children). Z params.children se pak vybuildi menu
            //a panely se vytvori kolem nej. Pokud params.children zustanou prazdne, nevytvori se div obalujici menu (a panely). V pripade takove potreby
            //bude treba zrefaktorit vytvareni menubuttonu.
            if (this._$ctMenu === null)
                throw "gbutton._createPanel(): Cannot create panels without menu definition";

            this._$ctMenu.css({
                float: "left"
            }).addClass("js-gbtn-ctmenu-pnl")
              .parent()
              .addClass("g-menu-pnl-wrp");

            var $left = $("<div class='js-gbtn-panel-left " + GMenu.menuItemClickCloseIgnoredClassName + "' style='float: left;'>"),
                $top = $("<div class='js-gbtn-panel-top " + GMenu.menuItemClickCloseIgnoredClassName + "'>"),
                $right = $("<div class='js-gbtn-panel-right " + GMenu.menuItemClickCloseIgnoredClassName + "' style='float: right;'>"),
                $bottom = $("<div class='js-gbtn-panel-bottom " + GMenu.menuItemClickCloseIgnoredClassName + "'>");

            this._$panels = $([]).add($left).add($top).add($right).add($bottom);

            this._$ctMenu.before($top)
                .before($left)
                .after($bottom)
                .after($right);

            $bottom.before("<div class='ui-helper-clearfix'>");

            for (var i = 0; i < this._panelTypes.length; i++) {
                var jsClass = "js-gbtn-panel-" + this._panelTypes[i].position;
                var $pnl = this._$ctMenu.parent().children("." + jsClass);
                
                if (this._panelTypes[i].customClass)
                    $pnl.addClass(this._panelTypes[i].customClass);

                //NOTE: Ponechat pro pripadnou kontrolu preklepu v typu panelu
                switch (this._panelTypes[i].position) {
                    case GMenu.panelPositionTypes.left:
                    case GMenu.panelPositionTypes.top:
                    case GMenu.panelPositionTypes.right:
                    case GMenu.panelPositionTypes.bottom:
                        break;
                    default:
                        console.warn("gbutton._createPanel(): Unsupported panel position", this._panelTypes[i]);
                        throw "gbutton._createPanel(): Unsupported panel position";
                }

                if (!this._panelTypes[i].children)
                    continue;

                for (var j = 0; j < this._panelTypes[i].children.length; j++) {
                    if (this._panelTypes[i].children[j].type === "separator") {
                        $pnl.append("<div class='g-menu-pnl-wrp__separator'>");
                        continue;
                    }

                    $pnl.append(this._panelTypes[i].children[j].html);
                }
            }
        },
        _openMenu: function(e) {
            /// <summary>Otevre menu</summary>
            /// <param name="e" type="$.Event"></param>
            e.preventDefault();
            if ($("body").hasClass("gwebapp")) {
                var __this = this;
                var $btn = /*this.options.params.action ? this._$mainButton :*/ this._$menuActivatorButton;
                if (!this._$ctMenu.hasClass("ginlinedialog"))
                    this._$ctMenu.ginlinedialog({
                        width: 275,
                        height: 250,
                        related: $btn,
                        createClosed: true,
                        autoClose: true,
                        //resizable: true,
                        closeButton: null,
                        customClass: "ginlinedialog--light-shadow",
                        open: function (ev) {
                            __this._$menuActivatorButton.addClass("g-button--activated");
                            $btn.addClass("g-button--mb-activated")
                                .attr("aria-expanded", "true");
                        },
                        close: function (ev, o) {
                            __this._$menuActivatorButton.removeClass("g-button--activated");
                            $btn.removeClass("g-button--mb-activated")
                                .attr("aria-expanded", "false");

                            //NOTE (BM 2022-11-09): Pokud zlikviduji actionmenu na jeho zavreni, pak dojde k preruseni
                            //                      gdomcontext a pak nemusi spravne fungovat napr. kontextova
                            //                      napoveda (F1), protoze gdomcontext() nevrati cestu az k body.
                            //                      Chvilku to ponechat zakomentovane a casem smazat, pokud nebude nekde zlobit.
                            //if (__this.options.menuCreateOnOpen && __this._$ctMenu.hasClass("gactionmenu"))
                            //    __this._$ctMenu.gactionmenu("destroy");

                            //NOTE: Uzivatel stisknul escape na menu, pak by se mel focus vratit asi zpet na tlacitko
                            if (o && o.type === "cancel" && o.originalEvent && o.originalEvent.keyCode === $.ui.keyCode.ESCAPE) $btn.focus();
                        }
                    });
                else if (this._$ctMenu.is(":visible")) {
                    this._$ctMenu.ginlinedialog("close");
                    return;
                }
                
                if (this.options.menuCreateOnOpen && this._$ctMenu.hasClass("gactionmenu")) { 
                    this._$ctMenu.gactionmenu("destroy");
                }

                if (!this._$ctMenu.hasClass("gactionmenu")) {
                    
                    var params = GMenu.getItemChildren(this.options.params);

                    this._$ctMenu.gactionmenu({
                        params: params,
                        actions: this.options.actions,
                        detachWidgetsOnDestroy: true
                    });

                    this._$ctMenu.off("gactionmenuitemop");
                    this._$ctMenu.on("gactionmenuitemop", function (ev, opType, params) {
                        if (opType === "actionrun") {
                            //NOTE: Nastavovat focus zpet na tlacitko ma smysl jen v pripade, ze si
                            //      programator nenastavil focus na neco jineho nekde v contentu.
                            var shouldFocusButton = document.activeElement === __this._$ctMenu[0]
                                                    || $.contains(__this._$ctMenu[0], document.activeElement);
                            __this._$ctMenu.ginlinedialog("close");
                            if(shouldFocusButton) __this._$mainButton.focus();
                        }
                        else if (opType === "framechanged") {
                            __this._$ctMenu.ginlinedialog("option", "autoClose", false);
                            __this._$ctMenu
                                .height(__this._$ctMenu.gactionmenu("getCurrentHeight"))
                                .ginlinedialog("updateSize");
                            __this._$ctMenu.ginlinedialog("option", "autoClose", true);
                        }
                    });
                }

                this._$ctMenu.ginlinedialog("toggle")
                    .gactionmenu("updateWidth")
                    .gactionmenu("move", "root")
                    .gactionmenu("resetActive")
                    .height(this._$ctMenu.gactionmenu("getCurrentHeight"))
                    .css("min-width", this._$mainButton.outerWidth())
                    .ginlinedialog("open")
                    .ginlinedialog("moveToTop");

                
                this._$ctMenu.focus();

                if(e && e.originalEvent && e.originalEvent instanceof KeyboardEvent)
                    this._$ctMenu.gactionmenu("move", "down"); //NOTE: otevreni pomoci klavesnice by melo oznacit prvni polozku, u kliku to ale nechceme (OHvezda)

                return;
            }



            if (this.options.menuCreateOnOpen && this._$ctMenu.hasClass("gctmenu"))
                this._$ctMenu.gctmenu("destroy");

            if (!this._$ctMenu.hasClass("gctmenu")) {
                this._createMenu();
                this._createPanel();
            }

            if (this._$ctMenu.gctmenu("isVisible")) {
                this._$ctMenu.gctmenu("hideMenu");
            }
            else if (!this._$menuActivatorButton.hasClass("g-button--disabled")) {
                this._$ctMenu.css("min-width", this._$mainButton.outerWidth()); //Uprava sirky, pokud by melo byt menu uzsi nez je tlacitko

                var menuPosition = $.extend({}, this.options.menuPosition);

                if (menuPosition.of === "this-button")
                    menuPosition.of = this._$mainButton;
                
                this._$ctMenu.gctmenu("show", menuPosition).css("min-width", this.element.width() + "px");

            }
            e.preventDefault();
        },
        _createMenu: function () {
            //TODO: Prepnutim na nove menu bude tato metoda ke smazani
            var $wg = this;
            var $btn = this.options.params.action ? this._$mainButton : this._$menuActivatorButton;

            var childrenArr = GMenu.getItemChildren(this.options.params);

            var menuOptions = $.extend({
                params: childrenArr,
                actions: this.options.actions,
                settings: { within: this.options.within },
                menuOpen: function () {
                    $wg._$menuActivatorButton.addClass("g-button--activated");
                    $btn.addClass("g-button--mb-activated");
                    $(this).parent(".g-menu-pnl-wrp").resize();
                },
                menuHidden: function (e, d) {
                    $wg._$menuActivatorButton.removeClass("g-button--activated g-button--mb-activated");

                    if (!($wg._$menuActivatorButton.is(":hover") || $wg._$menuActivatorButton.is(":focus")))
                        $btn.removeClass("g-button--mb-activated");

                    if (d && d.returnFocus)
                        $btn.focus();
                },
                activator: this._$menuActivatorButton,
                parent: this.element,
                detachInnerWidgetsOnDestroy: this.options.detachInnerWidgetsOnDestroy
            }, this.options.menuOptions);

            this._$ctMenu.gctmenu(menuOptions);
        },
        _destroyMenu: function (remove) {
            if (this._$panels) {
                this._$panels.remove();
                this._$panels = null;
            }
            if (this._$ctMenu !== null && this._$ctMenu.hasClass("gctmenu")) {
                this._$ctMenu.gctmenu("destroy");
            }

            if (this._$ctMenu !== null && this._$ctMenu.hasClass("gactionmenu")) {
                this._$ctMenu.gactionmenu("destroy");
            }

            if (remove && this._$ctMenu) this._$ctMenu.remove();
        }
    });
})(jQuery);

//#endregion

//#region q:\ginis\Development\NET\Gordic.Gui.WebControls\Scripts\gactions.gbadge.js 

/*  <FileHeader xmlns="http://www.gordic.cz/shared/file-header/v_1.0.0.0">
//    <Name>        Gordic.Gui.WebControls.gactions.gbadge.js                   </Name>
//    <Description> Widget gbadge                                               </Description>
//    <Author>      bmartinek                                                   </Author>
//    <Copyright>   © GORDIC spol. s r. o. 1993-2016                            </Copyright>
//    <Created>     2016-02-05                                                  </Created>
//  </FileHeader>
*/

var gbadge = (function ($) {
    "use strict";

    var defaultOptions = {
        id: "",
        value: "",
        tooltip: "",
        tooltipPosition: {
            my: "left top",
            at: "right top",
            of: "this.element",
            shift: { left: 4, top: 0 }
        },
        customClass: "",
        state: "info",
        params: null,    //objekt defaultOptions bez params - pro vyhnuti se deep copy pri vytvareni widgetu
        tooltipDisabled: false,
        allowHtmlValue: false   //je-li false, vklada value jako text, je-li true, vlozi jej jako HTML
    };

    $.widget("gordic.gbadge", {
        options: defaultOptions,
        _create: function () {
            this.element.addClass("gbadge g-badge g-state-background");

            if (this.options.params)
                this._mergeParams(this.options.params, this.options);

            if (this.options.params && this.options.params instanceof GObservableObject) {
                var that = this;
                this._update = function () { that._setOptions(this); };
                this.options.params.registerUpdate(this._update);
            }

            this._refresh();
        },
        _destroy: function () {
            this.element.empty();

            if (this.element.gtooltip("instance") !== undefined)
                this.element.gtooltip("destroy");

            if (this.element.is("[" + gparam.idAttrName + "]"))
                this.element.removeAttr(gparam.idAttrName);

            if (this.options.customClass !== "")
                this.element.removeClass(this.options.customClass);

            if (this.options.state)
                this.element.removeClass("g-state-" + this.options.state);
            
            if (this.options.params && this.options.params instanceof GObservableObject)
                this.options.params.unregisterUpdate(this._update);

            this.element.removeClass("gbadge g-badge g-state-background");
        },
        _setOptions: function (options) {
            this._super(options);
            if (!this._isRefreshing) {
                this._refresh();
                this.element.trigger(GMenu.eventControlUpdated);
            }
        },
        _setOption: function (key, value) {
            if (key === "customClass")
                this.element.removeClass(this.options.customClass);
            if (key === "state")
                this.element.removeClass("g-state-" + this.options.state);
            this._super(key, value);
        },
        _refresh: function () {
            if (this.options.value) this.element.css("display", "");
            else this.element.css("display", "none");

            if (this.options.allowHtmlValue) this.element.html(this.options.value);
            else this.element.text(this.options.value);

            if (this.options.id !== "")
                this.element.attr(gparam.idAttrName, this.options.id);

            if (this.options.customClass !== "")
                this.element.addClass(this.options.customClass);

            if (this.options.state)
                this.element.addClass("g-state-" + this.options.state);

            if (this.element.gtooltip("instance") === undefined) {
                if (this.options.tooltipPosition.of === "this.element")
                    this.options.tooltipPosition.of = this.element;
                this.element.gtooltip({
                    tooltip: this.options.tooltip,
                    show: { delay: 500 },
                    position: this.options.tooltipPosition,
                    showCaption: function () { return false; }
                });
            }
            else
                this.element.gtooltip("option", "tooltip", this.options.tooltip);

            this._isRefreshing = true;
            if (this.options.tooltipDisabled)
                this.disable(); //NOTE: Disable a enable vola uvnitr this._setOptions({disabled: true/false}), takze pokud se to vola bez this._isRefreshing skonci v nekonecnem cyklu.
            else
                this.enable();
            this._isRefreshing = false;
        },
        _isRefreshing: false,
        _lastUpdateTime: 0,
        _mergeParams: function (from, to) {
            /// <summary>Zkopiruje hodnoty z jednoho objektu do druheho, vynecha property 'params'</summary>
            for (var key in from) {
                if (key === "params")
                    continue;
                to[key] = from[key];
            }
        },
        update: function(badgeOpts) {
            /// <summary>Provede update podle badgeOpts a updatne vsechny souvisejici</summary>
            /// <param name="badgeOpts" type="Object"></param>
            //console.log("gbadge.update()", badgeOpts, this.element);

            //NOTE: Optimalizace pro pripad, ze by nekdo updatoval badge nad celou kolekci
            var currTime = Math.floor(Date.now() / 1000);
            if (this._lastUpdateTime == currTime)
                return;

            this._lastUpdateTime = currTime;

            if (badgeOpts === this.options.params)
                this._mergeParams(badgeOpts, this.options);
            else if ($.isPlainObject(badgeOpts) && !this.options.params) {
                this._mergeParams(badgeOpts, this.options);
            }
            else if ($.isPlainObject(badgeOpts) && this.options.params) {
                this._mergeParams(badgeOpts, this.options.params);
                this._mergeParams(this.options.params, this.options);
            }
            else
                throw new Error("gbadge.update(): argument is not supported");

            this.refresh();

            //update vsech souvisejicich podle id
            if (this.options.id && this.options.params) {
                $(".gbadge[data-param-id=" + this.options.id + "]")
                    .not(this.element)
                    .gbadge("refresh");
            }
        },
        refresh: function () {
            /// <summary>Provede self-update podle vlastnich options</summary>
            //console.log("gbadge.refresh()", this.element);
            this._refresh();
        }
    });

    //TODO: Cokoliv bude jen k gbadge a melo by byt viditelne zvenku, tak pridavat sem
    return {
        defaultOptions: defaultOptions
    };
})(jQuery);

