                const existing = this._flatpickrInstance.config[key];
                if (existing && existing.length > 0) {
                    var arr = existing.filter(it => it.toString() != value.toString());
                    arr.push(value);
                    value = arr;
                }

                if (value instanceof Function) value = [value];
                /* 
                //merge arrays
                if (this.options[key] == null) this.options[key] = [];
                value = value.concat(this.options[key].filter(function (item) {
                    return value.indexOf(item) < 0;
                }));
                
                */
