    document.addEventListener('scroll', function (e) {  // prepocitani velikosti dialogu pri zmene velikosti okna
        if ($(e.target).is(".suggestion-list,input[type=text],textarea") || $(e.target).closest(".gfield").length) return;   // scrolly v naseptavaci + ignorovat interni scrolly ve fieldu (IE haze scroll i v inputu pri rolovani dlouheho textu)
        $(e.target).find(".gautocomplete").gautocomplete("close");
    }, true);
