var GExtended = {}; 
GExtended.GDiv = {
  setWidth: function(value) { this.style.width = value; },
  setHeight: function(value) { this.style.height = value;},
  setTop: function(value) { this.style.top = value; }, 
  setBottom: function(value) { this.style.bottom = value; }, 
  setLeft: function(value) { this.style.left = value; }, 
  setRight: function(value) { this.style.right = value; }
}

  
/* ======================================================= */
/* GPanel */
/* ======================================================= */

$.widget("gordic.gtab", {
    options: {
        id: null, 
        title: "",
        loadingMessage: "jres:25030462", //RC 25030462 : (načítá se...)
        opened: false,
        locked: false,
        visible: true,
        autoload: false,
        icon: "fa-chevron-right",
        iconOpened: "fa-chevron-down",
        iconLoading: "fa-spinner fa-spin",
        headerClass: "",
        animationTimer: 200,
        customMenuID: null,
        menuBar: null,
        allowFullscreen: false,
        badge: null
    },
    _create: function () {
        var _this = this;

        this._header = null;
        this._badge = null;
        this._headerBar = null;
        this._lastHeaderClass = "";
        this._lastCustomMenuID = null;
        this._loaded = false;
        this._newH = $();
        this._forceShowListener = $.noop;

        var tBar = this.element.prev().filter("h3");  // tohle bych nejradeji zrusil (pak by byla jistota, ze remove vyhodi co ma) 
        if (tBar.length == 0) tBar = this._newH = $("<h3>").insertBefore(this.element);
        else this.options.title = tBar.html();
        tBar.addClass("g-tab-header-text").wrap("<div>").prepend("<i class='g-tab-header-icon'>");

        this._header = tBar.parent().uniqueId()
            .addClass("g-tab-header ui-widget-header smartnav-skip" + (this.element.hasClass("concealed") ? " concealed" :"")) //pokud je tab vytvářen na concealed divu, měla by i hlavička být concealed
            .click(function (ev) {
                if (ev.isDefaultPrevented() || $(ev.target).closest(".gfield").length) return;
                if (_this.options.locked === true) return false;
                _this.options.opened = !_this.options.opened;
                _this.refresh(null, ev);
            });
        this._badge = $.newDiv().appendTo(this._header).wrap("<div class='g-tab-header-badge'>");
        this._headerBar = $.newDiv("g-tab-header-barcontent").appendTo(this._header).wrap("<div class='g-tab-header-bar'>");

        this.element
            .addClass("gtab g-tab-content")
            .on({
                "contentinit.gtab": function (ev) { if (ev.target === _this.element[0]) _this.refresh(true); },
                "contentworking.gtab": function (e, working, status, content) {
                    if (e.isDefaultPrevented()) return;

                    _this._workingHelper(working !== false);
                    if (working) {
                        if (_this.options.loadingMessage && $.isPlainObject(status) && status.text) _this.options.loadingMessage = status.text; // pokud nejaky text zadan byl (neni explicitne vypnut), zobrazi se v titulku zalozky
                        _this.refresh();
                    } else {
                        _this._loaded = content.loaded;
                        if (_this._loaded)
                            _this.loadComplete();
                        else
                            _this.loadCanceled();
                    }

                    e.preventDefault();
                },
                "contentnewops.gtab": function (e, ops, content) {
                    if (e.target != this) return;
                    if (_this.options.customMenuID == null && ops.menuBar)
                        if (ops.menuBar.length > 0)
                            _this.setMenuBar(ops.menuBar, content.userSettings.sub("menuBar")); // mel by byt stejny jako this.userSettings, ale content muze mit pretizene userSettings a menuBar z newOps patri jemu
                        else
                            _this.setMenuBar(null, null);

                    if (typeof ops.title != "undefined") {
                        _this.options.title = ops.title;
                        _this.refresh();
                    }
                },
                "contentclosed.gtab": function (e, returnValue) {
                    if (e.target != this) return;

                    _this.unload(); // zavreni panelu pri content.close(), nastaveni priznaku loaded=false => pri otevreni se znovu provede load 
                },
                "gstatechanged.gtab": function (e, changes) {
                    if (e.target !== this) return;
                    if (typeof changes.title !== "undefined") {
                        e.preventDefault();    
                        _this.options.title = changes.title;
                        _this.refresh();
                    }
                    //NOTE (BM): Pro menubar, commandbar neni treba resit (o ty se stara contentwrapper)
                }
            });

        this._forceShowListener = function (e) {
            if (!e.defaultPrevented) {
                //NOTE: U gtabu je asynchronni prepareContent a navic rozbaleni je delano s pomoci animace.
                //      Nastavim tedy focus na header a jakmile je rozbaleni hotovo, zeptam se, jestli
                //      aktivnim elementem je porad header. Pokud ano, muzu zkusit focusnout puvodne pozadovany
                //      element.
                if (!_this.options.opened) {
                    _this.element.one("gtabopencomplete", function () {
                        if (document.activeElement === _this._header[0]) $(e.target).forceFocus(e.detail.context);
                    });
                    _this.open();
                    _this._header.focus();
                }
            }
        };

        this.element[0].addEventListener("forceshow", this._forceShowListener, { capture: true });

        // DEMO KEY MENU
        this.element.on("keydown.gtab", function (e) {
            if (e.isDefaultPrevented()) return;
            if (e.altKey && e.keyCode == 81) { // ALT+Q
                var tb = _this._headerBar.filter(".gtoolbar");
                if (tb.length > 0) {
                    tb[0]._focused = $(':focus');
                    tb.gtoolbar("focusMenuButton");
                    e.preventDefault();

                    tb.off("keydown.toolbar").on("keydown.toolbar", function (e) {
                        if (e.isDefaultPrevented()) return;
                        if (this._focused && ((e.altKey && e.keyCode == 81) || e.keyCode == 27)) { // ALT+Q
                            //          window.alert(e.altKey + " " + e.keyCode);
                            this._focused.focus();
                            delete this._focused;
                            e.preventDefault();
                        }
                    });
                }
            }
        });

        this.element.on('fielderror.gtab ggriderror.gtab', function (ev, ctx) {
            // dočasná detekce errorů na gridu a formech - nutno nahradit univerzálním errorproviderem
            var errors = _this.element.gform('getErrors');
            errors = errors || [];
            errors.push.apply(errors, _this.element.find('div.ggrid div.status-errors:not(:empty)').addBack('div.ggrid div.status-errors:not(:empty)'));

            if (_this._header) {
                var headerText = _this._header.find('.g-tab-header-text');
                var existing = headerText.find('.g-tab-header-error-icon');

                if (existing.length === 0 && errors.length > 0) {
                    var errorTypes = errors.map(function (it) { return it && it.errorType; });
                    var Colors = Gordic.Utils.Colors;
                    var fn = errorTypes.indexOf("error") >= 0 ? Colors.textErrorFn : errorTypes.indexOf("warning") >= 0 ? Colors.textWarningFn : errorTypes.indexOf("info") >= 0 ? Colors.textInfoFn : Colors.textErrorFn;
                    var icon = fn('fa-exclamation-triangle');
                    $('<i class="g-tab-header-error-icon fa fa-fw ' + icon +'">').appendTo(headerText);
                } else if (existing.length > 0 && errors.length <= 0) {
                    existing.remove();
                } else {
                    return;
                }
            }
        });

        //#region Rozbaleni/sbaleni klavesnici

        this._header.gshortcut({
            id: "ariasupport_expand",
            key: ["arrowdown", "space", "enter"],
            group: Gordic.Shortcuts.Groups.App,
            //description: "Opens tab",
            visible: false,
            canExecute: function (ev) { return !ev.isDefaultPrevented() && !_this.options.disabled && !_this.options.locked && document.activeElement === _this._header[0]; },
            run: function (ev, ctx) {
                if (_this.options.opened) { _this.close(); }
                else {
                    _this.open();
                    var tb = _this._headerBar.filter(".gtoolbar");
                    if (tb.length) tb.gtoolbar("focusMenuButton");
                }
            }
        })
        .gshortcut({
            id: "ariasupport_collapse",
            key: "escape",
            group: Gordic.Shortcuts.Groups.App,
            //description: "Closes tab",
            visible: false,
            canExecute: function (ev) { return !ev.isDefaultPrevented() && !_this.options.disabled && !_this.options.locked && _this.options.opened && ($.contains(_this._header[0], document.activeElement) || document.activeElement === _this._header[0]); },
            run: function (ev, ctx) { _this.close(); _this._header.focus(); }
        });

        //#endregion

        this.refresh(true);
    },
    _destroy: function () {
        this.element.removeClass("gtab g-tab-content ui-widget-content").off(".gtab");
        this._header.remove();
        this.element.gshortcut("remove", "ariasupport_collapse");
        this.element[0].removeEventListener("forceshow", this._forceShowListener, { capture: true });
        this._super();
    },
    _setOptions: function (options) {
        this._super(options);
        this.refresh();
    },
    refresh: function (forced, ev) {
        var _this = this;

        // content
        var content = (this.element.is(".gcontent") || null) && $.content(this.element[0]);
        if (content) {
            this._loaded = content.loaded;
            if (content.loading) this._header.addClass("g-tab-loading").attr('aria-busy','true');
        }

        // userSettings 
        var p = this.element.parent(), t, id = this.options.id || this.element.prop("uid") || this.element.prop("id");
        if (id) { // serverove ASCX contenty (hybrid) maji id tabu ve tvaru "_ctl01_content04_historie" pricemz se cisla nahodne meni, tato rutina se pokousi nalezt nejblizsiho parenta a odstranit vygenerovanou cast id
            var c = $.content(p);
            if (c && id.startsWith(c.element.prop("id") + "_")) id = "@" + id.substr(c.element.prop("id").length + 1);
        }
        this.userSettings = Gordic.Data.Storage.resolve(id ? ["tabs", id] : false, this.element); // internal settings v nadrazenem contentu; pokud je obsahem content, tak jeho menuBar jde do nej.. reseno v attachContent
        if (id) this.element.add(this._header).addHelpContext("tab:" + id);

        // enabled
        this._header.toggleClass("ui-state-disabled", this.options.disabled || false);  //disabled je soucast widgetu
        this.options.opened = this.options.opened && !this.options.disabled && this.options.visible;

        // locked
        this._header.toggleClass("g-tab-locked", this.options.locked || false);



        //groupable
        //group - concealment
        if (this.element.hasClass("ggroupable")) { //update group definition
            this.element.ggroupable("option", "group", this.options.group);
        } else { // create groupable
            this.element.ggroupable({
                group: this.options.group,
                conceal: function (ev, ctx) {
                    var classAct = ctx.conceal ? "addClass" : "removeClass";
                    _this._header[classAct]("concealed");
                    _this.element[classAct]("concealed");
                    //refresh tlačítek - změnila se velikost
                    if (!ctx.conceal) {
                        _this._headerBar.filter(".gtoolbar").gtoolbar("updateFavorites");
                        _this.element.trigger("resize");
                    }
                }
            });
        }


        //headerClass
        if (this._lastHeaderClass != this.options.headerClass) {
            this._header.removeClass(this._lastHeaderClass);
            this._header.addClass(this.options.headerClass);
            this._lastHeaderClass = this.options.headerClass;
        }

        //customMenu - vmaca 29/11/2023 - má cenu řešit až když je opened nebo se načítá
        if (this.options.opened || this._header.is(".g-tab-loading")) {
            if (this.options.menuBar) {
                this.setMenuBar(this.options.menuBar, this.userSettings.sub("menuBar"));
            } else if (this._lastCustomMenuID != this.options.customMenuID) {
                if (this.options.customMenuID) {
                    var cMenu = this.options.customMenuID;
                    cMenu = (cMenu.indexOf(".") >= 0 ? cMenu.split(".") : [null, cMenu]); // rozdeleni na ContentName.CustomMenuID

                    var p = cMenu[0] // nalezeni spravneho contentu, ktery ma nase customMenuID
                        ? $(".gcontent").filter(function () { return this.id == cMenu[0] || this.uid == cMenu[0]; })  // filtr podle nazvu contentu
                        : this.element.parents(".gcontent");                                                          // filtr podle hiearche
                    p = p.filter(function () { return this.content && this.content.customMenus && this.content.customMenus[cMenu[1]]; });
                    if (p.length >= 1) {
                        this.setMenuBar(p[0].content.customMenus[cMenu[1]], this.userSettings.sub("menuBar"));
                        this._lastCustomMenuID = this.options.customMenuID;
                    } else
                        this.setMenuBar(null, null);
                } else {
                    this.setMenuBar(null, null);
                    this._lastCustomMenuID = "";
                }
            }
        }

        // autoload
        if (this.options.autoload) this._ensureContent();

        // visible -- co nejblíže opened, aby neproblikávalo
        this._header.css("display", (this.options.visible || false) ? "" : "none");

        // opened
        if (this.options.opened && (this._header.is(".ui-state-default, .g-tab-closing") || forced === true)) {
            this.element.finish(); this._headerBar.stop();
            this._header.addClass("ui-state-active").removeClass("ui-state-default g-tab-closing")
            this._ensureContent()
                .then(function () {
                    if (_this._loaded === true) {
                        if (forced === true) {
                            _this.element.css('display', '');
                            _this._trigger("opencomplete");
                        } else {
                            _this.element.slideDown(_this.options.animationTimer, function () { _this.element.css('display', ''); }).css("display", ""); //zustava display:"block", ktery zbytecne prebije classy 
                            _this._headerBar.fadeIn(_this.options.animationTimer, function () { _this._trigger("opencomplete"); });
                        }
                         //$(window).resize(); // udalost k prekresleni kde ceho
                        _this.element.resize();
                        if (forced !== true) _this._trigger("open", ev, null);
                    }
                });
        } else if (!this.options.opened && (this._header.is(".ui-state-active:not(.g-tab-closing)") || forced === true)) {
            this.element.finish(); this._headerBar.stop();
            if (forced === true || this.element.hasClass("concealed")) { // sbalit - negraficky - děje se i při vytvoření
                _this.element.hide();
                _this._header.removeClass("ui-state-active g-tab-closing").addClass("ui-state-default");
            } else { // sbalit - graficky - jen když je vidět
                this._header.addClass("g-tab-closing");
                this.element.slideUp(this.options.animationTimer, function () {
                    _this._header.removeClass("ui-state-active g-tab-closing").addClass("ui-state-default");
                });
                this._headerBar.fadeOut(this.options.animationTimer);
            }

            if (forced !== true) this._trigger("close", ev, null);
        }

        if (this._loaded === true) this._header.removeClass("g-tab-loading").removeAttr('aria-busy');

        // title
        if (this.options.title) {
            var h3 = this._header.find(".g-tab-header-text");
            icon = h3.find(".g-tab-header-icon");
            var errorIcon = h3.find(".g-tab-header-error-icon");
            h3.children().detach();
            h3.html(this.options.title).prepend(icon);
            if (errorIcon.length > 0) {
                h3.append(errorIcon);
            }

            // loadingMessage
            if (this._header.hasClass("g-tab-loading") && this.options.loadingMessage)
                h3.append(" " + this.options.loadingMessage);
        }

        // icon
        var icon = "";
        if (this.options.iconLoading && this._header.is(".g-tab-loading,.g-tab-working"))
            icon = "fa fa-fw " + this.options.iconLoading;
        else if (this.options.icon && this.options.locked && this.options.iconOpened === $.gordic.gtab.prototype.options.iconOpened && this.options.icon === $.gordic.gtab.prototype.options.icon)
            icon = "fa fa-fw fa-circle";
        else if (this.options.icon)
            icon = "fa fa-fw " + (this.options.opened && this.options.iconOpened ? this.options.iconOpened : this.options.icon);
        this._header.find(".g-tab-header-icon").attr("class", "g-tab-header-icon " + icon);
        this._header.find(".g-tab-header-text").toggleClass("g-tab-header__empty", !(this.options.title || icon)) 

        //badge
        if (this._badge.hasClass("gbadge")) this._badge.gbadge("destroy");
        if (this.options.badge) this._badge.gbadge(this.options.badge instanceof GObservableObject ? { params: this.options.badge } : this.options.badge);

        // refresh tlacitek (neco se na panelu mohlo vizualne zmenit - label, ikona)
        this._headerBar.filter(".gtoolbar").gtoolbar("updateFavorites");

        //aria + ovladani klavesnici
        if (this.options.opened) {
            this._header.attr("aria-expanded", "true");
            if (this.options.menuBar) this._header.removeAttr("tabindex");
        }
        else if (!this.options.disabled) this._header.attr("tabindex", "0").removeAttr("aria-expanded");
        var elemId = this.element.prop('id')
        if (elemId ) {
            this._header.attr({ 'aria-controls': elemId });
        }

        if (!this.element.attr('aria-labelledby')) {
            this.element.attr({ 'role': this.element.attr('role') || 'region', 'aria-labelledby': this._header.prop('id') });
        }

    },
    _ensureContent: function () {
        if (this._initLoad) return this._initLoad;

        var _this = this;
        var def = $.Deferred();
        var promise = def.promise();
        this._initLoad = promise;
        this._initLoad.always(function () { delete _this._initLoad; });

        if (this._loaded === false && !this._header.is(".g-tab-loading")) {
            var loadParams = this._loadParams = this._loadParams || {};
            var content;
            this._header.addClass("g-tab-loading").attr('aria-busy', 'true');  // obezlicka. Pokud customLoad vola new GContent, nasledujici oncontentinit vyvola refresh a znovu vyvola ensureContent
            if (this._trigger("customLoad", null, this._loadParams) === false) { def.reject(); }  // ===false (AKA isDefaultPrevented) znamena, ze customLoad nechce provest defaultload, ale zavolal bud ajax, nebo gtab.loadComplete
            else if (content = (this.element.is(".gcontent") || null) && $.content(this.element[0])) { // varianta GContent
                content.readyAwait
                    .then(function () {
                        if (content.className && loadParams /*&& content.loaded === false && content.loading === false*/)
                            return content.load(loadParams); // loading, stavy, refresh by melo byt reseno v content.newPromiseCreated, viz. gpanel.attachContent()
                    })
                    .then(def.resolve, def.reject)
                    .always(function () {
                        _this._loaded = content.loaded;
                        if (_this._loaded && !content.className) _this.refresh(); //klientske contenty by musi mit zaktualizovanou hlavicku, jinak visi preloader. Serverove volaji refresh pres udalost.
                    });
            } else { this._loaded = true; def.resolve(); }
            delete this._loadParams;
        }
        else def.resolve();

        return promise;
    },
    setMenuBar: function (menu, userSettings) {
        if (menu == null) {
            this._headerBar.filter(".gtoolbar").gtoolbar("destroy");
        } else {

            if (this.options.allowFullscreen) {
               menu = this._addFullscreenToMenuBar(menu);
            }
            
            this._headerBar.gtoolbar({
                params: menu,
                userSettings: userSettings,
                //NOTE: BMartinek (2020-05-11): I pres to, ze s posledni prestylovavaci akci jsme se v GWA05 techto stylu zbavili, porad se na ne
                //                              chytaji hybridy. Jakmile se vypnou hybridy, pak je mozne toto smazat a asi bude mozne to odstranit
                //                              i z options gtoolbaru.
                favsCssModifiers: {
                    button: "g-button--favorite-tab",
                    text: "g-button__text--tab",
                    icon: " g-button__icon--tab "
                }
            });
            this._headerBar.gdomcontext({ parent: this.element[0] });
        }
    },
    _addFullscreenToMenuBar: function (menu) {
        const _this = this;

        _this.fullscreen = null;
        let autofitMap = []
        _this.fullscreenAction = new GAction({
            name: "tabFullscreen",
            caption: "jres:31750121",
            icon: 'gi-window-full',
            checked: false,
            run: function (ev, ctx) {
                if (_this.fullscreen === null) {
                    _this.fullscreen = GDlg.showModalWindow($.newDiv().gcontent({}))
                        .dialog('maximize', true)
                        .dialog('option', {
                            'noMaximize': true,
                            draggable: false,
                            resizable: false,
                            title: _this.options.title ?? "jres:31750484", //RC 31750484 : Režim celé obrazovky
                        });
                    $.content(_this.fullscreen).menuBar(menu);
                    _this.fullscreen.on('close fullscreentabclose', function () {
                        if (_this.fullscreenAction.checked()) {
                            _this.fullscreenAction.run();
                        }
                    });
                   
                    _this.element.detach().appendTo(_this.fullscreen).trigger("resize");
                    _this.element.find(".gautofit").each((idx, it) => { let opts; autofitMap.push([it, opts = $(it).gautofit("option")]); $(it).gautofit("destroy"); $(it).gautofit($.extend({}, opts, { resizersOnTab: false })) });
                    _this.element.find(".ggrid").each((idx, it) => $(it).ggrid("fitV"));
                    if (autofitMap.length <= 0) { _this.element.height("100%").trigger("resize"); }
                    this.update({
                        icon: 'gi-window-original',
                        caption: 'jres:31750122',
                    }); //RC 31750122 : Ukončit režim celé obrazovky
                    this.checked(true);
                    this.visible(false);
                    _this.element.trigger("resize");
                    _this.element.find(".gautofit").each((idx, it) => { Gordic.ResizeManager.forceRefresh(it); });

                    _this._trigger('fullscreenon', null, {
                        fullscreenElement: _this.fullscreen,
                    });
                } else {
                    this.checked(false);
                    this.visible(true);
                    
                    _this.element.detach();

                    _this.element.css("height", "");
                    _this.element.insertAfter(_this._header);
                    for (const it of autofitMap) {
                        $(it[0]).gautofit("destroy").gautofit(it[1]);
                    }
                    _this.element.trigger("resize");
                    autofitMap = [];
                    _this.element.find(".ggrid").each((idx, it) => $(it).ggrid("fitV"));

                    _this.fullscreen = null;

                    this.update({
                        icon: 'gi-window-full',
                        caption: 'jres:31750121',
                    }); //RC 31750121 : Zobrazit na celou obrazovku

                    _this._trigger('fullscreenoff', null, {
                        fullscreenElement: _this.fullscreen,
                    })
                }
            }
        });
        menu = menu.filter(it => it?.action?.name !== "tabFullscreen"); // odstraneni pokud tam nahodou je)
        menu.push({
            action: _this.fullscreenAction,
            favorite: true,
            captionVisible: "never",
            align: "opposite"
        });
        return menu;
    },
    open: function () {
        if (this.options.opened === true) return;
        this.options.opened = true;
        this.refresh();
    },
    close: function () {
        if (this.options.opened === false) return;
        this.options.opened = false;
        this.refresh();
    },
    show: function () {
        if (this.options.visible === true) return;
        this.options.visible = true;
        this.refresh(true); //true protože nechceme čekat na animace
    },
    hide: function () {
        if (this.options.visible === false) return;
        this.options.visible = false;
        this.refresh(true); //true protože nechceme čekat na animace
    },
    loadComplete: function () {
        this._loaded = true;
        if (this.options.opened) this._header.addClass("g-tab-closing"); // aby se znovu zavolal animovany open
        this.refresh();
    },
    loadCanceled: function () {
        this._loaded = false;
        this._header.removeClass("g-tab-loading").removeAttr('aria-busy');
        this.options.opened = false;
        this.options.autoload = false;  // jinak refresh => ensureContent
        this.refresh();
    },
    load: function (params) {
        this.options.autoload = true;
        if (params) {
            this._loadParams = params;
            this._loaded = false;
            this._header.removeClass("g-tab-loading").removeAttr('aria-busy');
        }
        this.refresh();
    },
    unload: function () {
        this.loadCanceled();
    },
    scrollIntoView: function () {
        if (this._header.length === 0) this.element.get(0).scrollIntoView();
        else this._header.get(0).scrollIntoView();
    },
    _workingHelper: function (working) {
        this._header.toggleClass("g-tab-working", working);

        if (working && !this._contentCover) {
            var pos = this.element.css("position");
            if (pos === "relative" || pos === "absolute") {
                this._contentCover = $("<div class='ui-cover' aria-busy=true><div><i class='ui-preloader'></i></div></div>").appendTo(this.element);
            }
        } else if (!working && this._contentCover) { this._contentCover.remove(); this._contentCover = null; }
    }
});




/* ======================================================= */
/* GInfos */
/* ======================================================= */

$.widget("gordic.ginfobar", {
    options: {
        infos: [],
    },
    _create: function () {
        this.element.addClass("ginfobar ui-helper-clearfix");
        this._refreshInfos();
    },
    _refreshInfos: function () {
        this.element.empty();
        for (var i = 0; i < this.options.infos.length; i++) {
            var data = this.options.infos[i];
            this.add(data.id, data.label, data.value, data.customClass);
        }
    },
    add: function (id, label, value, customClass) {
        this.element.append($("<div data-id='" + id + "' class='ginfobar__item g-state-text'><h3>" + label + "</h3>" + value + "</div>").addClass(customClass));
    },
    remove: function (id) {
        this.element.find("[data-id='" + id + "'").remove();
    },
    value: function (id, value) {
        var cont = this.element.find(".ginfobar__item[data-id='" + id + "'").contents().filter(function () {
            return this.nodeType == 3;
        });
        if (value)
            cont.text(value);
        else
            return cont.text();
    },
});





/* ======================================================= */
/* GFlashPanel */
/* ======================================================= */

$.widget("gordic.gflashpanel", {
    options: {
        id: "",
        customClass: null,
        state: "info", 
        icon: null,
        label: null, // OBSOLETE: pouzijte content
        content: null, 
        noClose: false,
        badge: null,
        isCollapsed: false,
        commandBar: null,
    },
    _create: function () {
        this.element.addClass("gflashpanel g-state-transbackground").attr("data-id", this.options.id).attr("role", "alert").attr("aria-live", "polite");
        this.iconBuilder = Gordic.Utils.IconBuilder.defaultInst;
        this.refresh();
    },
    _destroy: function () {
        this.element.removeClass("gflashpanel g-state-transbackground").attr("data-id", null).attr("role", null).attr("aria-live", null);
    },
    _setOptions: function (options) {
        this.element.removeClass(this.options.customClass);

        this._super(options);

        this.refresh();
    },
    refresh: function () {
        var _this = this;

        if (this.customClass && this.customClass.startsWith("g-state-")) {
            this.options.state = this.customClass.substr(8);
            this.customClass = null;
        }
        this.element.empty().addClass(this.options.customClass).addClass("g-state-" + this.options.state);
        var icon = this.options.icon || (this.options.state ? "g-state-" + this.options.state : null) || null;
        if (icon !== null) $(this.iconBuilder.createIcon(icon, "gflashpanel__icon fa-fw")).appendTo(this.element);
        var badge = this.options.badge;
        if (badge) $.newDiv().appendTo(this.element).gbadge(badge);
        $.newDiv("gflashpanel__content")
            .append(this.options.content || this.options.label)
            .appendTo(this.element)
            .addClass((this.options.isCollapsed ? "gflashpanel__content--collapsed" : ""))
            .click(function () { $(this).toggleClass("gflashpanel__content--collapsed") });
        var commandBar = this.options.commandBar;
        if (commandBar) $.newDiv().appendTo(this.element).gbuttonpanel({ params: commandBar, disableItemHide: true, mode: "link" });
        if (this.options.noClose !== true)
            $(this.iconBuilder.createIcon("gi-window-close", "gflashpanel__close")).click(function (ev) { _this.close(); }).appendTo(this.element);  // nejdriv span, pak text, jinak je float:right dole misto nahore
    },
    close: function () {
        this.element.hide(); 
        this._trigger("close");
        this.element.remove();
    }
});



