"use strict";
$(document).ready(function () {
    $(window).resize(function (e) {  // prepocitani velikosti dialogu pri zmene velikosti okna
        // if (e.type == "resize" && $(e.target).is(".ui-dialog")) return;   // widget resizable, ktery pouziva dialog vyvolava svoje vlastni resize pred dialogresize
        var forms = (e.target === window) ? $(".js-sml:visible") : $(e.target).find(".js-sml:visible").addBack(".js-sml");
        forms.each(function () {
            var w = this.offsetWidth || $(this).width();
            if (w >= (this.getAttribute("data-break-L") || 750)) $(this).removeClass("size-S size-M").addClass("size-L");
            else if (w >= (this.getAttribute("data-break-M") || 500)) $(this).removeClass("size-S size-L").addClass("size-M");
            else $(this).removeClass("size-M size-L").addClass("size-S");
        });
    }).resize();
});
