    var modeClassPrefix = "fvm";
    var modeHideClass = "gform-" + modeClassPrefix + "--hidden";
    var modeActiveClass = "gform-" + modeClassPrefix;
    var modeNoneClass = modeClassPrefix + "-default";
    var modeAutoClass = modeClassPrefix + "-auto";
    var modeReplacementClass = "gfield-mode-generated";
