(function ($) {
    "use strict";

    namespace("Gordic.Prefabs.Field", {
        charCounter: function (max, threshold) {
            return {
                tagByValue: function (value) {
                    max = max || 0;
                    threshold = threshold == null ? Math.max(0, Math.min(max - 10, max * 0.9)) : (threshold || 0);
                    if (typeof value === "string") {
                        if (max === 0) return { text: Gordic.Validators.Length.prototype.lengthFormat(value.length) }
                        else if (value.length > max) return { text: value.length.toString() + " / " + max.toString(), state: "error" }
                        else if (value.length > threshold) return { text: value.length.toString() + " / " + max.toString() }
                    }
                    return null; 
                }
            }
        }
    }, { pure: true });
})(jQuery);




