(function ($) {
    "use strict";

    namespace("Gordic.Forms", {
        Dependency: function (field, value, required, reverseFill, scope) {
            /// <summary>Zavislosti na hodnote jineho policka</summary>
            /// <param name="field" type="string">master policko, na jehoz hodnote zavisime (name, nebo jQuery)</param>
            /// <param name="value" type="string">cast hodnoty master policka, ktera se pouzije pro ziskani hodnoty filtru (napr.: "ixs_fun"). 
            /// $#10; Lze pouzit custom funkci function(masterValue) => thisValue
            /// $#10; Pri nevyplnene hodnote se automaticky zkusi pouzit nazev filtru 
            /// </param>
            /// <param name="required" type="bool">(default=true) zda je vyzadovana hodnota zadaneho policka (zaroven znamena, ze pokud se master zmeni, zavisle policko se vymaze)</param>
            /// <param name="reverseFill" type="function(thisValue, masterField) => masterValue">(default=thisValue) funkce pro plneni prazdneho master policka, pokud nekdo vyplni rovnou zavisle policko</param>
            /// <param name="scope" type="jQuery">element, v nemz se pokousime dohledat policka podle jmena. Vychozi je gform, na kterem toto policko lezi</param>
            $.extend(this, translateParams(arguments, ["field", "value", "required", "reverseFill", "scope"], { value: null, required: false, reverseFill: function (value, masterField) { return value; } }));
            if (!this.field) throw new Error("Gordic.Forms.Dependency musí mít zadán field!");

            this.linked = false;
        },
        _linkDependencies: function (fields) {
            /// <summary>prolinkuje vsechny zavislosti, ktere najde na prvni urovni objektu</summary>
            $(fields).findFields(".gselectbox").each(function () {
                var complexObject = $(this).gfield("option", "serverFilters");
                if (!complexObject || !$.isPlainObject(complexObject)) return;
                for (var k in complexObject)
                    if (complexObject[k] instanceof Gordic.Forms.Dependency)
                        complexObject[k].linkDependency($(this), k);
                //        else if ($.isPlainObject(complexObject[k])) this._linkDependencies(complexObject[k], thisField);  // resolve vnorenych promennych. Zatim zakomentovano, protoze stejne gselectbox._getServerFilters vnorene promenne nevyhodnocuje
            });
        },
        _duplicateDependencyInstances: function (complexObject) {
            if ($.isPlainObject(complexObject))
                for (var k in complexObject)
                    if (complexObject[k] instanceof Gordic.Forms.Dependency) {
                        var oldDep = complexObject[k]; 
                        complexObject[k] = new Gordic.Forms.Dependency(oldDep.field, oldDep.value, oldDep.required, oldDep.reverseFill, oldDep.scope);
                    }
        }
    }, { pure: true });

    $.extend(Gordic.Forms.Dependency.prototype, {
        linkDependency: function (thisField, filterName) {
            /// <summary>prolinkuje zavislost na svuj field (najde instanci zavisleho fieldu, nastavi potrebne onchange, ...)</summary>
            /// <param name="thisField" type="jQuery">zavisly field (predevsim kvuli clear pokud se master zmeni/vymaze)</param>
            if (this.linked === true) return;

            var _this = this;

            var orig = this.field;
            if (typeof this.field === "string") // pokus o nalezeni policka podle jmena
                this.field = (this.scope || thisField.gform()).findFields(this.field);
            if (!this.field || !this.field.length) { this.field = orig; return; } // nepovedlo se prolinkovat

            if (this.value == null && filterName) this.value = filterName;   // nezadane "value" defaultne do nazvu filtru pri linkovani
            var thisUid = thisField.gfield("instance").uuid;

            const fieldchange = function (ev, obj) {
                // MASTER CHANGED
                if (obj.flags.resolveDependency !== false) {  // manual request nebo se master zmenil, protoze jsme ho zmenili my ze slave

                    if (!thisField.hasClass("gfield")) 
                        _this.field.off("fieldchange", fieldchange);
                    else
                        if ((_this.required === true || _this.field.gfield("hasValue")))// master ma novou hodnotu, nebo je prazdny, ale povinny
                            thisField.gfield("clear", { dependencySet: true }); // smazeme SLAVE
                 
                    _this.field.gfield("resetErrors", "dependency"); //.prop("dependencyset" + thisUid, null);;
                }
            };
            this.field.on("fieldchange", fieldchange);

            thisField.on("fieldchange", function (ev, obj) {
                // SLAVE CHANGED
                if (obj.flags.resolveDependency !== false && thisField.gfield("hasValue") && !_this.field.gfield("hasValue")) {  // MASTER je prazdny 
                    var newMasterValue =
                      $.isFunction(_this.reverseFill) ? _this.reverseFill(obj.value, _this.field) : // vlastni funkce pro zpetne volani 
                      $.isArray(obj.value) ? obj.value[0] : obj.value;  // pokud je SLAVE multivalue, pouzijeme jeho prvni hodnotu
                    if (typeof newMasterValue !== "undefined") _this.field.gfield("setValue", newMasterValue, { valid: false, resolveDependency: false });
                }
            });

            this.linked = true;
        },
        getLinkedValue: function () {
            /// <summary>vraci vyslednou vyhodnocenou hodnotu zavislosti (interne se tato funkce binduje do asynchronnich filtru zavislych policek metodou Gordic.Forms._linkDependencies())</summary>
            /// <returns type="Promise"></returns>
            var _this = this;

            if (this.linked === false && this.required)
                throw new Error("LinkDependency: nepodarilo se vyhodnotit povinnou zavislost na fieldu '{0}'. Cilovy field nebyl nalezen v ocekavanem scope."
                    .format(this.field)); // field stale ve string podobe 
            else if (this.linked === false) // pokud neni required, policko nemusi existovat, vratime "prazdny filtr" (ale bez fieldu nemusi odpovidat jeho emptyValue)
                return $.Deferred().resolve(null).promise();
            else if (this.field.hasClass("gfield") === false) // pokud je/bylo linked, ale jiz neni gfield (nekonzistentni stav), vratime chybu 
                return $.Deferred().reject(new GAbortError(25010306)).promise();

            return this.field.gfield("getValueAsync").then(function (masterValue) {
                if (_this.required === true && _this.field.gfield("hasValue") === false) {
                    _this.field.gfield("resetErrors", "dependency").gfield("setError", { message: "jres:25030482", group: "dependency", showOnDisabled: true, stopping: false });  //RC 25030482 : Povinný filtr
                    return $.Deferred().reject().promise();  // failneme ziskavani filtru
                }

                if ($.isFunction(_this.value)) return _this.value(masterValue);  // value funkce => vyhodnotime bez ohledu na typ policka
                if ($.isArray(masterValue)) return masterValue.map(function (it) { return _this.value ? new GStor(it).get(_this.value) : it; });  // multi value policka
                return _this.value ? new GStor(masterValue).get(_this.value) : masterValue; // normalni hodnoty
            });
        }
    });
})(jQuery);

