            if (isElement(item)) { // ELEMENT v gridu (row nebo col)
                if (!item.parentNode) return null;
                if (this.options.navigationMode === "row") {
                    if (item.hasAttribute("data-column-index")) item = item.parentNode;
                    ncoords = { row: parseInt(item.getAttribute("data-row-index")), col: null };
                } else
                    ncoords = { row: parseInt(item.parentNode.getAttribute("data-row-index")), col: parseInt(item.getAttribute("data-column-index")) || 0 };
            } else if (typeof item === "number") {  // INDEX radku a sloupce
                if (this.options.navigationMode === "row") ncoords = { row: item, col: null }
                else ncoords = { row: item, col: typeof col === "string" ? (this.getTC(col) || { index: 0 }).index : (col || 0) }
            } else if (item && typeof item.row !== "undefined") ncoords = item;
            else return;

            // VYPOCET Y-SCROLLU / ZOBRAZENI RADKU
            var vp = this.uiViewPort[0];
            var row = this.uiRows.children(".row[data-row-index=" + ncoords.row + "]"); // prohledani existujiciho seznamu
            if (row.length === 0 || row[0].offsetTop < vp.scrollTop || (row[0].offsetTop + this.options.rowHeight > vp.scrollTop + vp.clientHeight)) { // mimo viditelnou oblast => musime zascrolovat
                // vypocet potrebneho scrollu
                var scrollReq = ncoords.row * this.options.rowHeight;
                var trueHeight = this.uiRows.prop("dataRowsOverflowMode");
                if ((row.length && row[0].offsetTop < vp.scrollTop) || scrollReq < vp.scrollTop || (trueHeight && scrollReq * (this._browserDimensionHardLimit - vp.clientHeight) / (trueHeight - vp.clientHeight) < vp.scrollTop))   // posun nahoru, selected item by mel byt prvni 
                    this.uiViewPort.prop("trueScrollTop", scrollReq);
                else // posun dolu, selected item by mel byt posledni 
                    this.uiViewPort.prop("trueScrollTop", scrollReq - vp.clientHeight + this.options.rowHeight + 1);

                this.refreshRows(true);

                row = this.uiRows.children(".row[data-row-index=" + ncoords.row + "]");  // znovu najdeme nyni jiz zascrollovany element
            }

