            /// <returns type="CellInfo">informace o oznacenem radku/sloupci </returns>
            /// </signature>
            /// <signature>
            /// <summary>Nastavi aktivni radek podle indexu</summary>
            /// <param name="row" type="Number">index radku, ktery se ma vybrat</param>
            /// <param name="col" type="Number">index sloupce, ktery se ma vybrat (viz trueColumns)</param>
