                var meta = this.dataView.getRows(true, r, 1)[0];
                var ci = { row: r, col: current.col };
                if (opts.enabled === true && this.options.rowsEnabled && this.options.rowsEnabled(meta) === false) continue;  // preskoceni disabled radku podle dat
                if (opts.conditionPreselect === false && opts.condition && opts.condition(meta, ci) !== true) continue;  // preskoceni nevhodnych radku podle dat pokud neni potreba preselect (OPTIMALIZACE)

