                var selected = this.dataView.getDataRows(true, "sort").filter(mf);  // virtualy netreba, ty se resi jen pro multi=true se single vyberem nize
                                                                                    // sort je jen naoko, jisty je pouze filtr, sort vrstva neodpovida vizualnimu sortu pokud napriklad dojde k razeni skupin, apod. 
                                                                                    // view se zde asi nepouziva, protoze vyber je stale vyberem i v zavrene skupine/zabalenem stromu. Pouze natvrdo odfiltrovane zaznamy se nezapocitavaji do vyberu
                if (selected.length) return meta ? selected : selected.map(function (item) { return item.data; });
