        _saveExportSettings: function (strategy, settings, defaultSettings) {

            var userSettings = this.options.userSettings;
            if (userSettings) {
                const profileId = this._generateProfileId(this.currentProfile);
                //do not try to save items, which are same as defaultSettings
                for (let key in defaultSettings) {
                    if (JSON.stringify(settings[key]) === JSON.stringify(defaultSettings[key])) {
                        delete settings[key];
                        userSettings.remove(['exportOpts', profileId, key]);
                    }
                }

                //save common parts
                userSettings.set(['exportOpts', profileId], {
                    filename: settings.filename,
                    dataType: settings.dataType,
                    outputType: settings.outputType,
                    withTimestamp: settings.withTimestamp,
                });


                if (strategy.saveOptions) {
                //save selected strategy parts
                    strategy.saveOptions(settings, userSettings?.sub(['exportOpts', profileId]), defaultSettings);
                }

                //remove oldstorage
                this.options.userSettings.remove('exportOptions');                
            }

            return $.when(settings);
        },
