                        var toRemove = ctx.datarow ? ctx.datarow : _this.grid.ggrid("getSelection");
                        _this.grid.ggrid("getView").updateData(toRemove, "delete");

                         //hide hidden column on remove, if hidden column is being removed and there is none other left
