                var pcol = (profile.columns && profile.columns[dcol.name]) || {};
                if (!gfcol) {
                    (profile.columns = (profile.columns || {}))[dcol.name] = {};
                    continue;
                }
                // je treba vyhodnocovat skutecne zmeny proti aktualnimu GridFormatu. Nechceme ulozit co je v gridu, jen by to zkopirovalo vychozi gridformat
                if (gfcol.caption !== dcol.displayCaption) pcol.displayCaption = dcol.displayCaption; else pcol.displayCaption = null;
                if (gfcol.width !== dcol.width) pcol.width = dcol.width; else pcol.width = null;
                if (gfcol.align !== dcol.align && (gfcol.align || dcol.align !== "left")) pcol.align = dcol.align; else pcol.align = null;
                if (gfcol.formatPreset !== dcol.formatPreset) pcol.formatPreset = dcol.formatPreset; else pcol.formatPreset = null;
                if (gfcol.aggregatePreset !== dcol.aggregatePreset) pcol.aggregatePreset = dcol.aggregatePreset; else pcol.aggregatePreset = null;
                if (gfcol.filterVariant !== dcol.filterVariant && dcol.filterVariant !== (gfcol.filter && gfcol.filter[0] && gfcol.filter[0].id)) pcol.filterVariant = dcol.filterVariant; else pcol.filterVariant = null;

                var dgrp = grpsIdx[dcol.name];
