//#region q:\ginis\Development\NET\Gordic.Gui.WebControls\Scripts\gcollapsible.js 

(function ($) {
    "use strict";
    /**
     *@type {JQuery.GCollabsibleOptions}
     */

    $.widget("gordic.gcollapsible", {

        options: {
            isCollapsedHorizontally: false,
            isCollapsedVertically: false,
           // canCollapseHorizontally: false,
           // canCollapseVertically: true
            //expandVertically
            //collapseVerically
            //expandHorizontally
            //collapseHorizontally
        },

        _create: function () {           
            this.options = $.extend({}, this.options);
            this.element.addClass("gcollapsible");
            this.refresh();
        },

        _setOption: function (key, value) {
            //console.log("glink._setOption", arguments);
            this._setCapabilities();
            
            if (key === "isCollapsedHorizontally") {
                if (this.options.canCollapseHorizontally && (value && !this.options.isCollapsedHorizontally || !value && this.options.isCollapsedHorizontally)) {
                    this.toggle("h");
                }
            } else if (key === "isCollapsedVertically") {
                if (this.options.canCollapseVertically && (value && !this.options.isCollapsedVertically || !value && this.options.isCollapsedVertically)) {
                    this.toggle("v");
                }
            }
           
            this._super(key, value);

        },

        _setCapabilities: function () {
            this.element.removeClass("gcollapsible-h gcollapsible-v");

            if (this.options.expandVertically && this.options.collapseVertically && this.options.canCollapseVertically == null)
                this.options.canCollapseVertically = true;

            if (this.options.expandHorizontally && this.options.collapseHorizontally && this.options.canCollapseHorizontally == null)
                this.options.canCollapseHorizontally = true;

            if (this.options.canCollapseHorizontally) {
                this.element.addClass("gcollapsible-h");
            }
            if (this.options.canCollapseVertically) {
                this.element.addClass("gcollapsible-v");
            }
        },

        refresh: function () {
            this._setCapabilities();

            this.element.removeClass("gcollapsible-collapsed-v gcollapsible-expanded-v gcollapsible-collapsed-h gcollapsible-expanded-h");



            if (this.options.canCollapseVertically) {
                if (this.options.isCollapsedVertically) {
                    this.element.addClass("gcollapsible-collapsed-v");
                } else {
                    this.element.addClass("gcollapsible-expanded-v");
                }
            }

            if (this.options.canCollapseHorizontally) {
                if (this.options.isCollapsedHorizontally) {
                    this.element.addClass("gcollapsible-collapsed-h");
                } else {
                    this.element.addClass("gcollapsible-expanded-h");
                }
            }

            
        },

        isCollapsed: function (axis) {
            axis = axis || "v";
            return axis.startsWith("v") ? this.options.isCollapsedVertically : this.options.isCollapsedHorizontally;
        },

        canCollapse: function (axis) {
            axis = axis || "v";
            return axis.startsWith("v") ? this.options.canCollapseHorizontally : this.options.canCollapseVertically;
        },

        collapse: function (axis) {
            axis = axis || "v";
            return axis.startsWith("v") ? this._changeVerticalStateTo("collapsed") : this._changeHorizontalStateTo("collapsed");
        },

        expand: function (axis) {
            axis = axis || "v";
            return axis.startsWith("v") ? this._changeVerticalStateTo("expanded") : this._changeHorizontalStateTo("expanded");
        },

        toggle: function (axis) {
            axis = axis || "v";
            return axis.startsWith("v") ? this.options.isCollapsedVertically ? this._changeVerticalStateTo("expanded") : this._changeVerticalStateTo("collapsed") : this.options.isCollapsedHorizontally ? this._changeHorizontalStateTo("expanded") : this._changeHorizontalStateTo("collapsed");
        },

        /**
         * Changes state of horizontal collapsing
         *
         * @param {"collapsed"|"expanded"}state
         * @returns {JQueryPromise<void>}
         */
        _changeHorizontalStateTo: function (state) {
            return this._changeStateTo(state, "h");
        },

        /**
         * Changes state of horizontal collapsing
         *
         * @param {"collapsed"|"expanded"}state
         * @returns {JQueryPromise<void>}
         */
        _changeVerticalStateTo: function (state) {
            return this._changeStateTo(state, "v");
        },


        _changeStateTo: function (state, axis) {
            
            var def = $.Deferred();
            var axisName = axis === "v" ? "Vertically" : "Horizontally";
            var isCollapsed = axis === "v" ? "isCollapsedVertically" : "isCollapsedHorizontally";
            var eventName = (state === "expanded" ? "expand" : "collapse") + axisName

            if (this.options[isCollapsed] && state.startsWith("e") || !this.options[isCollapsed] && state.startsWith("c")) {
                if (!this._trigger(eventName, null, { promise: def, isCollapsed: this.options[isCollapsed]  })) {
                    def.reject();
                } else {
                    this.options[isCollapsed] = !this.options[isCollapsed];
                    def.resolve();
                }
            } else {
                def.reject();
            }

            this.element.removeClass("gcollapsible-collapsed-" + axis + " gcollapsible-expanded-"+axis);
            this.element.addClass("gcollapsible-" + state + "-" + axis);

            return def.promise();
        },

        destroy: function () {
           
            this.element.removeClass("gcollapsible gcollapsible-h gcollapsible-v gcollapsible-collapsed-v gcollapsible-collapsed-h gcollapsible-expanded-v gcollapsible-expanded-h");
        }
    });

})(jQuery);



//#endregion

//#region q:\ginis\Development\NET\Gordic.Gui.WebControls\Scripts\gautofit.js 

(function ($) {
    "use strict";

    var uuid = 0;
    var GLog;
    $.widget("gordic.gautofit", {
        options: {
            minimalHeight: 250, //todo: sjednotit criticalHeight a minimalHeight, protože to stejne nema smysl.
            maximalHeight: 1000,
            criticalHeight: 200,
            scrollOnCritical: true,
            resizersOnTab: true,
            resizersUserSettingsKey: "autofitresizer",
            //parentElement //.g-sbp-content //.ui-dialog-content
            //belowminimal
            //overminimal
        },

        _setOption: function (key, value) {
            this._superApply(arguments);
            this.refresh();
        },

        _create: function () {
            if (GLog == null) GLog = new Gordic.Diagnostics.GLog({});

            this._superApply(arguments);

            var defaultOptions = { parentElement: [".g-sbp-content", ".gcwpanel", ".ui-dialog-content"] };

            this.element.addClass("gautofit js-autofit js-autofit--active");
            this.options = $.extend({}, defaultOptions, this.options);


            this.elementElement = this.element[0];
            this.originalElementHeight = this.elementElement.clientHeight;

            if (this.options.criticalHeight > this.options.minimalHeight) {
                this.options.criticalHeight = this.options.minimalHeight;
            }

        /*
            this.elementElement.style["height"] = this.options.minimalHeight + "px";//"100%";
            this.elementElement.style["min-height"] = this.options.criticalHeight + "px";
        */


            var _this = this;


            this.parentHeightToReturnTo = [];


            this.isParentObserved = false;
            this.isElementObserved = false;

            this.heightAfterHide = null;
            this.siblings = [];
            this.instanceId = "js-autofit-" + String(uuid++);

            

            this.refresh();
        },


        refresh: function () {
            if (!this.element.hasClass("gautofit")) return;

            var parentElOpt = this.options.parentElement;
            this.initSteps = 3;

            if (typeof parentElOpt === "string") //find closest parent element by selector
                this.parentElement = this.element.closest(parentElOpt);
            else if (Array.isArray(parentElOpt)) { //if multiple string selector, try one by one until one is found
                for (var i = 0, l = parentElOpt.length; i < l; i++) {
                    this.parentElement = typeof parentElOpt[i] == "string" ? this.element.closest(parentElOpt[i]) : $(parentElOpt[i]);
                    if (this.parentElement.length > 0) break;
                }
            }
            else//if it is JQuery or HTMLElement
                this.parentElement = $(this.options.parentElement);



            if (this.parentElement.length === 0) {  //there is no parent element

                this.element.addClass(this.instanceId); //add instance id class to be able to find element, when it is in DOM

                this._observeElement(true);
                this._observeParent(false);

            } else {
                this._observeElement(false);

                this.parentElementElement = this.parentElement[0];



              //  this.parentElementElement.style.overflow = "hidden";
                this._canShrink = false;
                var _this = this;
                if (!this.options.belowminimal) {
                    this.filterPanel = this.parentElement.find(".gcollapsible-v");
                    if (this.filterPanel.length > 0) {

                        this._belowMinimal = function (ev, data) {
                            this._canShrink = false;
                            return _this.filterPanel.gcollapsible("collapse");
                        };

                        this._overMinimal = function (ev, data) {
                            this._canShrink = true;
                            return _this.filterPanel.gcollapsible("expand");
                        };
                        this._canShrink = true;
                    }
                } else {
                    if (!this._belowMinimal) {
                        this._belowMinimal = function () { return this.options.belowminimal().always(function () { _this._canShrink = false; }); };
                        this._overMinimal = function () { return this.options.overminimal().then(function () { _this._canShrink = true; }, function () { _this._canShrink = false; }); };

                        this._canShrink = true;
                    }
                }

                this.canShrink = function () { return this._canShrink && !_this.filterPanel.gcollapsible("isCollapsed"); };

                this._observeParent(true);
            }

            if (this.elementElement) {
                this.elementElement.style["height"] = (this.originalElementHeight === 0 ? this.options.minimalHeight : Math.max(Math.min(this.originalElementHeight, this.options.maximalHeight), this.options.criticalHeight)) + "px";
                this.elementElement.style["min-height"] = this.options.criticalHeight + "px";
            }

            //this.elementElement._autofitLastActiveHeight = this.options.minimalHeight;

        },

        _handleTabResizers: function () {
            let gtab;
            /*if (this.element.hasClass('js-autofit-resizable')) { return false; } //already has resizer*/
            if (this.options.resizersOnTab && (gtab = this.element.closest(".gtab", this.parentElement)).length > 0) {
                if (!this.element.hasClass('js-autofit-resizable')) {
                    this._setActive(false);
                    if (this.parentElement.find(".js-autofit--active").length === 0) {
                        this.parentElementElement.style.overflow = "auto";
                    }
                    var that = this;
                    var triggerResize = Gordic.Utils.debounced(function () { Gordic.ResizeManager.forceRefresh(that.elementElement) }, 100);
                    if (that.options.resizersUserSettingsKey) this.originalElementHeight = parseFloat(gtab.gtab("instance").userSettings?.get(that.options.resizersUserSettingsKey, this.originalElementHeight) ?? this.originalElementHeight);
                    this.element.height(this.originalElementHeight === 0 ? this.options.minimalHeight : Math.max(Math.min(this.originalElementHeight, this.options.maximalHeight), this.options.criticalHeight));
                    const saveHeightToUserSettings = (height) => {
                        if (that.options.resizersUserSettingsKey && gtab.hasClass("gtab")) gtab.gtab("instance").userSettings?.set(that.options.resizersUserSettingsKey, height);
                    }
                    this.element.addClass('js-autofit-resizable').resizable({
                        handles: "s",
                        minHeight: this.options.criticalHeight,
                        resize: function (ev, ui) {
                            this.style.top = '';
                            saveHeightToUserSettings(ui.size.height)
                            triggerResize();
                            //_this.parentElement.scrollTop(_this.parentElementElement.scrollHeight);
                        }
                    }).appendVisibleResizeHandle('s');
                    const handle = this.element.find(".ui-resizable-handle");
                    handle.on("dblclick", function (ev) {
                        const contentRectHeight = that.parentElementElement.getBoundingClientRect().height;
                        const innerHeight = Gordic.ResizeManager.calculateInnerHeight(that.parentElementElement, contentRectHeight);
                        const sizeChange = -Math.floor(contentRectHeight - innerHeight);
                        const newElementHeight = Math.max(Math.floor(that.elementElement.clientHeight - sizeChange) - (handle.height() + 5), that.options.criticalHeight);
                        that.element.css("height", String(newElementHeight) + "px");
                        saveHeightToUserSettings(newElementHeight);
                        that.element.trigger("resize");

                    });
                    if (this.elementElement) {
                        this.elementElement.style["overflow"] = "";
                    }
                }
          return true;
        } else {
            if (this.elementElement) {
                this.elementElement.style["overflow"] = "auto";
            }
        }
      },
        _observeParent: function (observe) {
            var _this = this;

          if (observe && !this.isParentObserved && this.parentElementElement) {
              if (this._handleTabResizers()) return;

                this.parentElement.addClass("js-autofit-parent");
                if (this.options.scrollOnCritical) {
                    var critical = {};
                    critical["gautofitcritical"] = function (ev) {
                        if (!ev.handled && _this.isBelowCritical) {
                            _this.parentElementElement.style.overflow = "auto";
                            ev.handled = true;
                        }
                    };
                    this._on(this.parentElement, critical);

                    var normal = {};
                    normal["gautofitnormal"] = function (ev) {
                        if (!ev.handled && _this.element.is(':visible')) {
                            _this.parentElementElement.style.overflow = "hidden";
                            ev.handled = true;
                        }
                    };                        
                    this._on(this.parentElement, normal);

                }


              Gordic.ResizeManager.observe(this.parentElementElement, {
                    id: "gautofit-parentObserve-" + this.instanceId, // id pro unobserve
                    isActive: function (contentRect, prevContentRect, prevActiveContentRect) {
                        _this._observeSiblings(); //map siblings and force-refresh in case any of them changes.
                        return Math.floor(contentRect.height) !== 0;
                    },
                    execute: this.adjust, // výpočet nové velikosti a provedení resize
                    context: this, // v adjust bude this = this ...
                    // wait: 5
              });

              Gordic.ResizeManager.observe(this.elementElement, {
                  id: "gautofit-elementHidingObserve-" + this.instanceId, // id pro unobserve
                  isActive: function () { return true; },
                  execute: function (current, prev, lastActive) {
                      // console.log(_this.instanceId + ' - elementHidingObserve');
                      var thisIsVisible = _this.element.is(':visible');
                      current.isVisible = thisIsVisible;
                      if (!thisIsVisible) {
                          if (_this.parentElement && !_this.parentElement.find('.js-autofit--active:visible').length > 0) {
                              _this.parentElementElement.style.overflow = "auto";
                          }
                      } else {
                          if (_this.parentElementElement && (!_this.options.scrollOnCritical || _this.options.scrollOnCritical && !_this.isBelowCritical)) {
                              if (_this.parentElementElement.style.overflow !== 'hidden') {
                                  _this.parentElementElement.style.overflow = "hidden";
                              }
                          }
                          if (_this.parentElementElement && (!lastActive || lastActive.isVisible == false)) {
                              setTimeout(function () { Gordic && Gordic.ResizeManager && Gordic.ResizeManager.forceRefresh(_this.parentElementElement) }, 100);
                          }
                      }
                  },
                  wait: 100
              });
            
                this.isParentObserved = true;
            }

            if (!observe && this.isParentObserved && this.parentElementElement) {
                Gordic.ResizeManager.unobserve(this.parentElementElement, "gautofit-parentObserve-" + this.instanceId);
                Gordic.ResizeManager.unobserve(this.elementElement, "gautofit-elementHidingObserve-" + this.instanceId);

                this.isParentObserved = false;
                this.parentElement.removeClass("js-autofit-parent");
            }
        },
        _observeSiblings: function (observe) {

            if (observe !== false) {
                var _this = this;

                var siblings = this.element.siblings(":not(.js-autofit-sibling-" + _this.instanceId + ")");
                if (siblings.length === 0) return;

                siblings.each(function (i) {
                    $(siblings[i]).addClass("js-autofit-sibling-" + _this.instanceId);
                    _this.siblings.push(siblings[i]);
                    setTimeout(function () {
                        Gordic && Gordic.ResizeManager && Gordic.ResizeManager.observe(siblings[i], {
                            id: "gautofit-siblingObserve-" + _this.instanceId,
                            isActive: (function (contentRect, prevContentRect, prevActiveContentRect) {
                                if (_this.parentElementElement != null) {
                                    setTimeout(function () { Gordic && Gordic.ResizeManager && Gordic.ResizeManager.forceRefresh(_this.parentElementElement); },100)
                                }
                                return false;
                            }),
                            execute: $.noop,
                            // wait: 5
                        });
                    }, 1);
                });


            } else {
                var unobserveSibling = function (sibling, instanceId) {
                    setTimeout(function () { Gordic && Gordic.ResizeManager && Gordic.ResizeManager.unobserve(sibling, "gautofit-siblingObserve-" + instanceId); }, 1);
                    $(sibling).removeClass("js-autofit-sibling-" + instanceId);
                };

                for (var i = 0, l = this.siblings.length; i < l; i++) {
                    unobserveSibling(this.siblings[i], this.instanceId);
                }
            }

        },
        _observeElement: function (observe) {
            if (observe && !this.isElementObserved) {
                Gordic.ResizeManager.observe(this.elementElement, {
                    id: "gautofit-elementObserve-" + this.instanceId,
                    isActive: (function (contentRect, prevContentRect, prevActiveContentRect) {
                        return document.getElementsByClassName(this.instanceId).length > 0; // je v DOM ?
                    }),
                    execute: this.adjustInit,
                    context: this,
                });
                this.isElementObserved = true;
            }

            if (!observe && this.isElementObserved) {
                Gordic.ResizeManager.unobserve(this.elementElement, "gautofit-elementObserve-" + this.instanceId);
                this.isElementObserved = false;
            }
        },


        _hasClass: function (el, cn) {
            var classes = el.classList;

            if (classes != null) {
                for (var j = 0; j < classes.length; j++) {
                    if (classes[j] === cn) {
                        return true;
                    }
                }
            } else {
                return $(el).hasClass(cn);
            }
            return false;
        },

      adjust: function (contentRect, globalPrevRect, localPrevRect) {

            if (this._handleTabResizers()) {
              this._observeParent(false);
              this._observeSiblings(false);
              return;
            }


            var contentRectHeight = contentRect.height;
            var currentElementHeight = this.elementElement.clientHeight;

            if (this.elementElement.isConnected === false || this.elementElement.parentNode == null /*|| !this.element.is(':visible')*/) { //pokud by se ajust řešil jen pokud je element visible, způsobí to ošklivé překreslování prvků (animace roztažení na výšku) ... proto to tu být nemůže
                if (!this.isOff) {
                    this.isBelowCritical = true;
                    this.parentElement.trigger("gautofitcritical");
                    this._setActive(false);
                    return;
                }
            } else {
                this._setActive(true);
            }

            localPrevRect = localPrevRect || contentRect;
            globalPrevRect = globalPrevRect || contentRect;

            var sizeChange = Math.floor(localPrevRect.height - contentRectHeight);
            var scrollChange = Math.floor(this.parentElementElement.scrollHeight - contentRectHeight);
            var _this = this;

          sizeChange = sizeChange < 0 && scrollChange < 0 ? (sizeChange > scrollChange? scrollChange : sizeChange) : sizeChange > scrollChange ? sizeChange : scrollChange;

           
            if (sizeChange >= 0) { //if scroll is not present, calc inner empty space
                var innerHeight = Gordic.ResizeManager.calculateInnerHeight(this.parentElementElement, contentRectHeight);
                sizeChange = -Math.floor(contentRectHeight - innerHeight);
            }

            if (this.siblings.length > 0) {
                // find siblings, which are next to current item ... remove whats overflowing over current element's height from sizeChange
                var siblingOverflow = 0;
                var newSiblingHeight = 0;
                var elementOffsetTop = this.elementElement.offsetTop;
                var elementOffsetAndHeight = elementOffsetTop + currentElementHeight;
                for (var i = 0, l = this.siblings.length; i < l; i++) {
                    var sibling = this.siblings[i];
                    var siblingOffset = sibling.offsetTop;
                    if (siblingOffset >= elementOffsetTop && siblingOffset < elementOffsetAndHeight) {
                        newSiblingHeight = elementOffsetTop + sibling.clientHeight - elementOffsetAndHeight;
                        if (newSiblingHeight > siblingOverflow) {
                            siblingOverflow = newSiblingHeight;
                        }
                        
                    }
                }

                if (siblingOverflow > 0) {
                    sizeChange -= siblingOverflow;
                }
            }

            if ((sizeChange === 0 || Math.abs(sizeChange) === 1) && this.heightAfterHide === null) return; //ignore minor changes

            var newElementHeight = Math.floor(currentElementHeight - sizeChange);

            if (this.heightAfterHide !== null) {
                var change = newElementHeight - this.heightAfterHide;

                if (change > 20 || this.bottomElement) {
                    this.parentHeightToReturnTo.push(this.options.minimalHeight + change);

                    this.heightAfterHide = null;
                } else {
                    //size is lowering, even after call of belowminimal
                    if (newElementHeight < this.heightAfterHide) {
                        this.heightAfterHide = newElementHeight;
                    }
                }

            }


            if (newElementHeight < this.options.minimalHeight) {

                //below treshold

                if (!this.isBelowMinimal && this.canShrink() && !this.wasCollapsed && this._belowMinimal) {
                    this._belowMinimal().done(function () {
                       _this.heightAfterHide = newElementHeight - 5;
                    })
                }

                this.isBelowMinimal = true;


                if (newElementHeight < this.options.criticalHeight) {
                    //below critical treshold
                    newElementHeight = this.options.criticalHeight;


                    this.isBelowCritical = true;

                    this._trigger("critical");

                } else {

                    if (this.isBelowCritical) {
                        this.isBelowCritical = false;
                        this._trigger("normal");
                    } else {
                        if (this.element.is(':visible') && this.parentElementElement.style['overflow'] !== 'hidden') {
                            this.parentElementElement.style['overflow'] = 'hidden';
                        } else {
                            //this.parentElementElement.style['overflow'] = 'auto';
                        }
                    }
                }

            } else {


                this.isBelowMinimal = false;

                //over treshold
                if (this.parentHeightToReturnTo.length !== 0 && newElementHeight > this.parentHeightToReturnTo[this.parentHeightToReturnTo.length - 1]) {

                    if (this._overMinimal) {

                        this.parentHeightToReturnTo.pop();

                        this._overMinimal();
                    }
                }


                if (this.isBelowCritical) {
                    this.isBelowCritical = false;
                    this._trigger("normal");
                } else {
                    if (this.element.is(':visible') && this.parentElementElement.style['overflow'] !== 'hidden') {
                        this.parentElementElement.style['overflow'] = 'hidden';
                    } else {
                        //this.parentElementElement.style['overflow'] = 'auto';
                    }
                }
            }

            this.element.css("height", String(newElementHeight) + "px");
            this.wasCollapsed = this.filterPanel.gcollapsible("isCollapsed");

          this.element.trigger("resize");

        },


        adjustInit: function (contentRect, globalPrevRect, localPrevRect) {
            var _this = this;
            setTimeout(function () { _this.refresh(); }, 1);
        },

        _setActive: function (enable) {
            this.isOff = !enable;
            if (this.isOff) {
                this.element.removeClass("js-autofit--active");
            } else {
                this.element.addClass("js-autofit--active");
            }

        },

        destroy: function () {

            if (!this.element.hasClass("gautofit")) return;
            this._observeElement(false);
            this._observeParent(false);
            this._observeSiblings(false);

            if (this.element.hasClass('js-autofit-resizable')) this.element.resizable('destroy');

            this.element.removeClass("gautofit js-autofit js-autofit-resizable js-autofit--active js-autofit-inactive js-autofit-inactive-min");
            this.elementElement.style.height = "";
            this.elementElement.style.minHeight = "";

            if ((this.parentElement?.length ?? 0) > 0) {
                //parent už nemá žádný aktivní autofit jako child -> poslední zhasne
                if (this.parentElement.find(".gautofit").length == 0 && this.parentElement[0].style.overflow === "hidden") {
                    this.parentElement[0].style.overflow = ""; //reset overflow
                    this.parentElement.removeClass("js-autofit-parent");
                }
                this.parentElement.off(".gautofit" + this.instanceId);
            }

            delete this.elementElement;
            delete this.parentElement;
            delete this.parentElementElement;

            this._superApply(arguments);

        }
    });

})(jQuery);



